update classroom_blocks set payload = jsonb_set(payload,'{html}',to_jsonb($h$<div style="max-width:680px;border:1px solid #E6E0D8;border-radius:14px;overflow:hidden;font-size:15px;line-height:1.35"><div style="background:#6B4CC4;color:#fff;padding:7px 12px;font-weight:700">🗣️ Unit 0 Classroom Language</div><div style="padding:10px 12px;background:#fff"><div style="background:#6B4CC4;color:#fff;padding:6px 12px;border-radius:8px;font-weight:700;font-size:15px;margin:14px 0 8px">👩‍🏫 Teacher says:</div><table style="width:100%;border-collapse:collapse"><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top">💬 <b style="color:#5B2FBF">Stand up!</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;color:#6B7280;vertical-align:top">Встань!</td></tr><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top">💬 <b style="color:#5B2FBF">Sit down!</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;color:#6B7280;vertical-align:top">Сядь!</td></tr><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top">💬 <b style="color:#5B2FBF">Open your books!</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;color:#6B7280;vertical-align:top">Открой книги!</td></tr><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top">💬 <b style="color:#5B2FBF">Close your books!</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;color:#6B7280;vertical-align:top">Закрой книги!</td></tr><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top">💬 <b style="color:#5B2FBF">Listen!</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;color:#6B7280;vertical-align:top">Слушай!</td></tr><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top">💬 <b style="color:#5B2FBF">Look!</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;color:#6B7280;vertical-align:top">Смотри!</td></tr><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top">💬 <b style="color:#5B2FBF">Write your name!</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;color:#6B7280;vertical-align:top">Напиши имя!</td></tr><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top">💬 <b style="color:#5B2FBF">Read!</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;color:#6B7280;vertical-align:top">Читай!</td></tr><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top">💬 <b style="color:#5B2FBF">Work in pairs!</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;color:#6B7280;vertical-align:top">Работайте в парах!</td></tr></table><div style="background:#D94A77;color:#fff;padding:6px 12px;border-radius:8px;font-weight:700;font-size:15px;margin:14px 0 8px">🙋 Student says:</div><table style="width:100%;border-collapse:collapse"><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top">💬 <b style="color:#C23A6B">Can you help me?</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;color:#6B7280;vertical-align:top">Можете помочь?</td></tr><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top">💬 <b style="color:#C23A6B">Can you repeat that?</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;color:#6B7280;vertical-align:top">Повторите, пожалуйста?</td></tr><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top">💬 <b style="color:#C23A6B">I'm ready!</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;color:#6B7280;vertical-align:top">Я готов/а!</td></tr><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top">💬 <b style="color:#C23A6B">What's ___ in English?</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;color:#6B7280;vertical-align:top">Как будет ___ по-английски?</td></tr></table></div></div>$h$::text)) where id='02cede85-f3eb-4436-b56f-b0b2ba03e79d';
update classroom_blocks set payload = jsonb_set(payload,'{html}',to_jsonb($h$<div style="max-width:680px;border:1px solid #E6E0D8;border-radius:14px;overflow:hidden;font-size:15px;line-height:1.35"><div style="background:#1E6B3C;color:#fff;padding:7px 12px;font-weight:700">Одежда — Clothes</div><div style="padding:10px 12px;background:#fff"><table style="width:100%;border-collapse:collapse"><tr><td style="padding:6px;vertical-align:top;width:50%"><div style="background:#F2FAF5;border:1px solid #CFE8DA;border-radius:10px;padding:8px 12px"><b style="color:#1F6F45">boots</b><br><span style="color:#6B7280;font-style:italic">сапоги</span></div></td><td style="padding:6px;vertical-align:top;width:50%"><div style="background:#F2FAF5;border:1px solid #CFE8DA;border-radius:10px;padding:8px 12px"><b style="color:#1F6F45">cap</b><br><span style="color:#6B7280;font-style:italic">кепка</span></div></td></tr><tr><td style="padding:6px;vertical-align:top;width:50%"><div style="background:#F2FAF5;border:1px solid #CFE8DA;border-radius:10px;padding:8px 12px"><b style="color:#1F6F45">coat</b><br><span style="color:#6B7280;font-style:italic">пальто</span></div></td><td style="padding:6px;vertical-align:top;width:50%"><div style="background:#F2FAF5;border:1px solid #CFE8DA;border-radius:10px;padding:8px 12px"><b style="color:#1F6F45">dress</b><br><span style="color:#6B7280;font-style:italic">платье</span></div></td></tr><tr><td style="padding:6px;vertical-align:top;width:50%"><div style="background:#F2FAF5;border:1px solid #CFE8DA;border-radius:10px;padding:8px 12px"><b style="color:#1F6F45">hoodie</b><br><span style="color:#6B7280;font-style:italic">худи</span></div></td><td style="padding:6px;vertical-align:top;width:50%"><div style="background:#F2FAF5;border:1px solid #CFE8DA;border-radius:10px;padding:8px 12px"><b style="color:#1F6F45">jacket</b><br><span style="color:#6B7280;font-style:italic">куртка</span></div></td></tr><tr><td style="padding:6px;vertical-align:top;width:50%"><div style="background:#F2FAF5;border:1px solid #CFE8DA;border-radius:10px;padding:8px 12px"><b style="color:#1F6F45">jeans</b><br><span style="color:#6B7280;font-style:italic">джинсы</span></div></td><td style="padding:6px;vertical-align:top;width:50%"><div style="background:#F2FAF5;border:1px solid #CFE8DA;border-radius:10px;padding:8px 12px"><b style="color:#1F6F45">jumper</b><br><span style="color:#6B7280;font-style:italic">джемпер</span></div></td></tr><tr><td style="padding:6px;vertical-align:top;width:50%"><div style="background:#F2FAF5;border:1px solid #CFE8DA;border-radius:10px;padding:8px 12px"><b style="color:#1F6F45">shirt</b><br><span style="color:#6B7280;font-style:italic">рубашка</span></div></td><td style="padding:6px;vertical-align:top;width:50%"><div style="background:#F2FAF5;border:1px solid #CFE8DA;border-radius:10px;padding:8px 12px"><b style="color:#1F6F45">shoes</b><br><span style="color:#6B7280;font-style:italic">обувь</span></div></td></tr><tr><td style="padding:6px;vertical-align:top;width:50%"><div style="background:#F2FAF5;border:1px solid #CFE8DA;border-radius:10px;padding:8px 12px"><b style="color:#1F6F45">skirt</b><br><span style="color:#6B7280;font-style:italic">юбка</span></div></td><td style="padding:6px;vertical-align:top;width:50%"><div style="background:#F2FAF5;border:1px solid #CFE8DA;border-radius:10px;padding:8px 12px"><b style="color:#1F6F45">T-shirt</b><br><span style="color:#6B7280;font-style:italic">футболка</span></div></td></tr><tr><td style="padding:6px;vertical-align:top;width:50%"><div style="background:#F2FAF5;border:1px solid #CFE8DA;border-radius:10px;padding:8px 12px"><b style="color:#1F6F45">tracksuit</b><br><span style="color:#6B7280;font-style:italic">спорткостюм</span></div></td><td style="padding:6px;vertical-align:top;width:50%"><div style="background:#F2FAF5;border:1px solid #CFE8DA;border-radius:10px;padding:8px 12px"><b style="color:#1F6F45">trainers</b><br><span style="color:#6B7280;font-style:italic">кроссовки</span></div></td></tr><tr><td style="padding:6px;vertical-align:top;width:50%"><div style="background:#F2FAF5;border:1px solid #CFE8DA;border-radius:10px;padding:8px 12px"><b style="color:#1F6F45">trousers</b><br><span style="color:#6B7280;font-style:italic">брюки</span></div></td><td style="padding:6px;vertical-align:top;width:50%"><div style="background:#F2FAF5;border:1px solid #CFE8DA;border-radius:10px;padding:8px 12px"><b style="color:#1F6F45">top</b><br><span style="color:#6B7280;font-style:italic">топ</span></div></td></tr></table><p style="margin:12px 0 0;padding:10px 12px;background:#F2FAF5;border-left:4px solid #2E9E6B;border-radius:8px">💡 <b>IS:</b> <i>The T-shirt IS blue.</i> &nbsp; <b style="color:#2F6FB8">ARE:</b> <i>The jeans ARE black.</i> &nbsp; <span style="color:#6B7280">(jeans · shoes · trainers · trousers = множественное число)</span></p></div></div>$h$::text)) where id='b87e6408-3386-4949-95dc-cc18600a7ace';
update classroom_blocks set payload = jsonb_set(payload,'{html}',to_jsonb($h$<div style="max-width:680px;border:1px solid #E6E0D8;border-radius:14px;overflow:hidden;font-size:15px;line-height:1.35"><div style="background:#D94A77;color:#fff;padding:7px 12px;font-weight:700">Sorry about that! — Как извиниться и ответить</div><div style="padding:10px 12px;background:#fff"><div style="background:#D94A77;color:#fff;padding:6px 12px;border-radius:8px;font-weight:700;font-size:15px;margin:14px 0 8px">🤭 A — Apologising (Как извиняться)</div><table style="width:100%;border-collapse:collapse"><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top">💬 <b style="color:#C23A6B">I'm so sorry.</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;color:#6B7280;vertical-align:top">Мне очень жаль.</td></tr><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top">💬 <b style="color:#C23A6B">Sorry about that!</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;color:#6B7280;vertical-align:top">Извини за это!</td></tr><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top">💬 <b style="color:#C23A6B">Sorry, my mistake.</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;color:#6B7280;vertical-align:top">Извини, моя ошибка.</td></tr><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top">💬 <b style="color:#C23A6B">Are you OK?</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;color:#6B7280;vertical-align:top">С тобой всё в порядке?</td></tr></table><div style="background:#6B4CC4;color:#fff;padding:6px 12px;border-radius:8px;font-weight:700;font-size:15px;margin:14px 0 8px">😊 B — Responding (Как отвечать)</div><table style="width:100%;border-collapse:collapse"><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top">💬 <b style="color:#5B2FBF">It's OK.</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;color:#6B7280;vertical-align:top">Всё хорошо.</td></tr><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top">💬 <b style="color:#5B2FBF">That's all right.</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;color:#6B7280;vertical-align:top">Всё в порядке.</td></tr><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top">💬 <b style="color:#5B2FBF">No problem.</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;color:#6B7280;vertical-align:top">Не проблема.</td></tr><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top">💬 <b style="color:#5B2FBF">I'm fine. Thanks!</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;color:#6B7280;vertical-align:top">Я в порядке. Спасибо!</td></tr></table><p style="margin:12px 0 0;padding:10px 12px;background:#FFF8EF;border-left:4px solid #E8A33D;border-radius:8px">👉 <b>A:</b> "Sorry about that!" &nbsp; <b>B:</b> "No problem." &nbsp; <b>A:</b> "Are you OK?" &nbsp; <b>B:</b> "I'm fine. Thanks!"</p></div></div>$h$::text)) where id='2eec0fa5-cca4-4f2f-a715-817d478f8bf9';
update classroom_blocks set payload = jsonb_set(payload,'{html}',to_jsonb($h$<div style="max-width:680px;border:1px solid #E6E0D8;border-radius:14px;overflow:hidden;font-size:15px;line-height:1.35"><div style="background:#E8732A;color:#fff;padding:7px 12px;font-weight:700">Unit 5 Can questions &amp; short answers</div><div style="padding:10px 12px;background:#fff"><p style="margin:0 0 12px">Чтобы задать вопрос с CAN — ставим CAN ПЕРЕД подлежащим. В коротком ответе главный глагол НЕ повторяем!</p><table style="width:100%;border-collapse:collapse"><tr><td style="padding:6px;vertical-align:top;width:50%"><div style="background:#FDF3E7;border:1px solid #E8A33D;border-radius:10px;padding:10px 12px">❓ <b style="color:#B4530F">CAN + subject + infinitive ?</b></div></td><td style="padding:6px;vertical-align:top;width:50%"><div style="background:#FDF3E7;border:1px solid #E8A33D;border-radius:10px;padding:10px 12px">🔁 <b style="color:#B4530F">What CAN + subject + do ?</b></div></td></tr></table><table style="width:100%;border-collapse:collapse"><tr><td style="padding:6px;vertical-align:top;width:50%"><div style="background:#FFF8EF;border:1px solid #E8A33D;border-radius:10px;padding:10px 12px">✅ <b>Yes, I / you / he / she / it / we / they&nbsp; can.</b></div></td><td style="padding:6px;vertical-align:top;width:50%"><div style="background:#FFF8EF;border:1px solid #E8A33D;border-radius:10px;padding:10px 12px">❌ <b>No, I / you / he / she / it / we / they&nbsp; can't.</b></div></td></tr></table><p style="margin:12px 0 0;padding:10px 12px;background:#FFF8EF;border-left:4px solid #E8A33D;border-radius:8px">⚠️ <b style="color:#B4530F">Короткий ответ:</b> "Can she swim?" → "Yes, she CAN!"</p><table style="width:100%;border-collapse:collapse"><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top">✅ <b>Can you swim?</b> — <b>Yes, I can!</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;color:#6B7280;vertical-align:top">— Ты умеешь плавать? — Да!</td></tr><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top">✅ <b>Can he fly?</b> — <b>No, he can't!</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;color:#6B7280;vertical-align:top">— Он умеет летать? — Нет!</td></tr><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top">✅ <b>Can they cook?</b> — <b>Yes, they can!</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;color:#6B7280;vertical-align:top">— Они умеют готовить? — Да!</td></tr><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top">✅ <b>What can Superdug do?</b> — <b>He can run!</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;color:#6B7280;vertical-align:top">— Что умеет Суперпёс? — Он умеет бегать!</td></tr></table></div></div>$h$::text)) where id='29abc5db-36f7-48e8-aa74-9c5688b69e42';
update classroom_blocks set payload = jsonb_set(payload,'{html}',to_jsonb($h$<div style="max-width:680px;border:1px solid #E6E0D8;border-radius:14px;overflow:hidden;font-size:15px;line-height:1.35"><div style="background:#B4530F;color:#fff;padding:7px 12px;font-weight:700">Unit 6 Adverbs of Frequency</div><div style="padding:10px 12px;background:#fff"><p style="margin:0 0 12px">Слова частотности говорят, КАК ЧАСТО что-то происходит. С обычным глаголом — ПЕРЕД ним. С to be — ПОСЛЕ него.</p><table style="width:100%;border-collapse:collapse"><tr><td style="padding:4px;width:20%"><div style="background:#EAF0FB;border:1px solid #2F6FB8;border-radius:10px;padding:8px 6px;text-align:center"><span style="font-size:12px;color:#2F6FB8">0%</span><br><b style="color:#2F6FB8">never</b></div></td><td style="padding:4px;width:20%"><div style="background:#FBEAF2;border:1px solid #D94A77;border-radius:10px;padding:8px 6px;text-align:center"><span style="font-size:12px;color:#D94A77">25%</span><br><b style="color:#D94A77">sometimes</b></div></td><td style="padding:4px;width:20%"><div style="background:#EAF7F0;border:1px solid #2E9E6B;border-radius:10px;padding:8px 6px;text-align:center"><span style="font-size:12px;color:#2E9E6B">50%</span><br><b style="color:#2E9E6B">often</b></div></td><td style="padding:4px;width:20%"><div style="background:#FDF6E3;border:1px solid #C8911B;border-radius:10px;padding:8px 6px;text-align:center"><span style="font-size:12px;color:#C8911B">75%</span><br><b style="color:#C8911B">usually</b></div></td><td style="padding:4px;width:20%"><div style="background:#B4530F;color:#fff;border-radius:10px;padding:8px 6px;text-align:center"><span style="font-size:12px">100%</span><br><b>always</b></div></td></tr></table><table style="width:100%;border-collapse:collapse"><tr><td style="padding:6px;vertical-align:top;width:50%"><div style="background:#FDF3E7;border:1px solid #E8A33D;border-radius:10px;padding:10px 12px"><span style="font-size:13px;color:#B4530F">⚡ Обычный глагол:</span><br><b>I&nbsp; <span style="color:#B4530F">always</span>&nbsp; get up&nbsp; at 7.</b></div></td><td style="padding:6px;vertical-align:top;width:50%"><div style="background:#FDF3E7;border:1px solid #E8A33D;border-radius:10px;padding:10px 12px"><span style="font-size:13px;color:#B4530F">⚡ Глагол to be:</span><br><b>She&nbsp; is&nbsp; <span style="color:#B4530F">often</span>&nbsp; late.</b></div></td></tr></table><table style="width:100%;border-collapse:collapse"><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top">✅ <b>I <span style="color:#B4530F">always</span> have breakfast.</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;color:#6B7280;vertical-align:top">— Я всегда завтракаю.</td></tr><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top">✅ <b>She <span style="color:#B4530F">usually</span> goes to school by bus.</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;color:#6B7280;vertical-align:top">— Она обычно едет на автобусе.</td></tr><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top">✅ <b>He <span style="color:#B4530F">sometimes</span> watches TV.</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;color:#6B7280;vertical-align:top">— Он иногда смотрит телевизор.</td></tr><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top">✅ <b>They <span style="color:#B4530F">never</span> tidy their room.</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;color:#6B7280;vertical-align:top">— Они никогда не убирают комнату.</td></tr><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top">✅ <b>I am <span style="color:#B4530F">often</span> busy on Fridays.</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;color:#6B7280;vertical-align:top">— Я часто занят по пятницам.</td></tr></table></div></div>$h$::text)) where id='413dfb96-4ec6-446d-89eb-f223ad4a1d8b';
update classroom_blocks set payload = jsonb_set(payload,'{html}',to_jsonb($h$<div style="max-width:680px;border:1px solid #E6E0D8;border-radius:14px;overflow:hidden;font-size:15px;line-height:1.35"><div style="background:#D2702A;color:#fff;padding:7px 12px;font-weight:700">✏️ Present Simple — Negative</div><div style="padding:10px 12px;background:#fff"><p style="margin:0 0 12px;padding:10px 12px;background:#FFF8EF;border-left:4px solid #E8A33D;border-radius:8px">Чтобы сказать, что кто-то НЕ делает что-то, используй <b style="color:#C23A1E">DON'T</b> или <b style="color:#C23A1E">DOESN'T</b> + глагол (<span style="color:#C23A6B">без окончания</span>).</p><table style="width:100%;border-collapse:collapse"><tr><td style="padding:6px;vertical-align:top;width:50%"><div style="background:#E08A3C;border:1px solid #D2702A;border-radius:10px;padding:10px 12px"><span style="color:#fff">I / You / We / They&nbsp; + &nbsp;<b style="font-size:19px">DON'T</b>&nbsp; + verb</span></div></td><td style="padding:6px;vertical-align:top;width:50%"><div style="background:#B4530F;border:1px solid #B4530F;border-radius:10px;padding:10px 12px"><span style="color:#fff">He / She / It&nbsp; + &nbsp;<b style="font-size:19px">DOESN'T</b>&nbsp; + verb</span></div></td></tr></table><p style="margin:12px 0 0"><b style="color:#B4530F">⚠️ После doesn't — глагол БЕЗ окончания -s!</b> &nbsp; <span style="color:#C23A1E">She doesn't likeS ✗</span> → <span style="color:#1F6F45">She doesn't like ✓</span></p><table style="width:100%;border-collapse:collapse"><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top">✅ <b>I don't get up early.</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;color:#6B7280;vertical-align:top">Я не встаю рано.</td></tr><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top">✅ <b>They don't eat a lot.</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;color:#6B7280;vertical-align:top">Они не едят много.</td></tr><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top">✅ <b>We don't live in London.</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;color:#6B7280;vertical-align:top">Мы не живём в Лондоне.</td></tr><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top">✅ <b>She doesn't go to school at weekends.</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;color:#6B7280;vertical-align:top">Она не ходит в школу по выходным.</td></tr><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top">✅ <b>He doesn't like cats.</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;color:#6B7280;vertical-align:top">Ему не нравятся кошки.</td></tr></table></div></div>$h$::text)) where id='2ce1c561-8c7c-4e18-bace-de7b2ec136c8';
update classroom_blocks set payload = jsonb_set(payload,'{html}',to_jsonb($h$<div style="max-width:680px;border:1px solid #E6E0D8;border-radius:14px;overflow:hidden;font-size:15px;line-height:1.35"><div style="background:#2E9E6B;color:#fff;padding:7px 12px;font-weight:700">📚 Unit 8 Спорт</div><div style="padding:10px 12px;background:#fff"><table style="width:100%;border-collapse:collapse"><tr><td style="padding:6px;vertical-align:top;width:50%"><div style="background:#F2FAF5;border:1px solid #CFE8DA;border-radius:10px;padding:8px 12px">🏸 <b style="color:#2F6FB8">badminton</b><br><span style="color:#6B7280">бадминтон</span></div></td><td style="padding:6px;vertical-align:top;width:50%"><div style="background:#F2FAF5;border:1px solid #CFE8DA;border-radius:10px;padding:8px 12px">🏀 <b style="color:#2F6FB8">basketball</b><br><span style="color:#6B7280">баскетбол</span></div></td></tr><tr><td style="padding:6px;vertical-align:top;width:50%"><div style="background:#F2FAF5;border:1px solid #CFE8DA;border-radius:10px;padding:8px 12px">🚴 <b style="color:#2F6FB8">cycling</b><br><span style="color:#6B7280">езда на велосипеде</span></div></td><td style="padding:6px;vertical-align:top;width:50%"><div style="background:#F2FAF5;border:1px solid #CFE8DA;border-radius:10px;padding:8px 12px">⚽ <b style="color:#2F6FB8">football</b><br><span style="color:#6B7280">футбол</span></div></td></tr><tr><td style="padding:6px;vertical-align:top;width:50%"><div style="background:#F2FAF5;border:1px solid #CFE8DA;border-radius:10px;padding:8px 12px">🏒 <b style="color:#2F6FB8">hockey</b><br><span style="color:#6B7280">хоккей</span></div></td><td style="padding:6px;vertical-align:top;width:50%"><div style="background:#F2FAF5;border:1px solid #CFE8DA;border-radius:10px;padding:8px 12px">⛸️ <b style="color:#2F6FB8">ice-skating</b><br><span style="color:#6B7280">коньки</span></div></td></tr><tr><td style="padding:6px;vertical-align:top;width:50%"><div style="background:#F2FAF5;border:1px solid #CFE8DA;border-radius:10px;padding:8px 12px">🛼 <b style="color:#2F6FB8">roller skating</b><br><span style="color:#6B7280">ролики</span></div></td><td style="padding:6px;vertical-align:top;width:50%"><div style="background:#F2FAF5;border:1px solid #CFE8DA;border-radius:10px;padding:8px 12px">⛵ <b style="color:#2F6FB8">sailing</b><br><span style="color:#6B7280">парусный спорт</span></div></td></tr><tr><td style="padding:6px;vertical-align:top;width:50%"><div style="background:#F2FAF5;border:1px solid #CFE8DA;border-radius:10px;padding:8px 12px">🛹 <b style="color:#2F6FB8">skateboarding</b><br><span style="color:#6B7280">скейтборд</span></div></td><td style="padding:6px;vertical-align:top;width:50%"><div style="background:#F2FAF5;border:1px solid #CFE8DA;border-radius:10px;padding:8px 12px">⛷️ <b style="color:#2F6FB8">skiing</b><br><span style="color:#6B7280">лыжный спорт</span></div></td></tr><tr><td style="padding:6px;vertical-align:top;width:50%"><div style="background:#F2FAF5;border:1px solid #CFE8DA;border-radius:10px;padding:8px 12px">🏊 <b style="color:#2F6FB8">swimming</b><br><span style="color:#6B7280">плавание</span></div></td><td style="padding:6px;vertical-align:top;width:50%"><div style="background:#F2FAF5;border:1px solid #CFE8DA;border-radius:10px;padding:8px 12px">🏓 <b style="color:#2F6FB8">table tennis</b><br><span style="color:#6B7280">настольный теннис</span></div></td></tr><tr><td style="padding:6px;vertical-align:top;width:50%"><div style="background:#F2FAF5;border:1px solid #CFE8DA;border-radius:10px;padding:8px 12px">🥋 <b style="color:#2F6FB8">taekwondo</b><br><span style="color:#6B7280">тхэквондо</span></div></td><td style="padding:6px;vertical-align:top;width:50%"><div style="background:#F2FAF5;border:1px solid #CFE8DA;border-radius:10px;padding:8px 12px">🎾 <b style="color:#2F6FB8">tennis</b><br><span style="color:#6B7280">теннис</span></div></td></tr><tr><td style="padding:6px;vertical-align:top;width:50%"><div style="background:#F2FAF5;border:1px solid #CFE8DA;border-radius:10px;padding:8px 12px">🏐 <b style="color:#2F6FB8">volleyball</b><br><span style="color:#6B7280">волейбол</span></div></td><td style="padding:6px;vertical-align:top;width:50%"><div style="background:#F2FAF5;border:1px solid #CFE8DA;border-radius:10px;padding:8px 12px">🏄 <b style="color:#2F6FB8">windsurfing</b><br><span style="color:#6B7280">виндсёрфинг</span></div></td></tr></table><table style="width:100%;border-collapse:collapse;margin-top:10px"><tr><td style="padding:5px;vertical-align:top;width:33%"><div style="background:#FDF0E0;border:1px solid #E8821E;border-radius:10px;padding:10px 12px"><span style="background:#E8821E;color:#fff;border-radius:7px;padding:3px 12px;font-weight:700">DO</span><div style="margin-top:8px;color:#E8821E">taekwondo<br>exercise</div></div></td><td style="padding:5px;vertical-align:top;width:33%"><div style="background:#EAF0FB;border:1px solid #2F6FB8;border-radius:10px;padding:10px 12px"><span style="background:#2F6FB8;color:#fff;border-radius:7px;padding:3px 12px;font-weight:700">GO</span><div style="margin-top:8px;color:#2F6FB8">swimming · cycling · skiing<br>sailing · skateboarding<br>ice-skating · roller skating<br>windsurfing</div></div></td><td style="padding:5px;vertical-align:top;width:33%"><div style="background:#EAF7F0;border:1px solid #2E9E6B;border-radius:10px;padding:10px 12px"><span style="background:#2E9E6B;color:#fff;border-radius:7px;padding:3px 12px;font-weight:700">PLAY</span><div style="margin-top:8px;color:#2E9E6B">basketball · football<br>hockey · volleyball<br>tennis · badminton<br>table tennis</div></div></td></tr></table></div></div>$h$::text)) where id='ad529d68-e79c-4ed2-9141-182186343387';
update classroom_blocks set payload = jsonb_set(payload,'{html}',to_jsonb($h$<div style="max-width:680px;border:1px solid #E6E0D8;border-radius:14px;overflow:hidden;font-size:15px;line-height:1.35"><div style="background:#E8732A;color:#fff;padding:7px 12px;font-weight:700">📌 Adjective Word Order — Порядок прилагательных</div><div style="padding:10px 12px;background:#fff"><p style="margin:0 0 12px;padding:10px 12px;background:#FFF8EF;border-left:4px solid #E8A33D;border-radius:8px">📖 Когда описываем предмет, прилагательные идут в определённом порядке: сначала <span style="color:#2F6FB8">размер / мнение</span>, потом <span style="color:#E8821E">цвет</span>, потом <span style="color:#1F6F45">предмет</span>. Перед гласным звуком (a, e, i, o, u) используем <span style="color:#7A3FBF">an</span>, а не <span style="color:#7A3FBF">a</span>.</p><div style="background:#FFF8EF;border:1px solid #E8A33D;border-radius:10px;padding:10px 12px"><b style="color:#B4530F">✅ Формула:</b><div style="text-align:center;font-size:20px;font-weight:700;margin-top:6px"><span style="color:#7A3FBF">a / an</span> + <span style="color:#2F6FB8">размер / мнение</span> + <span style="color:#E8821E">цвет</span> + <span style="color:#1F6F45">предмет</span></div></div><table style="width:100%;border-collapse:collapse"><tr><td style="padding:6px;vertical-align:top;width:50%"><div style="background:#EAF4FD;border:1px solid #9CC7E8;border-radius:10px;padding:10px 12px"><b style="color:#2F6FB8">🏷️ Размер / Мнение:</b><ul style="margin:6px 0 0;padding-left:20px"><li>big (большой) · small (маленький)</li><li>long (длинный) · short (короткий)</li><li>old (старый) · new (новый)</li><li>beautiful (красивый) · ugly (некрасивый)</li></ul></div></td><td style="padding:6px;vertical-align:top;width:50%"><div style="background:#F7EFFB;border:1px solid #C9A7E0;border-radius:10px;padding:10px 12px"><b style="color:#7A3FBF">⚠️ a или an?</b><br><b style="color:#7A3FBF">a</b> — перед согласным звуком: a big, a small, a new<br><b style="color:#7A3FBF">an</b> — перед гласным звуком: an ugly, an old</div></td></tr></table><p style="margin:12px 0 4px"><b style="color:#B4530F">📝 Примеры:</b></p><table style="width:100%;border-collapse:collapse"><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top">✅ <b><span style="color:#7A3FBF">a</span> <span style="color:#2F6FB8">big</span> <span style="color:#E8821E">blue</span> <span style="color:#1F6F45">plane</span></b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;color:#6B7280;vertical-align:top">— большой синий самолёт</td></tr><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top">✅ <b><span style="color:#7A3FBF">a</span> <span style="color:#2F6FB8">small</span> <span style="color:#E8821E">orange</span> <span style="color:#1F6F45">plane</span></b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;color:#6B7280;vertical-align:top">— маленький оранж. самолёт</td></tr><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top">✅ <b><span style="color:#7A3FBF">an</span> <span style="color:#2F6FB8">ugly</span> <span style="color:#E8821E">black</span> <span style="color:#1F6F45">kite</span></b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;color:#6B7280;vertical-align:top">— некрасивый чёрный змей</td></tr><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top">✅ <b><span style="color:#7A3FBF">a</span> <span style="color:#2F6FB8">beautiful</span> <span style="color:#E8821E">pink</span> <span style="color:#1F6F45">kite</span></b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;color:#6B7280;vertical-align:top">— красивый розовый змей</td></tr><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top">✅ <b><span style="color:#7A3FBF">a</span> <span style="color:#2F6FB8">long</span> <span style="color:#E8821E">yellow</span> <span style="color:#1F6F45">train</span></b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;color:#6B7280;vertical-align:top">— длинный жёлтый поезд</td></tr><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top">✅ <b><span style="color:#7A3FBF">an</span> <span style="color:#2F6FB8">old</span> <span style="color:#E8821E">pink</span> <span style="color:#1F6F45">bike</span></b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;color:#6B7280;vertical-align:top">— старый розовый велосипед</td></tr><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top">✅ <b><span style="color:#7A3FBF">a</span> <span style="color:#2F6FB8">new</span> <span style="color:#E8821E">purple</span> <span style="color:#1F6F45">bike</span></b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;color:#6B7280;vertical-align:top">— новый фиолетовый велосипед</td></tr></table><p style="margin:10px 0 0;font-size:13px;color:#6B7280">Цвета: <span style="color:#7A3FBF">■</span> артикль <span style="color:#2F6FB8">■</span> размер/мнение <span style="color:#E8821E">■</span> цвет <span style="color:#1F6F45">■</span> предмет</p></div></div>$h$::text)) where id='dccbc7be-82fb-458a-a9f8-502a6fb3482d';
update classroom_blocks set payload = jsonb_set(payload,'{html}',to_jsonb($h$<div style="max-width:680px;border:1px solid #E6E0D8;border-radius:14px;overflow:hidden;font-size:15px;line-height:1.35"><div style="background:#F2A423;color:#fff;padding:7px 12px;font-weight:700">📌 Grammar — I like / I don't like</div><div style="padding:10px 12px;background:#fff"><p style="margin:0 0 12px;padding:10px 12px;background:#FFF8EF;border-left:4px solid #E8A33D;border-radius:8px">📖 Чтобы сказать, что тебе <span style="color:#1F6F45">нравится</span> что-то, говори: <b style="color:#1F6F45">I like ...</b> Если <span style="color:#C23A1E">не нравится</span>: <b style="color:#C23A1E">I don't like ...</b> Спроси друга: <b style="color:#2F6FB8">What about you?</b></p><table style="width:100%;border-collapse:collapse"><tr><td style="padding:6px;vertical-align:top;width:50%"><div style="background:#EFFAF3;border:1px solid #2E9E6B;border-radius:10px;padding:10px 12px"><div style="text-align:center">❤️<div style="font-size:21px;font-weight:700;color:#1F6F45">I like + [pets]!</div><div style="color:#6B7280">= Мне нравится!</div><hr style="border:none;border-top:1px solid #333;margin:8px 0">🐱 I like cats! &nbsp; 🐸 I like frogs!</div></div></td><td style="padding:6px;vertical-align:top;width:50%"><div style="background:#FDEFEF;border:1px solid #D94A3A;border-radius:10px;padding:10px 12px"><div style="text-align:center">🙅<div style="font-size:21px;font-weight:700;color:#D94A3A">I don't like + [pets]!</div><div style="color:#6B7280">= Мне не нравится!</div><hr style="border:none;border-top:1px solid #333;margin:8px 0">🕷️ I don't like spiders! &nbsp; 🐭 I don't like mice!</div></div></td></tr></table><p style="margin:12px 0 0;padding:10px 12px;background:#EAF4FD;border:1px solid #2F6FB8;border-radius:8px">🤔 <b style="color:#2F6FB8">What about you?</b> = А ты? &nbsp; Ответ: <span style="color:#1F6F45">I like frogs, too!</span> / <span style="color:#C23A1E">I don't like frogs!</span></p><p style="margin:12px 0 4px"><b style="color:#B4530F">📝 Examples / Примеры:</b></p><table style="width:100%;border-collapse:collapse"><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top">❤️ <b>I like cats.</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;color:#6B7280;vertical-align:top">— Мне нравятся кошки.</td></tr><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top">❤️ <b>I like dogs.</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;color:#6B7280;vertical-align:top">— Мне нравятся собаки.</td></tr><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top">🙅 <b>I don't like spiders.</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;color:#6B7280;vertical-align:top">— Мне не нравятся пауки.</td></tr><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top">🤔 <b>I like frogs. What about you?</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;color:#6B7280;vertical-align:top">— А ты?</td></tr><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top">👍 <b>I like frogs, too!</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;color:#6B7280;vertical-align:top">— Мне тоже!</td></tr><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top">🙅 <b>I don't like big frogs!</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;color:#6B7280;vertical-align:top">— Не нравятся большие лягушки!</td></tr></table><p style="margin:12px 0 0;padding:10px 12px;background:#FFF8EF;border-left:4px solid #E8A33D;border-radius:8px">⚠️ <b style="color:#B4530F">Запомни:</b> <b style="color:#C23A1E">don't</b> = do not (сокращение). Говори: I <b style="color:#C23A1E">don't</b> like, а НЕ "I no like"!</p></div></div>$h$::text)) where id='859f2e11-eab7-40be-98b1-42fa0a1dbb38';
update classroom_blocks set payload = jsonb_set(payload,'{html}',to_jsonb($h$<div style="max-width:680px;border:1px solid #E6E0D8;border-radius:14px;overflow:hidden;font-size:15px;line-height:1.35"><div style="background:#E8732A;color:#fff;padding:7px 12px;font-weight:700">📖 Phonics — OW &amp; O_E</div><div style="padding:10px 12px;background:#fff"><table style="width:100%;border-collapse:collapse"><tr><td style="padding:6px;vertical-align:top;width:50%"><div style="background:#fff;border:1px solid #E6E0D8;border-radius:12px;padding:16px;text-align:center"><div style="font-size:34px;font-weight:700;color:#2F6FB8">OW</div><div style="color:#6B7280;font-style:italic">/əʊ/</div><hr style="border:none;border-top:1px solid #E6E0D8;margin:12px 0"><div style="font-size:34px">❄️</div><div style="font-weight:700;font-size:18px;margin-top:6px">snow</div><div style="color:#6B7280">‘снег’</div></div></td><td style="padding:6px;vertical-align:top;width:50%"><div style="background:#fff;border:1px solid #E6E0D8;border-radius:12px;padding:16px;text-align:center"><div style="font-size:34px;font-weight:700;color:#2F6FB8">O_E</div><div style="color:#6B7280;font-style:italic">/əʊ/</div><hr style="border:none;border-top:1px solid #E6E0D8;margin:12px 0"><div style="font-size:34px">🦴</div><div style="font-weight:700;font-size:18px;margin-top:6px">bone</div><div style="color:#6B7280">‘кость’</div></div></td></tr></table></div></div>$h$::text)) where id='352fb542-bed5-4e4a-8fc1-4a4a66460135';
update classroom_blocks set payload = jsonb_set(payload,'{html}',to_jsonb($h$<div style="max-width:680px;border:1px solid #E6E0D8;border-radius:14px;overflow:hidden;font-size:15px;line-height:1.35"><div style="background:#F2A423;color:#fff;padding:7px 12px;font-weight:700">📝 Grammar 1 — There's … / There are …</div><div style="padding:10px 12px;background:#fff"><p style="margin:0 0 12px;padding:10px 12px;background:#FFF8EF;border-left:4px solid #E8A33D;border-radius:8px">📖 Чтобы сказать, что где-то что-то ЕСТЬ: <b style="color:#1F6F45">There's</b> (= there is) → 1 предмет, <b style="color:#2F6FB8">There are</b> → несколько.</p><table style="width:100%;border-collapse:collapse"><tr><td style="padding:6px;vertical-align:top;width:50%"><div style="background:#EFFAF3;border:1px solid #2E9E6B;border-radius:10px;padding:10px 12px"><div style="text-align:center"><span style="color:#C23A1E;font-size:13px;font-weight:700">1️⃣ ОДИН предмет</span><div style="font-size:17px;font-weight:700;color:#1F6F45;margin-top:4px">There's + a + <i>[предмет]</i> + in the <i>[комната]</i></div><hr style="border:none;border-top:1px solid #333;margin:8px 0"><b>There's a fish in the hall.</b><div style="color:#6B7280">В прихожей рыба.</div></div></div></td><td style="padding:6px;vertical-align:top;width:50%"><div style="background:#EAF4FD;border:1px solid #2F6FB8;border-radius:10px;padding:10px 12px"><div style="text-align:center"><span style="color:#C23A1E;font-size:13px;font-weight:700">2️⃣+ НЕСКОЛЬКО</span><div style="font-size:17px;font-weight:700;color:#2F6FB8;margin-top:4px">There are + <i>[кол-во]</i> + <i>[предметы]</i> + in the <i>[комната]</i></div><hr style="border:none;border-top:1px solid #333;margin:8px 0"><b>There are three fish in the kitchen.</b><div style="color:#6B7280">На кухне три рыбы.</div></div></div></td></tr></table><p style="margin:12px 0 4px"><b style="color:#B4530F">📝 Примеры:</b></p><table style="width:100%;border-collapse:collapse"><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top">🟢 <b>There's a fish in the hall.</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;color:#6B7280;vertical-align:top">— В прихожей рыба.</td></tr><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top">🟢 <b>There's a spider in the cellar.</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;color:#6B7280;vertical-align:top">— В подвале паук.</td></tr><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top">🔵 <b>There are two fish in the living room.</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;color:#6B7280;vertical-align:top">— В гостиной две рыбы.</td></tr><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top">🔵 <b>There are three fish in the kitchen.</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;color:#6B7280;vertical-align:top">— На кухне три рыбы.</td></tr><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top">🔵 <b>There are four fish in the dining room.</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;color:#6B7280;vertical-align:top">— В столовой четыре рыбы.</td></tr></table><p style="margin:12px 0 0;padding:10px 12px;background:#FFF8EF;border-left:4px solid #E8A33D;border-radius:8px">⚠️ <b style="color:#1F6F45">There's</b> = There is</p></div></div>$h$::text)) where id='790596b9-6aef-49ef-b03c-ed1df5ed4d9a';
update classroom_blocks set payload = jsonb_set(payload,'{html}',to_jsonb($h$<div style="max-width:680px;border:1px solid #E6E0D8;border-radius:14px;overflow:hidden;font-size:15px;line-height:1.35"><div style="background:#F2A423;color:#fff;padding:7px 12px;font-weight:700">📝 Grammar 2 — Is he/she wearing …?</div><div style="padding:10px 12px;background:#fff"><p style="margin:0 0 12px">📖 Чтобы спросить, что кто-то сейчас носит: <b style="color:#C23A1E">Is he/she wearing …?</b> (Present Continuous вопрос).</p><div style="background:#EFFAF3;border:1px solid #2E9E6B;border-radius:10px;padding:10px 12px"><div style="text-align:center"><span style="color:#C23A6B;font-size:13px;font-weight:700">❓ Формула вопроса</span><div style="font-size:20px;font-weight:700;margin-top:4px"><span style="color:#C23A1E">Is he/she wearing</span> + <i>a</i> + <i>[предмет одежды]</i>?</div><hr style="border:none;border-top:1px solid #9CC7E8;margin:8px 0"><div style="color:#1F6F45;font-weight:700">✅ Yes, he is. / Yes, she is.</div><div style="color:#C23A1E;font-weight:700">❌ No, he isn't. / No, she isn't.</div></div></div><p style="margin:12px 0 4px"><b style="color:#B4530F">📝 Примеры:</b></p><table style="width:100%;border-collapse:collapse"><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top">🟢 <b>Is he wearing a red hat? — No, he isn't.</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;color:#6B7280;vertical-align:top">— Он носит красную шляпу? — Нет.</td></tr><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top">🟢 <b>Is he wearing a blue hat? — Yes, he is.</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;color:#6B7280;vertical-align:top">— Он носит синюю шляпу? — Да.</td></tr><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top">🔵 <b>Is she wearing a yellow T-shirt?</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;color:#6B7280;vertical-align:top">— Она носит жёлтую футболку?</td></tr><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top">🔵 <b>Jim's wearing a blue hat.</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;color:#6B7280;vertical-align:top">— Джим носит синюю шляпу.</td></tr></table><p style="margin:12px 0 0;padding:10px 12px;background:#FFF8EF;border-left:4px solid #E8A33D;border-radius:8px">⚠️ <b style="color:#C23A1E">isn't</b> = is not. &nbsp; <b style="color:#E8821E">wearing</b> = wear + <b style="color:#2F6FB8">-ing</b> (сейчас на нём/ней надето)</p></div></div>$h$::text)) where id='3aa9ec2c-0d68-4281-91de-3453fd4de5f5';
update classroom_blocks set payload = jsonb_set(payload,'{html}',to_jsonb($h$<div style="max-width:680px;border:1px solid #E6E0D8;border-radius:14px;overflow:hidden;font-size:15px;line-height:1.35"><div style="background:#F2A423;color:#fff;padding:7px 12px;font-weight:700">📝 Grammar 2 — Can you …?</div><div style="padding:10px 12px;background:#fff"><p style="margin:0 0 12px">📖 Чтобы спросить, умеет ли кто-то что-то делать: <b style="color:#C23A1E">Can you …?</b> — Ты умеешь …?</p><div style="background:#EFFAF3;border:1px solid #2E9E6B;border-radius:10px;padding:10px 12px"><div style="text-align:center"><span style="color:#C23A6B;font-size:13px;font-weight:700">❓ Формула вопроса</span><div style="font-size:20px;font-weight:700;margin-top:4px"><span style="color:#C23A1E">Can you</span> + <i>[действие]</i>?</div><hr style="border:none;border-top:1px solid #9CC7E8;margin:8px 0"><span style="color:#1F6F45;font-weight:700">✅ Yes, I can.</span> <span style="color:#6B7280">— Да, умею.</span> &nbsp;&nbsp; <span style="color:#C23A1E;font-weight:700">❌ No, I can't.</span> <span style="color:#6B7280">— Нет, не умею.</span></div></div><p style="margin:12px 0 4px"><b style="color:#B4530F">📝 Примеры:</b></p><table style="width:100%;border-collapse:collapse"><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top">🟢 <b>Can you cook? — Yes, I can.</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;color:#6B7280;vertical-align:top">— Ты умеешь готовить? — Да.</td></tr><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top">🔴 <b>Can you draw? — No, I can't.</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;color:#6B7280;vertical-align:top">— Ты умеешь рисовать? — Нет.</td></tr><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top">🔴 <b>Can you fly? — No, I can't.</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;color:#6B7280;vertical-align:top">— Ты умеешь летать? — Нет.</td></tr><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top">🟢 <b>Can you play tennis? — Yes, I can.</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;color:#6B7280;vertical-align:top">— Ты умеешь играть в теннис? — Да.</td></tr><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top">🟢 <b>Can you ride a bike? — Yes, I can.</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;color:#6B7280;vertical-align:top">— Ты умеешь кататься на велике? — Да.</td></tr></table></div></div>$h$::text)) where id='8dbf4ba4-91ec-417f-88ca-dde90123646e';
update classroom_blocks set payload = jsonb_set(payload,'{html}',to_jsonb($h$<div style="max-width:680px;border:1px solid #E6E0D8;border-radius:14px;overflow:hidden;font-size:15px;line-height:1.35"><div style="background:#6B4CC4;color:#fff;padding:7px 12px;font-weight:700">Key Phrases: "The Burglars" (1/2)</div><div style="padding:10px 12px;background:#fff"><div style="background:#F6EFFA;border:1px solid #C9A7E0;border-left:7px solid #7A3FBF;border-radius:10px;padding:10px 14px;margin-bottom:10px">💬 <b style="color:#7A3FBF;font-size:18px">There are two burglars.</b><div style="color:#6B7280;font-style:italic">Здесь двое воров.</div></div><div style="background:#F6EFFA;border:1px solid #C9A7E0;border-left:7px solid #7A3FBF;border-radius:10px;padding:10px 14px;margin-bottom:10px">💬 <b style="color:#7A3FBF;font-size:18px">They're taking our computer.</b><div style="color:#6B7280;font-style:italic">Они забирают наш компьютер.</div></div><div style="background:#F6EFFA;border:1px solid #C9A7E0;border-left:7px solid #7A3FBF;border-radius:10px;padding:10px 14px;margin-bottom:10px">💬 <b style="color:#7A3FBF;font-size:18px">There's a problem!</b><div style="color:#6B7280;font-style:italic">Есть проблема!</div></div><div style="background:#F6EFFA;border:1px solid #C9A7E0;border-left:7px solid #7A3FBF;border-radius:10px;padding:10px 14px;margin-bottom:10px">💬 <b style="color:#7A3FBF;font-size:18px">I've got an idea!</b><div style="color:#6B7280;font-style:italic">У меня есть идея!</div></div></div></div>$h$::text)) where id='da5af1cc-39c0-4362-aeb7-d7f7012abfe7';
update classroom_blocks set payload = jsonb_set(payload,'{html}',to_jsonb($h$<div style="max-width:680px;border:1px solid #E6E0D8;border-radius:14px;overflow:hidden;font-size:15px;line-height:1.35"><div style="background:#6B4A12;color:#fff;padding:7px 12px;font-weight:700">CLIL Vocabulary</div><div style="padding:10px 12px;background:#fff"><table style="width:100%;border-collapse:collapse"><tr><td style="padding:5px;vertical-align:top;width:33%"><div style="background:#FDF3E0;border:1px solid #E8C27A;border-radius:10px;padding:10px 12px">🕰️ <b style="color:#6B4A12">sundial</b><div style="color:#6B7280">солнечные часы</div></div></td><td style="padding:5px;vertical-align:top;width:33%"><div style="background:#FDF7E0;border:1px solid #E8C27A;border-radius:10px;padding:10px 12px">☀️ <b style="color:#6B4A12">sun</b><div style="color:#6B7280">солнце</div></div></td><td style="padding:5px;vertical-align:top;width:33%"><div style="background:#EFE7F7;border:1px solid #C9A7E0;border-radius:10px;padding:10px 12px">🟣 <b style="color:#6B4A12">shadow</b><div style="color:#6B7280">тень</div></div></td></tr></table><div style="background:#6B4A12;color:#fff;padding:6px 12px;border-radius:8px;font-weight:700;font-size:15px;margin:14px 0 8px">🔢 Римские цифры</div><table style="width:100%;border-collapse:collapse"><tr><td style="padding:4px;text-align:center;width:16%"><div style="background:#FBF6E8;border:1px solid #E6E0D8;border-radius:10px;padding:10px 4px"><b style="font-size:20px;color:#6B4A12">I</b><div style="color:#6B7280">1</div></div></td><td style="padding:4px;text-align:center;width:16%"><div style="background:#FBF6E8;border:1px solid #E6E0D8;border-radius:10px;padding:10px 4px"><b style="font-size:20px;color:#6B4A12">II</b><div style="color:#6B7280">2</div></div></td><td style="padding:4px;text-align:center;width:16%"><div style="background:#FBF6E8;border:1px solid #E6E0D8;border-radius:10px;padding:10px 4px"><b style="font-size:20px;color:#6B4A12">III</b><div style="color:#6B7280">3</div></div></td><td style="padding:4px;text-align:center;width:16%"><div style="background:#FBF6E8;border:1px solid #C23A1E;border-radius:10px;padding:10px 4px"><b style="font-size:20px;color:#C23A1E">IV</b> <sup style="color:#C23A1E">★</sup><div style="color:#6B7280">4</div></div></td><td style="padding:4px;text-align:center;width:16%"><div style="background:#FBF6E8;border:1px solid #E6E0D8;border-radius:10px;padding:10px 4px"><b style="font-size:20px;color:#6B4A12">V</b><div style="color:#6B7280">5</div></div></td><td style="padding:4px;text-align:center;width:16%"><div style="background:#FBF6E8;border:1px solid #E6E0D8;border-radius:10px;padding:10px 4px"><b style="font-size:20px;color:#6B4A12">VI</b><div style="color:#6B7280">6</div></div></td></tr><tr><td style="padding:4px;text-align:center;width:16%"><div style="background:#FBF6E8;border:1px solid #E6E0D8;border-radius:10px;padding:10px 4px"><b style="font-size:20px;color:#6B4A12">VII</b><div style="color:#6B7280">7</div></div></td><td style="padding:4px;text-align:center;width:16%"><div style="background:#FBF6E8;border:1px solid #E6E0D8;border-radius:10px;padding:10px 4px"><b style="font-size:20px;color:#6B4A12">VIII</b><div style="color:#6B7280">8</div></div></td><td style="padding:4px;text-align:center;width:16%"><div style="background:#FBF6E8;border:1px solid #C23A1E;border-radius:10px;padding:10px 4px"><b style="font-size:20px;color:#C23A1E">IX</b> <sup style="color:#C23A1E">★</sup><div style="color:#6B7280">9</div></div></td><td style="padding:4px;text-align:center;width:16%"><div style="background:#FBF6E8;border:1px solid #E6E0D8;border-radius:10px;padding:10px 4px"><b style="font-size:20px;color:#6B4A12">X</b><div style="color:#6B7280">10</div></div></td><td style="padding:4px;text-align:center;width:16%"><div style="background:#FBF6E8;border:1px solid #E6E0D8;border-radius:10px;padding:10px 4px"><b style="font-size:20px;color:#6B4A12">XI</b><div style="color:#6B7280">11</div></div></td><td style="padding:4px;text-align:center;width:16%"><div style="background:#FBF6E8;border:1px solid #E6E0D8;border-radius:10px;padding:10px 4px"><b style="font-size:20px;color:#6B4A12">XII</b><div style="color:#6B7280">12</div></div></td></tr></table><p style="margin:12px 0 0;padding:10px 12px;background:#FBF6E8;border-left:4px solid #E8C27A;border-radius:8px">★ <b style="color:#B4530F">Трудные:</b> IV = 4 (V-I) и IX = 9 (X-I) — буква перед большей ВЫЧИТАЕТСЯ!</p></div></div>$h$::text)) where id='6e3722f3-d779-4a88-b4ec-5d1f4f329ed7';
update classroom_blocks set payload = jsonb_set(payload,'{html}',to_jsonb($h$<div style="max-width:680px;border:1px solid #E6E0D8;border-radius:14px;overflow:hidden;font-size:15px;line-height:1.35"><div style="background:#6B4CC4;color:#fff;padding:7px 12px;font-weight:700">📖 KEY PHRASES — Thunder's Birthday</div><div style="padding:10px 12px;background:#fff"><table style="width:100%;border-collapse:collapse"><tr><td style="padding:6px;vertical-align:top;width:50%"><div style="background:#F6EFFA;border-left:7px solid #7A3FBF;border-radius:8px;padding:10px 14px">💬 <b style="color:#2B2140;font-size:17px">tug of war</b><div style="color:#6B7280;font-style:italic">перетягивание каната</div></div></td><td style="padding:6px;vertical-align:top;width:50%"><div style="background:#F6EFFA;border-left:7px solid #A06BD8;border-radius:8px;padding:10px 14px">💬 <b style="color:#2B2140;font-size:17px">three-legged race</b><div style="color:#6B7280;font-style:italic">гонка на трёх ногах</div></div></td></tr><tr><td style="padding:6px;vertical-align:top;width:50%"><div style="background:#EFE7F7;border-left:7px solid #6B3FBF;border-radius:8px;padding:10px 14px">💬 <b style="color:#2B2140;font-size:17px">blindfold</b><div style="color:#6B7280;font-style:italic">повязка на глаза</div></div></td><td style="padding:6px;vertical-align:top;width:50%"><div style="background:#FDEFEA;border-left:7px solid #E8512A;border-radius:8px;padding:10px 14px">💬 <b style="color:#2B2140;font-size:17px">medal</b><div style="color:#6B7280;font-style:italic">медаль</div></div></td></tr><tr><td style="padding:6px;vertical-align:top;width:50%"><div style="background:#FDE7E0;border-left:7px solid #E8512A;border-radius:8px;padding:10px 14px">💬 <b style="color:#2B2140;font-size:17px">That's not fair!</b><div style="color:#6B7280;font-style:italic">Это нечестно!</div></div></td><td style="padding:6px;vertical-align:top;width:50%"><div style="background:#FDE7E0;border-left:7px solid #7A2A12;border-radius:8px;padding:10px 14px">💬 <b style="color:#2B2140;font-size:17px">No medals for us today!</b><div style="color:#6B7280;font-style:italic">Сегодня нам медалей нет!</div></div></td></tr></table></div></div>$h$::text)) where id='90469058-5fe5-4b1a-a741-50ec82fe4eda';
update classroom_blocks set payload = jsonb_set(payload,'{html}',to_jsonb($h$<div style="max-width:680px;border:1px solid #E6E0D8;border-radius:14px;overflow:hidden;font-size:15px;line-height:1.35"><div style="background:#B5541E;color:#fff;padding:7px 12px;font-weight:700">GRAMMAR 2 &nbsp;·&nbsp; Present Continuous Q&amp;A</div><div style="padding:10px 12px;background:#fff"><div style="background:#FDF3EC;border:1px solid #B5541E;border-radius:10px;padding:10px 12px"><div style="font-size:18px">Are you <b style="color:#E8512A">[verb+ing]</b> a [transport]? &nbsp;→&nbsp; <b style="color:#1F6F45">Yes, I am!</b> / <b style="color:#1F6F45">No, I'm not!</b></div><div style="font-size:18px">What's he doing? &nbsp;→&nbsp; He's <b style="color:#E8512A">[verb+ing]</b>!</div></div><table style="width:100%;border-collapse:collapse"><tr><td style="padding:6px;vertical-align:top;width:50%"><div style="border:1px solid #B5541E;border-radius:10px;overflow:hidden"><div style="background:#B5541E;color:#fff;padding:6px 10px;text-align:center;font-weight:700">💡 Как запомнить?</div><div style="background:#FBEFE9;padding:10px 12px">Present Continuous = что происходит <b>СЕЙЧАС</b>.<br>Добавляем <b>-ing</b> к глаголу: drive → driving.<br><u>Вопрос</u>: Are you + verb-ing? (Are you driving a car?)<br><u>Ответ</u>: Yes, I am! / No, I'm not!</div></div></td><td style="padding:6px;vertical-align:top;width:50%"><div style="border:1px solid #E8B321;border-radius:10px;overflow:hidden"><div style="background:#F2C230;color:#4A3505;padding:6px 10px;text-align:center;font-weight:700">⚠️ Глаголы транспорта!</div><div style="background:#FDF7E0;padding:10px 12px">drive → driving 🚗 &nbsp;(bus, car, lorry, taxi)<br>fly → flying ✈️ &nbsp;(plane, helicopter)<br>ride → riding 🛵 &nbsp;(bike, scooter, motorbike, skateboard)<br>sail → sailing ⛵ &nbsp;(boat, ship)</div></div></td></tr></table><table style="width:100%;border-collapse:collapse;margin-top:6px"><tr><td style="padding:5px;vertical-align:top;width:50%"><div style="background:#FDF3EC;border:1px solid #E0B49A;border-radius:10px;padding:10px 12px">❓ <b style="color:#B4530F">Are you driving a bus?</b><div style="color:#6B7280;font-size:14px">Ты едешь на автобусе?</div></div></td><td style="padding:5px;vertical-align:top;width:50%"><div style="background:#FDF3EC;border:1px solid #E0B49A;border-radius:10px;padding:10px 12px">✅ <b style="color:#B4530F">Yes, I am! I'm driving a big bus!</b><div style="color:#6B7280;font-size:14px">Да! Я еду на большом автобусе!</div></div></td></tr><tr><td style="padding:5px;vertical-align:top;width:50%"><div style="background:#FDF3EC;border:1px solid #E0B49A;border-radius:10px;padding:10px 12px">❓ <b style="color:#B4530F">Are you flying a helicopter?</b><div style="color:#6B7280;font-size:14px">Ты летишь на вертолёте?</div></div></td><td style="padding:5px;vertical-align:top;width:50%"><div style="background:#FDF3EC;border:1px solid #E0B49A;border-radius:10px;padding:10px 12px">✅ <b style="color:#B4530F">No, I'm not! I'm riding a scooter!</b><div style="color:#6B7280;font-size:14px">Нет! Я еду на скутере!</div></div></td></tr><tr><td style="padding:5px;vertical-align:top;width:50%"><div style="background:#FDF3EC;border:1px solid #E0B49A;border-radius:10px;padding:10px 12px">❓ <b style="color:#B4530F">What's he doing?</b><div style="color:#6B7280;font-size:14px">Что он делает?</div></div></td><td style="padding:5px;vertical-align:top;width:50%"><div style="background:#FDF3EC;border:1px solid #E0B49A;border-radius:10px;padding:10px 12px">✅ <b style="color:#B4530F">He's sailing a ship!</b><div style="color:#6B7280;font-size:14px">Он плывёт на корабле!</div></div></td></tr></table></div></div>$h$::text)) where id='46ffd22b-dac4-4a10-8248-2c50c8ba388d';
update classroom_blocks set payload = jsonb_set(payload,'{html}',to_jsonb($h$<div style="max-width:680px;border:1px solid #E6E0D8;border-radius:14px;overflow:hidden;font-size:15px;line-height:1.35"><div style="background:#B5541E;color:#fff;padding:7px 12px;font-weight:700">✏️ Grammar 1: [Activity]'s [adjective]</div><div style="padding:10px 12px;background:#fff"><div style="background:#FDF7E8;border:1px solid #E8C27A;border-radius:10px;padding:10px 12px">Чтобы сказать своё мнение об активности, используй глагол+ING + 's + прилагательное.<div style="color:#6B7280;font-style:italic;margin-top:4px">Playing football's fun = Playing football IS fun. ✅</div></div><table style="width:100%;border-collapse:collapse"><tr><td style="padding:6px;vertical-align:top;width:50%"><div style="background:#FDF3E7;border-left:7px solid #E8821E;border-radius:8px;padding:10px 12px">📐 <b style="color:#B4530F">Формула:</b><div style="font-size:19px;font-weight:700;margin-top:4px">[Verb+ING]'s [adjective]</div></div></td><td style="padding:6px;vertical-align:top;width:50%"><div style="background:#FDF7E0;border-left:7px solid #F2C230;border-radius:8px;padding:10px 12px">⚠️ <b style="color:#B4530F">Важно запомнить!</b><div>Нет 'it' — активность САМА является подлежащим!</div></div></td></tr></table><table style="width:100%;border-collapse:collapse"><tr><td style="padding:6px;vertical-align:top;width:50%"><div style="background:#FDF7E8;border:1px solid #E8C27A;border-radius:10px;padding:10px 12px">✅ <b style="color:#2B2140;font-size:17px">Swimming's fun!</b><div style="color:#6B7280;font-style:italic">Плавание — это весело!</div></div></td><td style="padding:6px;vertical-align:top;width:50%"><div style="background:#FDF7E8;border:1px solid #E8C27A;border-radius:10px;padding:10px 12px">✅ <b style="color:#2B2140;font-size:17px">Playing tennis's difficult!</b><div style="color:#6B7280;font-style:italic">Играть в теннис — сложно!</div></div></td></tr><tr><td style="padding:6px;vertical-align:top;width:50%"><div style="background:#FDF7E8;border:1px solid #E8C27A;border-radius:10px;padding:10px 12px">✅ <b style="color:#2B2140;font-size:17px">Flying a kite's amazing!</b><div style="color:#6B7280;font-style:italic">Запускать змея — потрясающе!</div></div></td><td style="padding:6px;vertical-align:top;width:50%"><div style="background:#FDF7E8;border:1px solid #E8C27A;border-radius:10px;padding:10px 12px">✅ <b style="color:#2B2140;font-size:17px">Playing football's great!</b><div style="color:#6B7280;font-style:italic">Играть в футбол — здорово!</div></div></td></tr><tr><td style="padding:6px;vertical-align:top;width:50%"><div style="background:#FDF7E8;border:1px solid #E8C27A;border-radius:10px;padding:10px 12px">✅ <b style="color:#2B2140;font-size:17px">Dancing's easy!</b><div style="color:#6B7280;font-style:italic">Танцевать — это легко!</div></div></td><td style="padding:6px;vertical-align:top;width:50%"><div style="background:#FDF7E8;border:1px solid #E8C27A;border-radius:10px;padding:10px 12px">✅ <b style="color:#2B2140;font-size:17px">Watching TV's boring.</b><div style="color:#6B7280;font-style:italic">Смотреть телевизор — скучно.</div></div></td></tr></table></div></div>$h$::text)) where id='b38b0ede-9185-45e7-8cc3-5f63489b6231';
update classroom_blocks set payload = jsonb_set(payload,'{html}',to_jsonb($h$<div style="max-width:680px;border:1px solid #E6E0D8;border-radius:14px;overflow:hidden;font-size:15px;line-height:1.35"><div style="background:#D9821E;color:#fff;padding:7px 12px;font-weight:700">📝 Грамматика: Can I / Can we…?</div><div style="padding:10px 12px;background:#fff"><p style="margin:0 0 12px;padding:10px 12px;background:#FDF7E8;border-left:4px solid #E8C27A;border-radius:8px">Когда хочешь попросить разрешения по-английски — используй Can I…? (для себя) или Can we…? (для себя и кого-то ещё). Ответы: Yes, of course, you/we can. / No, you/we can't.</p><div style="background:#D9821E;border-radius:10px;padding:12px 14px;text-align:center;color:#fff"><div style="font-size:18px;font-weight:700">❓ Can I + глагол (основа) + …? &nbsp;|&nbsp; Can we + глагол (основа) + …?</div><div style="margin-top:8px;font-size:14px">⚠️ Важно: после Can всегда глагол в основной форме (без to, без -ing, без -s)!</div></div><div style="margin-top:12px"><table style="width:100%;border-collapse:collapse"><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top">✅ <b style="color:#1F6F45">Can I go camping, Mum?</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;color:#6B7280;vertical-align:top">— Мама, можно я пойду в поход с палаткой?</td></tr><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top">✅ <b style="color:#1F6F45">Can we build a tree house, Dad?</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;color:#6B7280;vertical-align:top">— Папа, можно мы построим домик на дереве?</td></tr><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top">✅ <b style="color:#1F6F45">Can I take riding lessons, please?</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;color:#6B7280;vertical-align:top">— Можно мне брать уроки верховой езды, пожалуйста?</td></tr><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top">✅ <b style="color:#1F6F45">Yes, of course you can!</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;color:#6B7280;vertical-align:top">— Да, конечно, можешь! ✅</td></tr><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top">✅ <b style="color:#1F6F45">No, you can't go hiking today.</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;color:#6B7280;vertical-align:top">— Нет, ты не можешь идти в поход сегодня. ❌</td></tr><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top">✅ <b style="color:#1F6F45">Can we visit cousins on Friday?</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;color:#6B7280;vertical-align:top">— Можно мы навестим кузенов в пятницу?</td></tr></table></div></div></div>$h$::text)) where id='3b9a25cc-2cb3-42d1-beef-b09585f8a2e9';
update classroom_blocks set payload = jsonb_set(payload,'{html}',to_jsonb($h$<div style="max-width:680px;border:1px solid #E6E0D8;border-radius:14px;overflow:hidden;font-size:15px;line-height:1.35"><div style="background:#E17B20;color:#fff;padding:7px 12px;font-weight:700">Unit 1 · to be · Утвердительная форма</div><div style="padding:10px 12px;background:#fff"><p style="margin:0 0 10px">Глагол to be = «быть».</p><table style="width:100%;border-collapse:collapse;background:#FFF8EF"><tr><th style="text-align:left;padding:4px 8px;color:#B4530F">Подлежащее</th><th style="text-align:left;padding:4px 8px;color:#B4530F">Полная</th><th style="text-align:left;padding:4px 8px;color:#B4530F">Краткая</th></tr><tr><td style="padding:4px 8px">I</td><td style="padding:4px 8px"><b>am</b></td><td style="padding:4px 8px">I&#39;m</td></tr><tr><td style="padding:4px 8px">You/We/They</td><td style="padding:4px 8px"><b>are</b></td><td style="padding:4px 8px">You&#39;re / We&#39;re / They&#39;re</td></tr><tr><td style="padding:4px 8px">He/She/It</td><td style="padding:4px 8px"><b>is</b></td><td style="padding:4px 8px">He&#39;s / She&#39;s / It&#39;s</td></tr></table><p style="margin:6px 0 0;text-align:right;color:#6B7280;font-size:14px">Краткие формы используются в разговоре</p><div style="margin:12px 0 0;padding:10px 12px;background:#FFF8EF;border-left:4px solid #E8732A;border-radius:8px"><b style="color:#B4530F">👤 Притяжательные местоимения</b><table style="width:100%;border-collapse:collapse"><tr><td style="padding:6px 10px"><b style="color:#E8732A">I</b> → my</td><td style="padding:6px 10px"><b style="color:#E8732A">you</b> → your</td></tr><tr><td style="padding:6px 10px"><b style="color:#E8732A">he</b> → his</td><td style="padding:6px 10px"><b style="color:#E8732A">she</b> → her</td></tr></table></div><div style="margin:12px 0 0;padding:7px 10px;background:#FDF0F4;border-left:4px solid #D94A77;border-radius:8px">⚠️ &quot;She ARE&quot; ✗ → &quot;She IS&quot; ✓ · апостроф заменяет букву: she&#39;s = she is</div><p style="margin:16px 0 6px;font-weight:700;color:#B4530F">Примеры</p><table style="width:100%;border-collapse:collapse"><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top"><b>✅ I&#39;m ten years old.</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top;color:#6B7280">Мне десять лет.</td></tr><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top"><b>✅ She is from Spain.</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top;color:#6B7280">Она из Испании.</td></tr><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top"><b>✅ They&#39;re my best friends.</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top;color:#6B7280">Они мои лучшие друзья.</td></tr><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top"><b>✅ His name is Lucas.</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top;color:#6B7280">Его зовут Лукас.</td></tr><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top"><b>✅ Her granny is seventy.</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top;color:#6B7280">Её бабушке семьдесят.</td></tr><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top"><b>✅ We&#39;re at school.</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top;color:#6B7280">Мы в школе.</td></tr></table></div></div>$h$::text)) where id='44f47f0c-046d-44bf-878e-776bdac3518d';
update classroom_blocks set payload = jsonb_set(payload,'{html}',to_jsonb($h$<div style="max-width:680px;border:1px solid #E6E0D8;border-radius:14px;overflow:hidden;font-size:15px;line-height:1.35"><div style="background:#E17B20;color:#fff;padding:7px 12px;font-weight:700">📍 There is / There are + Предлоги места</div><div style="padding:10px 12px;background:#fff"><p style="margin:0 0 10px">Используй <b>there is</b> (есть один предмет) и <b>there are</b> (есть несколько), чтобы сказать, что что-то где-то есть (находится).</p><div style="margin:0 0 12px;padding:10px 12px;background:#E17B20;color:#fff;border-radius:10px"><b>There is</b> (There&#39;s) + singular &nbsp;|&nbsp; <b>There are</b> + plural &nbsp;|&nbsp; ⚠️ <i>There are не сокращается!</i></div><table style="width:100%;border-collapse:collapse"><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top"><b>✅ There&#39;s a phone on the sofa.</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top;color:#6B7280">— Есть телефон на диване.</td></tr><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top"><b>✅ There are two books behind the sofa.</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top;color:#6B7280">— Есть две книги позади дивана.</td></tr><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top"><b>✅ There are some sweets under the sofa.</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top;color:#6B7280">— Есть несколько конфет под диваном.</td></tr><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top"><b>✅ There&#39;s a lamp on the desk.</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top;color:#6B7280">— На столе есть лампа.</td></tr></table><p style="margin:16px 0 6px;font-weight:700;color:#B4530F">Предлоги места:</p><table style="width:100%;border-collapse:collapse"><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top"><b>on</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top;color:#6B7280">на</td></tr><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top"><b>under</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top;color:#6B7280">под</td></tr><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top"><b>behind</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top;color:#6B7280">за/позади</td></tr><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top"><b>in</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top;color:#6B7280">в</td></tr><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top"><b>next to</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top;color:#6B7280">рядом с</td></tr><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top"><b>in front of</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top;color:#6B7280">перед</td></tr></table></div></div>$h$::text)) where id='ff2bbaf4-dce4-43b8-ac65-8b35bccee443';
update classroom_blocks set payload = jsonb_set(payload,'{html}',to_jsonb($h$<div style="max-width:680px;border:1px solid #E6E0D8;border-radius:14px;overflow:hidden;font-size:15px;line-height:1.35"><div style="background:#D64C8D;color:#fff;padding:7px 12px;font-weight:700">Unit 5 · Making Suggestions</div><div style="padding:10px 12px;background:#fff"><p style="margin:16px 0 6px;font-weight:700;color:#D64C8D">💡 Предлагаем</p><table style="width:100%;border-collapse:collapse"><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top"><b>→ Let&#39;s go ice-skating!</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top;color:#6B7280">Давай пойдём кататься на коньках!</td></tr><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top"><b>→ We can go to the park.</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top;color:#6B7280">Мы можем пойти в парк!</td></tr></table><p style="margin:16px 0 6px;font-weight:700;color:#1B793E">✅ Соглашаемся</p><table style="width:100%;border-collapse:collapse"><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top"><b>😄 I agree!</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top;color:#6B7280">Согласен(на)!</td></tr><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top"><b>😄 Great idea!</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top;color:#6B7280">Отличная идея!</td></tr><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top"><b>😄 Let&#39;s do that!</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top;color:#6B7280">Давай так и сделаем!</td></tr></table><p style="margin:16px 0 6px;font-weight:700;color:#6B4CC4">🤔 Сомневаемся / Отказываемся</p><table style="width:100%;border-collapse:collapse"><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top"><b>😕 I&#39;m not sure…</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top;color:#6B7280">Я не уверен(а)…</td></tr><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top"><b>😕 It&#39;s not a good idea.</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top;color:#6B7280">Это не очень хорошая идея.</td></tr></table><p style="margin:16px 0 6px;font-weight:700;color:#D64C8D">💛 Предлагаем помощь</p><table style="width:100%;border-collapse:collapse"><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top"><b>✓ No problem, I can teach you!</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top;color:#6B7280">Не проблема — я могу тебя научить!</td></tr></table></div></div>$h$::text)) where id='563e1a4c-33e8-4f4c-aeea-bf7dbdd553c1';
update classroom_blocks set payload = jsonb_set(payload,'{html}',to_jsonb($h$<div style="max-width:680px;border:1px solid #E6E0D8;border-radius:14px;overflow:hidden;font-size:15px;line-height:1.35"><div style="background:#7B3AEB;color:#fff;padding:7px 12px;font-weight:700">Unit 6 · Telling the Time</div><div style="padding:10px 12px;background:#fff"><table style="width:100%;border-collapse:collapse"><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top"><b>💬 What time is it?</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top;color:#6B7280"><small style="color:#9CA3AF">RU</small> Который час?</td></tr><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top"><b>💬 It&#39;s four o&#39;clock.</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top;color:#6B7280"><small style="color:#9CA3AF">RU</small> Четыре часа ровно (4:00)</td></tr><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top"><b>💬 It&#39;s ten past four.</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top;color:#6B7280"><small style="color:#9CA3AF">RU</small> Десять минут пятого (4:10)</td></tr><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top"><b>💬 It&#39;s quarter past four.</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top;color:#6B7280"><small style="color:#9CA3AF">RU</small> Четверть пятого (4:15)</td></tr><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top"><b>💬 It&#39;s half past four.</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top;color:#6B7280"><small style="color:#9CA3AF">RU</small> Половина пятого (4:30)</td></tr><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top"><b>💬 It&#39;s quarter to five.</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top;color:#6B7280"><small style="color:#9CA3AF">RU</small> Без четверти пять (4:45)</td></tr><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top"><b>💬 It&#39;s ten to five.</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top;color:#6B7280"><small style="color:#9CA3AF">RU</small> Без десяти пять (4:50)</td></tr><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top"><b>💬 What time is the film?</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top;color:#6B7280"><small style="color:#9CA3AF">RU</small> Когда начинается фильм?</td></tr><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top"><b>💬 It&#39;s at four o&#39;clock.</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top;color:#6B7280"><small style="color:#9CA3AF">RU</small> В четыре часа.</td></tr></table><div style="margin:12px 0 0;padding:10px 12px;background:#F3EFFE;border-left:4px solid #6B4CC4;border-radius:8px">📌 <b>PAST</b> = до 30 минут (после): 10 past 4 = 4:10 &nbsp;&nbsp; <b>TO</b> = после 30 минут (до): 10 to 5 = 4:50</div></div></div>$h$::text)) where id='80ad3315-e002-4fcd-be81-93fda0b52b6e';
update classroom_blocks set payload = jsonb_set(payload,'{html}',to_jsonb($h$<div style="max-width:680px;border:1px solid #E6E0D8;border-radius:14px;overflow:hidden;font-size:15px;line-height:1.35"><div style="background:#E17B20;color:#fff;padding:7px 12px;font-weight:700">❓ Present Simple — Questions</div><div style="padding:10px 12px;background:#fff"><div style="margin:12px 0 0;padding:10px 12px;background:#FFFBEB;border-left:4px solid #E17B20;border-radius:8px">Чтобы задать вопрос, поставь <b style="color:#C2185B">DO</b> или <b style="color:#C2185B">DOES</b> ПЕРЕД подлежащим. Глагол — без -s!</div><table style="width:100%;border-collapse:collapse;margin-top:12px"><tr><td style="padding:10px 12px;background:#E17B20;color:#fff;border-radius:10px;text-align:center">DO + I / You / We / They + <b>verb?</b></td><td style="width:10px"></td><td style="padding:10px 12px;background:#B45309;color:#fff;border-radius:10px;text-align:center">DOES + He / She / It + <b>verb?</b></td></tr></table><div style="margin:12px 0 0;padding:10px 12px;background:#FFFBEB;border-left:4px solid #E17B20;border-radius:8px"><b>Краткие ответы:</b> <b style="color:#1B793E">Yes, I do.</b> / <b style="color:#C2185B">No, I don&#39;t.</b> &nbsp;·&nbsp; <b style="color:#1B793E">Yes, he does.</b> / <b style="color:#C2185B">No, he doesn&#39;t.</b></div><p style="margin:16px 0 6px;font-weight:700;color:#B4530F">Примеры</p><table style="width:100%;border-collapse:collapse"><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top"><b>✅ Do you sing?</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top;color:#6B7280">Ты поёшь?</td></tr><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top"><b>✅ Does he have piano lessons?</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top;color:#6B7280">У него есть уроки фортепиано?</td></tr><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top"><b>✅ Do they work together?</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top;color:#6B7280">Они работают вместе?</td></tr><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top"><b>✅ Does Kit visit you at weekends?</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top;color:#6B7280">Кит навещает тебя по выходным?</td></tr><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top"><b>✅ Do lions sleep all day?</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top;color:#6B7280">Львы спят весь день?</td></tr></table></div></div>$h$::text)) where id='98c00948-5665-4f6d-805c-e9107707f0af';
update classroom_blocks set payload = jsonb_set(payload,'{html}',to_jsonb($h$<div style="max-width:680px;border:1px solid #E6E0D8;border-radius:14px;overflow:hidden;font-size:15px;line-height:1.35"><div style="background:#D37218;color:#fff;padding:7px 12px;font-weight:700">📖 love / like / hate + -ING</div><div style="padding:10px 12px;background:#fff"><p style="margin:0 0 10px">После глаголов <b style="color:#C2185B">love</b> (любить), <b style="color:#C2185B">like</b> (нравиться), <b style="color:#C2185B">hate</b> (ненавидеть) следующий глагол всегда стоит с окончанием <b style="color:#C2185B">-ING</b>.</p><div style="margin:12px 0 0;padding:10px 12px;background:#FFF8EF;border-left:4px solid #E8732A;border-radius:8px"><b style="color:#B4530F">Формула:</b> Subject + love / like / hate / don&#39;t like + verb + <b style="color:#1B793E">ING</b><br>⚠️ <b style="color:#C2185B">НИКОГДА:</b> &quot;I love swim&quot; → <b>Только: &quot;I love swimm-ING&quot;</b></div><p style="margin:16px 0 6px;font-weight:700;color:#B4530F">Примеры</p><table style="width:100%;border-collapse:collapse"><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top"><b>✅ I love swimming.</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top;color:#6B7280">— Я обожаю плавать.</td></tr><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top"><b>✅ She likes playing football.</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top;color:#6B7280">— Ей нравится играть в футбол.</td></tr><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top"><b>✅ He hates cycling.</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top;color:#6B7280">— Он терпеть не может езду на велосипеде.</td></tr><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top"><b>✅ We don&#39;t like doing taekwondo.</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top;color:#6B7280">— Нам не нравится тхэквондо.</td></tr><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top"><b>✅ Do you like skating?</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top;color:#6B7280">— Тебе нравится кататься?</td></tr></table></div></div>$h$::text)) where id='3345accd-fbd7-430b-8731-65d8b20ec193';
update classroom_blocks set payload = jsonb_set(payload,'{html}',to_jsonb($h$<div style="max-width:680px;border:1px solid #E6E0D8;border-radius:14px;overflow:hidden;font-size:15px;line-height:1.35"><div style="background:#C2185B;color:#fff;padding:7px 12px;font-weight:700">💬 Key Phrases — The Go-Kart Race 🏎️</div><div style="padding:10px 12px;background:#fff"><table style="width:100%;border-collapse:collapse"><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top"><b>🤢 What an ugly old go-kart!</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top;color:#6B7280">Какая некрасивая старая гоночная машина!</td></tr><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top"><b>💪 Hold on!</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top;color:#6B7280">Держись!</td></tr><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top"><b>🏁 1, 2, 3 — Go!</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top;color:#6B7280">1, 2, 3 — Вперёд!</td></tr><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top"><b>😱 Help!</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top;color:#6B7280">Помогите!</td></tr><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top"><b>😈 Now I&#39;m first!</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top;color:#6B7280">Теперь я первый!</td></tr><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top"><b>🏆 Congratulations! You&#39;re first!</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top;color:#6B7280">Поздравляю! Ты первая!</td></tr><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top"><b>😡 That isn&#39;t fair!</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top;color:#6B7280">Это нечестно!</td></tr></table></div></div>$h$::text)) where id='4fe4cdeb-6e2d-438e-8475-d803c314e1a6';
update classroom_blocks set payload = jsonb_set(payload,'{html}',to_jsonb($h$<div style="max-width:680px;border:1px solid #E6E0D8;border-radius:14px;overflow:hidden;font-size:15px;line-height:1.35"><div style="background:#E91F63;color:#fff;padding:7px 12px;font-weight:700">📖 Story — &quot;The Spider&quot; (Key Phrases)</div><div style="padding:10px 12px;background:#fff"><table style="width:100%;border-collapse:collapse"><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top"><b>I don&#39;t like spiders!</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top;color:#6B7280">Я не люблю пауков!</td></tr><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top"><b>Touch him, Misty.</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top;color:#6B7280">Потрогай его, Мисти.</td></tr><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top"><b>Come back!</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top;color:#6B7280">Вернись!</td></tr><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top"><b>I like spiders. They&#39;re great!</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top;color:#6B7280">Я люблю пауков. Они классные!</td></tr><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top"><b>He&#39;s beautiful. Look!</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top;color:#6B7280">Он красивый. Посмотри!</td></tr><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top"><b>I&#39;ve got an idea!</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top;color:#6B7280">У меня есть идея!</td></tr></table></div></div>$h$::text)) where id='8bb4c011-f6f5-4530-8214-adff32ba95d6';
update classroom_blocks set payload = jsonb_set(payload,'{html}',to_jsonb($h$<div style="max-width:680px;border:1px solid #E6E0D8;border-radius:14px;overflow:hidden;font-size:15px;line-height:1.35"><div style="background:#E91F63;color:#fff;padding:7px 12px;font-weight:700">📖 Story — &quot;The Pizza&quot; (Key Phrases)</div><div style="padding:10px 12px;background:#fff"><table style="width:100%;border-collapse:collapse"><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top"><b>Pizza, please!</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top;color:#6B7280">Пиццу, пожалуйста!</td></tr><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top"><b>OK. Sausages and peas, please.</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top;color:#6B7280">Ладно. Сосиски и горох.</td></tr><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top"><b>Sorry, we haven&#39;t got pizza.</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top;color:#6B7280">Извините, пиццы нет.</td></tr><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top"><b>Here you are.</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top;color:#6B7280">Вот, пожалуйста.</td></tr><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top"><b>Pizza is my favourite!</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top;color:#6B7280">Пицца — моё любимое!</td></tr><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top"><b>Thank you!</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top;color:#6B7280">Спасибо!</td></tr></table><p style="margin:16px 0 6px;font-weight:700;color:#C2185B">🎭 Mini-Dialogue (Act it out!)</p><p style="margin:0">👧 <b style="color:#E8732A">Misty:</b> &quot;Pizza, please!&quot;<br>🧕 <b style="color:#1B793E">Woman:</b> &quot;Sorry, we haven&#39;t got pizza.&quot;<br>👧 <b style="color:#E8732A">Misty:</b> &quot;OK. Sausages and peas, please.&quot;<br>🧕 <b style="color:#1B793E">Woman:</b> &quot;Here you are.&quot;<br>👧 <b style="color:#E8732A">Misty:</b> &quot;Thank you!&quot;</p></div></div>$h$::text)) where id='63cc6a14-ca76-467a-b9ec-0c74f607b889';
update classroom_blocks set payload = jsonb_set(payload,'{html}',to_jsonb($h$<div style="max-width:680px;border:1px solid #E6E0D8;border-radius:14px;overflow:hidden;font-size:15px;line-height:1.35"><div style="background:#F39C11;color:#fff;padding:7px 12px;font-weight:700">📄 Grammar 2 — Is there…? / Are there…?</div><div style="padding:10px 12px;background:#fff"><div style="margin:12px 0 0;padding:10px 12px;background:#FFFBEB;border-left:4px solid #F39C11;border-radius:8px">📖 Чтобы спросить, есть ли что-то: <b style="color:#1B793E">Is there…?</b> (один) / <b style="color:#2F6FB8">Are there any…?</b> (несколько).</div><div style="margin:12px 0 0;padding:10px 12px;background:#EFFBF2;border:1px solid #1B793E;border-radius:10px"><p style="margin:0 0 4px;text-align:center;color:#C2185B">❓ ОДИН ПРЕДМЕТ</p><p style="margin:0 0 4px;text-align:center"><b style="color:#1B793E">Is there a + [предмет]?</b></p><p style="margin:0 0 8px;text-align:center;color:#6B7280;font-size:14px">Есть ли…?</p><p style="margin:0;text-align:center">✅ <b style="color:#1B793E">Yes, there is.</b><br>❌ <b style="color:#C2185B">No, there isn&#39;t.</b></p></div><div style="margin:12px 0 0;padding:10px 12px;background:#EFF5FD;border:1px solid #2F6FB8;border-radius:10px"><p style="margin:0 0 4px;text-align:center;color:#C2185B">❓ НЕСКОЛЬКО</p><p style="margin:0 0 4px;text-align:center"><b style="color:#2F6FB8">Are there any + [предметы]?</b></p><p style="margin:0 0 8px;text-align:center;color:#6B7280;font-size:14px">Есть ли какие-то…?</p><p style="margin:0;text-align:center">✅ <b style="color:#1B793E">Yes, there are.</b><br>❌ <b style="color:#C2185B">No, there aren&#39;t.</b><br>🔢 <b style="color:#2F6FB8">How many are there?</b> — Сколько?</p></div><p style="margin:16px 0 6px;font-weight:700;color:#B4530F">📄 Примеры</p><table style="width:100%;border-collapse:collapse"><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top"><b>🟢 Is there a park? — Yes, there is.</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top;color:#6B7280">— Есть парк? — Да.</td></tr><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top"><b>🟢 Is there a school? — Yes, there is.</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top;color:#6B7280">— Есть школа? — Да.</td></tr><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top"><b>🔵 Are there any bikes? — Yes, there are.</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top;color:#6B7280">— Есть велосипеды? — Да.</td></tr><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top"><b>🔵 Are there any trees? — No, there aren&#39;t.</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top;color:#6B7280">— Есть деревья? — Нет.</td></tr><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top"><b>🔵 Are there any dogs? — Yes, there are.</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top;color:#6B7280">— Есть собаки? — Да.</td></tr><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top"><b>🔢 How many ducks are there?</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top;color:#6B7280">— Сколько уток?</td></tr></table><div style="margin:12px 0 0;padding:10px 12px;background:#FFFBEB;border-left:4px solid #F39C11;border-radius:8px">⚠️ <b style="color:#E8732A">any</b> — в вопросах и отрицаниях (Are there <b style="color:#E8732A">any</b> trees?). &nbsp; <b>isn&#39;t</b> = is not, &nbsp; <b>aren&#39;t</b> = are not</div></div></div>$h$::text)) where id='bcf325b5-b5e0-4e9b-9476-8d9ff6cac8ed';
update classroom_blocks set payload = jsonb_set(payload,'{html}',to_jsonb($h$<div style="max-width:680px;border:1px solid #E6E0D8;border-radius:14px;overflow:hidden;font-size:15px;line-height:1.35"><div style="background:#B65A0B;color:#fff;padding:7px 12px;font-weight:700">Grammar: There&#39;s a / There are some</div><div style="padding:10px 12px;background:#fff"><p style="margin:0 0 10px">Когда хочешь сказать, что что-то ЕСТЬ — используй There&#39;s (одна вещь) или There are (несколько вещей). Начинай предложение с There&#39;s / There are — не с названия предмета!</p><div style="margin:12px 0 0;padding:10px 12px;background:#FFF8EF;border-left:4px solid #E8732A;border-radius:8px"><b style="color:#B45309;font-size:18px">There&#39;s a</b> + существительное (1 штука) &nbsp; ☝️ одна вещь<br><b style="color:#B45309;font-size:18px">There are some</b> + существительное (много) &nbsp; ✌️ две и больше<br>⚠️ <b>Важно запомнить: There&#39;s — ОДНА вещь! &nbsp; There are — ДВЕ и больше!</b></div><p style="margin:16px 0 6px;font-weight:700;color:#B4530F">Примеры</p><table style="width:100%;border-collapse:collapse"><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top"><b>✅ There&#39;s a clock.</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top;color:#6B7280">— Есть одни часы.</td></tr><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top"><b>✅ There&#39;s a chair.</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top;color:#6B7280">— Есть стул.</td></tr><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top"><b>✅ There are some books.</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top;color:#6B7280">— Есть несколько книг.</td></tr><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top"><b>✅ There are some crayons.</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top;color:#6B7280">— Есть несколько карандашей.</td></tr><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top"><b>✅ There&#39;s a board.</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top;color:#6B7280">— Есть доска.</td></tr><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top"><b>✅ There are some cupboards.</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top;color:#6B7280">— Есть несколько шкафов.</td></tr></table></div></div>$h$::text)) where id='70230df1-356a-44f9-80d1-da4d0f4b8bc7';
update classroom_blocks set payload = jsonb_set(payload,'{html}',to_jsonb($h$<div style="max-width:680px;border:1px solid #E6E0D8;border-radius:14px;overflow:hidden;font-size:15px;line-height:1.35"><div style="background:#784214;color:#fff;padding:7px 12px;font-weight:700">Grammar 1</div><div style="padding:10px 12px;background:#fff"><p style="margin:0 0 10px;font-weight:700;font-size:18px">Как спросить время и сказать, когда ты что-то делаешь?</p><div style="margin:12px 0 0;padding:10px 12px;background:#FFF8EF;border-left:4px solid #E8732A;border-radius:8px">📌 <b>Два главных вопроса о времени:</b><br>① «Который час?» — используй <b>What&#39;s the time?</b><br>② «Когда ты…?» — используй <b>When do you…?</b> &nbsp; Время всегда отвечает на вопрос с <b style="color:#E8732A">AT</b></div><div style="margin:12px 0 0;padding:10px 12px;background:#E17B20;color:#fff;border-radius:10px"><b>What&#39;s the time?</b> &nbsp;→&nbsp; <b>It&#39;s 9 o&#39;clock.</b><br><b>When do you get up?</b> &nbsp;→&nbsp; <b>At 9 o&#39;clock.</b></div><div style="margin:12px 0 0;padding:10px 12px;background:#FFF8EF;border-left:4px solid #E8732A;border-radius:8px">⚠️ <b>Важно запомнить:</b> AT seven o&#39;clock ✅</div><p style="margin:16px 0 6px;font-weight:700;color:#B4530F">Примеры</p><table style="width:100%;border-collapse:collapse"><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top"><b>✅ What&#39;s the time? It&#39;s seven o&#39;clock.</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top;color:#6B7280">— Который час? – Семь часов.</td></tr><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top"><b>✅ When do you get up? At seven o&#39;clock.</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top;color:#6B7280">— Когда ты встаёшь? – В семь.</td></tr><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top"><b>✅ When do you have lunch? At one o&#39;clock.</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top;color:#6B7280">— Когда ты обедаешь? – В час.</td></tr><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top"><b>✅ What&#39;s the time? It&#39;s three o&#39;clock.</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top;color:#6B7280">— Который час? – Три часа.</td></tr><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top"><b>✅ When do you go to bed? At ten o&#39;clock.</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top;color:#6B7280">— Когда ты ложишься? – В десять.</td></tr></table></div></div>$h$::text)) where id='7fbcb7f4-8c5e-471e-91f2-2a98936e53f3';
update classroom_blocks set payload = jsonb_set(payload,'{html}',to_jsonb($h$<div style="max-width:680px;border:1px solid #E6E0D8;border-radius:14px;overflow:hidden;font-size:15px;line-height:1.35"><div style="background:#DF751E;color:#fff;padding:7px 12px;font-weight:700">📖 Грамматика 1: likes / doesn&#39;t like</div><div style="padding:10px 12px;background:#fff"><p style="margin:0 0 6px;font-weight:700;color:#B4530F">Как сказать, что кому-то нравится или не нравится?</p><p style="margin:0 0 10px">Когда говорим про одного человека или животное (он/она/оно), глагол gets <b style="color:#C2185B">-s: likes</b>. Если нет — используем <b style="color:#C2185B">doesn&#39;t like</b> (does + not + like).</p><div style="margin:12px 0 0;padding:10px 12px;background:#FFF8EF;border-left:4px solid #E8732A;border-radius:8px">he / she / it + <b style="color:#1B793E">LIKES</b> + (noun) ✅ &nbsp;&nbsp; he / she / it + <b style="color:#C2185B">DOESN&#39;T LIKE</b> + (noun) ❌<br>⚠️ <b>Важно запомнить:</b> <i>likes (с -s!) только для he/she/it &nbsp;|&nbsp; doesn&#39;t = does + not</i></div><p style="margin:16px 0 6px;font-weight:700;color:#B4530F">Примеры</p><table style="width:100%;border-collapse:collapse"><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top"><b>✅ The tiger LIKES meat. 🍖</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top;color:#6B7280">Тигру нравится мясо.</td></tr><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top"><b>✅ The tiger DOESN&#39;T LIKE carrots. 🥕</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top;color:#6B7280">Тигру не нравится морковь.</td></tr><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top"><b>✅ The monkey LIKES bananas. 🍌</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top;color:#6B7280">Обезьяне нравятся бананы.</td></tr><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top"><b>✅ She LIKES fish. 🐟</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top;color:#6B7280">Ей нравится рыба.</td></tr><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top"><b>✅ The bear LIKES fish. 🐟</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top;color:#6B7280">Медведю нравится рыба.</td></tr><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top"><b>✅ He DOESN&#39;T LIKE peas. 🫛</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top;color:#6B7280">Ему не нравится горох.</td></tr><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top"><b>✅ The monkey DOESN&#39;T LIKE cheese. 🧀</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top;color:#6B7280">Обезьяне не нравится сыр.</td></tr></table></div></div>$h$::text)) where id='15c38a3a-3326-4508-a759-0545ad8e158e';
update classroom_blocks set payload = jsonb_set(payload,'{html}',to_jsonb($h$<div style="max-width:680px;border:1px solid #E6E0D8;border-radius:14px;overflow:hidden;font-size:15px;line-height:1.35"><div style="background:#DC691A;color:#fff;padding:7px 12px;font-weight:700">Grammar 1 — Has your town got…? ❓</div><div style="padding:10px 12px;background:#fff"><div style="margin:12px 0 0;padding:10px 12px;background:#FFFEF8;border-left:4px solid #E8C89C;border-radius:8px">📖 <b style="color:#B4530F">Как использовать?</b><br>Мы спрашиваем, ЕСТЬ ли что-то в городе.</div><div style="margin:12px 0 0;padding:10px 12px;background:#FFF8EF;border-left:4px solid #E8732A;border-radius:8px">⚠️ <b style="color:#E8732A">Формула:</b><br><b>Has your town got a [place]?</b><br>✅ <b>Yes, it has.</b> &nbsp; ❌ <b>No, it hasn&#39;t.</b></div><p style="margin:16px 0 6px;font-weight:700;color:#B4530F">Примеры</p><table style="width:100%;border-collapse:collapse"><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top"><b>✅ Has your town got a park?</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top;color:#6B7280">Есть ли в твоём городе парк?</td></tr><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top"><b>✅ Yes, it has!</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top;color:#6B7280">Да, есть!</td></tr><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top"><b>✅ Has your town got a cinema?</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top;color:#6B7280">Есть ли в твоём городе кинотеатр?</td></tr><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top"><b>✅ No, it hasn&#39;t!</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top;color:#6B7280">Нет, нет.</td></tr><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top"><b>✅ Has your town got a café?</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top;color:#6B7280">Есть ли в твоём городе кафе?</td></tr><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top"><b>✅ Has your town got a bus stop?</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top;color:#6B7280">Есть ли в твоём городе остановка?</td></tr></table></div></div>$h$::text)) where id='bb087982-608d-4707-acb4-133bfb81454c';
update classroom_blocks set payload = jsonb_set(payload,'{html}',to_jsonb($h$<div style="max-width:680px;border:1px solid #E6E0D8;border-radius:14px;overflow:hidden;font-size:15px;line-height:1.35"><div style="background:#B84F0C;color:#fff;padding:7px 12px;font-weight:700">😮 Грамматика: Would you like…?</div><div style="padding:10px 12px;background:#fff"><p style="margin:0 0 10px">Это вежливое предложение еды или напитка — используй, когда хочешь угостить кого-то.<br>Ответ: Yes, please! 😊 &nbsp;/&nbsp; No, thank you. 🙇</p><div style="margin:12px 0 0;padding:10px 12px;background:#FFF8EF;border-left:4px solid #E8732A;border-radius:8px">⚠️ <b style="color:#E8732A">Формула:</b><br><b>Would you like + <span style="color:#2F6FB8">a</span> (согл.) / <span style="color:#6B4CC4">an</span> (гласн.) / <span style="color:#1B793E">some</span> (неисч./мн.ч.) + food?</b> &nbsp;&nbsp; <i>✗ a apple → ✓ an apple</i></div><p style="margin:16px 0 6px;font-weight:700;color:#B4530F">Примеры</p><table style="width:100%;border-collapse:collapse"><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top"><span style="background:#2F6FB8;color:#fff;border-radius:6px;padding:2px 8px;font-size:14px">a</span></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top">✅ <b>Would you like a tomato?</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top;color:#6B7280">— Хочешь помидор?</td></tr><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top"><span style="background:#6B4CC4;color:#fff;border-radius:6px;padding:2px 8px;font-size:14px">an</span></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top">✅ <b>Would you like an egg?</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top;color:#6B7280">— Хочешь яйцо?</td></tr><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top"><span style="background:#1B793E;color:#fff;border-radius:6px;padding:2px 8px;font-size:14px">some</span></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top">✅ <b>Would you like some bread?</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top;color:#6B7280">— Хочешь хлеба?</td></tr><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top"><span style="background:#2F6FB8;color:#fff;border-radius:6px;padding:2px 8px;font-size:14px">a</span></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top">✅ <b>Would you like a kiwi?</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top;color:#6B7280">— Хочешь киви?</td></tr><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top"><span style="background:#1B793E;color:#fff;border-radius:6px;padding:2px 8px;font-size:14px">some</span></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top">✅ <b>Would you like some grapes?</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top;color:#6B7280">— Хочешь виноград?</td></tr><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top"><span style="background:#6B4CC4;color:#fff;border-radius:6px;padding:2px 8px;font-size:14px">an</span></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top">✅ <b>Would you like an orange?</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top;color:#6B7280">— Хочешь апельсин?</td></tr><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top"></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top">✅ — Yes, please! / No, thank you.</td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top;color:#6B7280">— — Да, пожалуйста! / Нет, спасибо.</td></tr></table></div></div>$h$::text)) where id='ca76cb04-6c6c-4dcb-aaec-d56ce1ccee32';
update classroom_blocks set payload = jsonb_set(payload,'{html}',to_jsonb($h$<div style="max-width:680px;border:1px solid #E6E0D8;border-radius:14px;overflow:hidden;font-size:15px;line-height:1.35"><div style="background:#E8732A;color:#fff;padding:7px 12px;font-weight:700">👉 Грамматика 1: This · That · These · Those</div><div style="padding:10px 12px;background:#fff"><div style="margin:12px 0 0;padding:10px 12px;background:#FFFEF8;border-left:4px solid #E8C89C;border-radius:8px">Используй эти слова вместо &quot;этот / эта / это / эти&quot; — в зависимости от расстояния и количества.</div><table style="width:100%;border-collapse:collapse"><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top"><span style="color:#E8732A;font-size:20px">THIS</span></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top;color:#6B7280">1 вещь — БЛИЗКО</td></tr><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top"><span style="color:#E8732A;font-size:20px">THAT</span></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top;color:#6B7280">1 вещь — ДАЛЕКО</td></tr><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top"><span style="color:#E8732A;font-size:20px">THESE</span></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top;color:#6B7280">много — БЛИЗКО</td></tr><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top"><span style="color:#E8732A;font-size:20px">THOSE</span></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top;color:#6B7280">много — ДАЛЕКО</td></tr></table><div style="margin:12px 0 0;padding:10px 12px;background:#FFF8EF;border-left:4px solid #E8732A;border-radius:8px">⚠️ <b>Важно:</b><br>THIS/THESE — рядом со мной &nbsp;&nbsp; THAT/THOSE — вдали<br>THIS/THAT — одна вещь &nbsp;&nbsp; THESE/THOSE — много вещей</div><p style="margin:16px 0 6px;font-weight:700;color:#B4530F">Примеры</p><table style="width:100%;border-collapse:collapse"><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top"><b>✅ I like THIS bed.</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top;color:#6B7280">— Мне нравится ЭТА кровать. (одна, рядом)</td></tr><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top"><b>✅ I like THAT lamp.</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top;color:#6B7280">— Мне нравится ТА лампа. (одна, далеко)</td></tr><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top"><b>✅ I like THESE rugs.</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top;color:#6B7280">— Мне нравятся ЭТИ ковры. (много, рядом)</td></tr><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top"><b>✅ I don&#39;t like THOSE posters.</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top;color:#6B7280">— Мне не нравятся ТЕ постеры. (много, далеко)</td></tr><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top"><b>✅ What is THAT? — It&#39;s a sofa.</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top;color:#6B7280">— Что это? — Это диван.</td></tr></table></div></div>$h$::text)) where id='9bf3a99d-779e-4889-9215-464993796b01';
update classroom_blocks set payload = jsonb_set(payload,'{html}',to_jsonb($h$<div style="max-width:680px;border:1px solid #E6E0D8;border-radius:14px;overflow:hidden;font-size:15px;line-height:1.35"><div style="background:#2B5F45;color:#fff;padding:7px 12px;font-weight:700">📗 VOCABULARY 2 — Portraits</div><div style="padding:10px 12px;background:#fff"><table style="width:100%;border-collapse:collapse"><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top"><b>🎨 painting</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top;color:#6B7280">живопись / картина</td></tr><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top"><b>✏️ drawing</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top;color:#6B7280">рисунок (карандаш)</td></tr><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top"><b>📷 photo</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top;color:#6B7280">фотография</td></tr><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top"><b>✂️ paper collage</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top;color:#6B7280">бумажный коллаж</td></tr></table><div style="margin:12px 0 0;padding:10px 12px;background:#2B7A4B;color:#fff;border-radius:10px;text-align:center">For this portrait, the artist uses <b>[paint / a pencil / a camera / paper and glue].</b></div><p style="margin:10px 0 0">✅ The person in the portrait is [young / old / happy / sad].</p><p style="margin:8px 0 0">✅ It has got lots of [colours / detail].</p></div></div>$h$::text)) where id='bff268c9-7bc8-4b9a-be5c-72389bd7b555';
update classroom_blocks set payload = jsonb_set(payload,'{html}',to_jsonb($h$<div style="max-width:680px;border:1px solid #E6E0D8;border-radius:14px;overflow:hidden;font-size:15px;line-height:1.35"><div style="background:#7D3C98;color:#fff;padding:7px 12px;font-weight:700">THE BUS TRIP</div><div style="padding:10px 12px;background:#fff"><table style="width:100%;border-collapse:collapse"><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top"><b>🚌 Off we go!</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top;color:#6B7280">Поехали! / Вперёд!</td></tr><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top"><b>😄 I&#39;m excited!</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top;color:#6B7280">Я в восторге! / Я взволнован!</td></tr><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top"><b>🐑 There&#39;s a sheep on the road!</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top;color:#6B7280">На дороге овца!</td></tr><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top"><b>🤝 It&#39;s my turn to help!</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top;color:#6B7280">Теперь моя очередь помочь!</td></tr><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top"><b>☸️ The tyre is flat!</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top;color:#6B7280">Шина спустила / Пробито колесо!</td></tr><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top"><b>😊 No problem!</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top;color:#6B7280">Нет проблем!</td></tr><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top"><b>✈️ This is the airport, not the beach!</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top;color:#6B7280">Это аэропорт, а не пляж!</td></tr></table></div></div>$h$::text)) where id='c0aeaaa2-8b1e-40d0-bd00-4733e7279a83';
update classroom_blocks set payload = jsonb_set(payload,'{html}',to_jsonb($h$<div style="max-width:680px;border:1px solid #E6E0D8;border-radius:14px;overflow:hidden;font-size:15px;line-height:1.35"><div style="background:#C2392C;color:#fff;padding:7px 12px;font-weight:700">✏️ Grammar 2: I like / I don&#39;t like + [verb]ing</div><div style="padding:10px 12px;background:#fff"><div style="margin:12px 0 0;padding:10px 12px;background:#FFFEF8;border-left:4px solid #E8C89C;border-radius:8px">После слова like глагол всегда стоит в форме -ing. Нельзя сказать &#39;I like play&#39; — только &#39;I like play<b>ING</b>&#39;.<br><i style="color:#C2392C">Для согласия: So do I! / Me too! &nbsp; Для несогласия: I don&#39;t.</i></div><div style="margin:12px 0 0;padding:10px 12px;background:#FDF1F0;border-left:4px solid #C2392C;border-radius:8px">📐 <b style="color:#C2392C">Формула:</b><br><b style="font-size:18px">I like / don&#39;t like + [verb]ing</b></div><p style="margin:16px 0 6px;font-weight:700;color:#C2392C">Примеры</p><table style="width:100%;border-collapse:collapse"><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top"><b>✅ I like playing football!</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top;color:#6B7280">Я люблю играть в футбол!</td></tr><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top"><b>✅ I don&#39;t like playing hockey.</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top;color:#6B7280">Мне не нравится хоккей.</td></tr><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top"><b>✅ I like swimming!</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top;color:#6B7280">Я люблю плавать!</td></tr><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top"><b>✅ What sport do you like doing?</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top;color:#6B7280">Какой спорт тебе нравится?</td></tr><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top"><b>✅ I like tennis! — Me too!</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top;color:#6B7280">Я тоже люблю теннис!</td></tr><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top"><b>✅ I don&#39;t like hockey. — I don&#39;t.</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top;color:#6B7280">Я тоже не люблю хоккей.</td></tr></table></div></div>$h$::text)) where id='4ece4118-8c64-4d9c-a85b-75d678830611';
update classroom_blocks set payload = jsonb_set(payload,'{html}',to_jsonb($h$<div style="max-width:680px;border:1px solid #E6E0D8;border-radius:14px;overflow:hidden;font-size:15px;line-height:1.35"><div style="background:#B6960A;color:#fff;padding:7px 12px;font-weight:700">📄 Грамматика: Вопросительные слова</div><div style="padding:10px 12px;background:#fff"><div style="margin:12px 0 0;padding:10px 12px;background:#FFFDF0;border-left:4px solid #B6960A;border-radius:8px">В английском есть разные вопросительные слова — каждое открывает свой тип вопроса. Запомни их все!</div><div style="height:10px"></div><table style="width:100%;border-collapse:collapse"><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top">🐘 <b style="color:#B6960A">Are there…?</b><br><span style="font-size:15px">Are there any animals here?</span></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top;color:#6B7280">— Здесь есть животные?</td></tr><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top">🏊 <b style="color:#B6960A">Can…?</b><br><span style="font-size:15px">Can you swim?</span></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top;color:#6B7280">— Ты умеешь плавать?</td></tr><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top">🏕️ <b style="color:#B6960A">Does…?</b><br><span style="font-size:15px">Does he like camping?</span></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top;color:#6B7280">— Ему нравится поход?</td></tr><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top">📓 <b style="color:#B6960A">Has/Have…got?</b><br><span style="font-size:15px">Has she got a scrapbook?</span></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top;color:#6B7280">— У неё есть скрапбук?</td></tr><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top">🔢 <b style="color:#B6960A">How many…?</b><br><span style="font-size:15px">How many cousins have you got?</span></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top;color:#6B7280">— Сколько у тебя кузенов?</td></tr><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top">👤 <b style="color:#B6960A">Whose…?</b><br><span style="font-size:15px">Whose comic is this?</span></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;vertical-align:top;color:#6B7280">— Чей это комикс?</td></tr></table></div></div>$h$::text)) where id='aa67616b-8f0e-417a-a290-5da869ccbc8a';
update classroom_blocks set payload = jsonb_set(payload,'{html}',to_jsonb($h$<div style="max-width:680px;border:1px solid #E6E0D8;border-radius:14px;overflow:hidden;font-size:15px;line-height:1.35"><div style="background:#E17B20;color:#fff;padding:7px 12px;font-weight:700">✖️ Unit 1 to be Отрицательная форма</div><div style="padding:10px 12px;background:#fff"><p style="margin:0 0 12px">Чтобы сказать «нет» или «не» — добавь NOT после to be.<br>Краткие формы: is not → isn't · are not → aren't. ⚠️ I'm not</p><table style="width:100%;border-collapse:collapse;background:#FFF8EF;border:2px solid #E8732A"><tr><th style="text-align:left;padding:4px 8px;color:#B4530F">Подлежащее</th><th style="text-align:left;padding:4px 8px;color:#B4530F">Полная форма</th><th style="text-align:left;padding:4px 8px;color:#B4530F">Краткая форма</th><th style="text-align:left;padding:4px 8px;color:#B4530F">Пример</th></tr><tr><td style="padding:4px 8px">I</td><td style="padding:4px 8px">am not</td><td style="padding:4px 8px"><b style="color:#E8732A">I'm not</b></td><td style="padding:4px 8px">I'm not twelve.</td></tr><tr><td style="padding:4px 8px">You / We / They</td><td style="padding:4px 8px">are not</td><td style="padding:4px 8px"><b style="color:#E8732A">aren't</b></td><td style="padding:4px 8px">They aren't here.</td></tr><tr><td style="padding:4px 8px">He / She / It</td><td style="padding:4px 8px">is not</td><td style="padding:4px 8px"><b style="color:#E8732A">isn't</b></td><td style="padding:4px 8px">She isn't British.</td></tr></table><p style="margin:14px 0 6px;color:#B4530F;font-weight:700">Примеры</p><table style="width:100%;border-collapse:collapse"><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6">✅ <b>She isn't British.</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;color:#6B7280">Она не британка.</td></tr><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6">✅ <b>They aren't at home.</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;color:#6B7280">Они не дома.</td></tr><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6">✅ <b>I'm not twelve.</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;color:#6B7280">Мне не двенадцать.</td></tr><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6">✅ <b>His brother isn't Spanish.</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;color:#6B7280">Его брат не испанец.</td></tr><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6">✅ <b>We aren't from France.</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;color:#6B7280">Мы не из Франции.</td></tr><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6">✅ <b>Kit isn't Dug's sister.</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;color:#6B7280">Кит не сестра Дага.</td></tr></table></div></div>$h$::text)) where id='0700a8b8-24c2-46f8-88a8-dec487ff5a5c';
update classroom_blocks set payload = jsonb_set(payload,'{html}',to_jsonb($h$<div style="max-width:680px;border:1px solid #E6E0D8;border-radius:14px;overflow:hidden;font-size:15px;line-height:1.35"><div style="background:#B85700;color:#fff;padding:7px 12px;font-weight:700">Вопросы с to be: Am / Is / Are?</div><div style="padding:10px 12px;background:#fff"><p style="margin:0 0 12px">В вопросе глагол AM / IS / ARE ставится В НАЧАЛО предложения. Порядок слов меняется!</p><div style="background:#FDF3D2;border:2px solid #D79B2A;border-radius:10px;padding:10px 12px;text-align:center"><p style="margin:0 0 6px">Утверждение: <b style="color:#2E9E6B">I am cool.</b> → Вопрос: <b style="color:#B85700">Am I cool?</b></p><p style="margin:0;font-size:15px">⚠️ AM / IS / ARE переносим В НАЧАЛО вопроса!</p></div><p style="margin:14px 0 6px;font-weight:700">Правило:</p><table style="width:100%;border-collapse:collapse"><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;color:#6B7280;font-style:italic">I am cool.</td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;text-align:center">→</td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;background:#FDF3D2"><b style="color:#B85700">Am</b> I cool?</td></tr><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;color:#6B7280;font-style:italic">You are sure.</td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;text-align:center">→</td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;background:#FDF3D2"><b style="color:#B85700">Are</b> you sure?</td></tr><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;color:#6B7280;font-style:italic">He is cool.</td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;text-align:center">→</td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;background:#FDF3D2"><b style="color:#B85700">Is</b> he cool?</td></tr><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;color:#6B7280;font-style:italic">They are OK.</td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;text-align:center">→</td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;background:#FDF3D2"><b style="color:#B85700">Are</b> they OK?</td></tr></table></div></div>$h$::text)) where id='e286f503-285a-4eed-ad94-cb6b0d28ae4e';
update classroom_blocks set payload = jsonb_set(payload,'{html}',to_jsonb($h$<div style="max-width:680px;border:1px solid #E6E0D8;border-radius:14px;overflow:hidden;font-size:15px;line-height:1.35"><div style="background:#E57822;color:#fff;padding:7px 12px;font-weight:700">❓ There isn't / There aren't / Вопросы</div><div style="padding:10px 12px;background:#fff"><p style="margin:0 0 12px">Чтобы сказать, что чего-то НЕТ — используй isn't или aren't. Чтобы спросить — поставь Is/Are перед there.</p><div style="background:#E8732A;color:#fff;border-radius:10px;padding:10px 12px;margin-bottom:8px"><div>✖️ <b>There isn't</b> + singular</div><div>✖️ <b>There aren't</b> + plural</div></div><div style="background:#1A5FBF;color:#fff;border-radius:10px;padding:10px 12px;margin-bottom:8px"><div>❓ <b>Is there</b> + singular?</div><div>❓ <b>Are there</b> + plural?</div></div><div style="background:#FDF0F4;border:1px solid #F3C4D6;border-radius:10px;padding:10px 12px;margin-bottom:12px"><b style="color:#D94A77">Краткие ответы:</b> ✅ Yes, there is. ✅ Yes, there are. ❌ No, there isn't. ❌ No, there aren't.</div><table style="width:100%;border-collapse:collapse"><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6">✅ <b>There isn't a cat in the bedroom.</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;color:#6B7280">— В спальне нет кошки.</td></tr><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6">✅ <b>There aren't any books on the desk.</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;color:#6B7280">— На столе нет книг.</td></tr><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6">✅ <b>Is there a fridge in the kitchen?</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;color:#6B7280">— Есть ли холодильник на кухне?</td></tr><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6">✅ <b>Are there any plants in the living room?</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;color:#6B7280">— Есть ли растения в гостиной?</td></tr><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6">✅ <b>No, there aren't.</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;color:#6B7280">— Нет, их нет.</td></tr></table></div></div>$h$::text)) where id='4cea7020-0459-44e0-9bbd-8ad3b4490f08';
update classroom_blocks set payload = jsonb_set(payload,'{html}',to_jsonb($h$<div style="max-width:680px;border:1px solid #E6E0D8;border-radius:14px;overflow:hidden;font-size:15px;line-height:1.35"><div style="background:#D9822B;color:#fff;padding:7px 12px;font-weight:700">have got — утвердительная и отрицательная форма</div><div style="padding:10px 12px;background:#fff"><p style="margin:0 0 12px">Используй have got, чтобы сказать, что у тебя есть (или нет).<br>С <b>he / she / it</b> → has got / hasn't got. С остальными → have got / haven't got.</p><div style="background:#FFF3E6;border:2px solid #E8732A;border-radius:10px;padding:10px 12px"><p style="margin:0 0 6px">✅ <b style="color:#B4530F">Affirmative:</b> I / You / We / They <b style="color:#E8732A">have got</b> · He / She / It <b style="color:#E8732A">has got</b></p><p style="margin:0">❌ <b style="color:#B4530F">Negative:</b> I / You / We / They <b style="color:#E8732A">haven't got</b> · He / She / It <b style="color:#E8732A">hasn't got</b></p></div><p style="margin:12px 0 0;padding:10px 12px;background:#FFFBEF;border-left:4px solid #D79B2A;border-radius:8px">⚠️ <b>Важно:</b> 've = have, 's = has. Краткая форма = то же значение: I've got = I have got!</p><p style="margin:14px 0 6px;color:#B4530F;font-weight:700">Примеры</p><table style="width:100%;border-collapse:collapse"><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6">✅ <b>I've got long hair.</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;color:#6B7280">— У меня длинные волосы.</td></tr><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6">✅ <b>She hasn't got big feet.</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;color:#6B7280">— У неё нет больших ступней.</td></tr><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6">✅ <b>We've got a lot of time.</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;color:#6B7280">— У нас много времени.</td></tr><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6">✅ <b>He hasn't got curly hair.</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;color:#6B7280">— У него нет кудрявых волос.</td></tr><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6">✅ <b>They've got super eyes.</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;color:#6B7280">— У них суперзрение.</td></tr><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6">✅ <b>It hasn't got battery power.</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;color:#6B7280">— У него нет заряда батарейки.</td></tr></table></div></div>$h$::text)) where id='79c075ba-1dc3-4793-8fed-1231b76be711';
update classroom_blocks set payload = jsonb_set(payload,'{html}',to_jsonb($h$<div style="max-width:680px;border:1px solid #E6E0D8;border-radius:14px;overflow:hidden;font-size:15px;line-height:1.35"><div style="background:#7B3AEB;color:#fff;padding:7px 12px;font-weight:700">🎫 Buying a Ticket</div><div style="padding:10px 12px;background:#fff"><table style="width:100%;border-collapse:collapse"><tr><td style="padding:8px 6px;border-bottom:1px solid #F0ECE6;vertical-align:top;white-space:nowrap"><span style="display:inline-block;background:#C94B9B;color:#fff;border-radius:6px;padding:2px 8px;font-weight:700">A</span></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;background:#FDF0F8"><b style="color:#7B3AEB">Can I help you?</b><div style="color:#6B7280;font-size:14px">Чем могу помочь?</div></td></tr><tr><td style="padding:8px 6px;border-bottom:1px solid #F0ECE6;vertical-align:top;white-space:nowrap"><span style="display:inline-block;background:#7B3AEB;color:#fff;border-radius:6px;padding:2px 8px;font-weight:700">B</span></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;background:#F3EEFD"><b style="color:#7B3AEB">Can I have one ticket to the zoo, please?</b><div style="color:#6B7280;font-size:14px">Можно один билет в зоопарк, пожалуйста?</div></td></tr><tr><td style="padding:8px 6px;border-bottom:1px solid #F0ECE6;vertical-align:top;white-space:nowrap"><span style="display:inline-block;background:#C94B9B;color:#fff;border-radius:6px;padding:2px 8px;font-weight:700">A</span></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;background:#FDF0F8"><b style="color:#7B3AEB">That's £18.50, please.</b><div style="color:#6B7280;font-size:14px">С вас 18 фунтов 50 пенсов.</div></td></tr><tr><td style="padding:8px 6px;border-bottom:1px solid #F0ECE6;vertical-align:top;white-space:nowrap"><span style="display:inline-block;background:#7B3AEB;color:#fff;border-radius:6px;padding:2px 8px;font-weight:700">B</span></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;background:#F3EEFD"><b style="color:#7B3AEB">Here you are.</b><div style="color:#6B7280;font-size:14px">Пожалуйста. (подаёте деньги)</div></td></tr><tr><td style="padding:8px 6px;border-bottom:1px solid #F0ECE6;vertical-align:top;white-space:nowrap"><span style="display:inline-block;background:#C94B9B;color:#fff;border-radius:6px;padding:2px 8px;font-weight:700">A</span></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;background:#FDF0F8"><b style="color:#7B3AEB">Here's your ticket.</b><div style="color:#6B7280;font-size:14px">Вот ваш билет.</div></td></tr><tr><td style="padding:8px 6px;border-bottom:1px solid #F0ECE6;vertical-align:top;white-space:nowrap"><span style="display:inline-block;background:#7B3AEB;color:#fff;border-radius:6px;padding:2px 8px;font-weight:700">B</span></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;background:#F3EEFD"><b style="color:#7B3AEB">Thanks.</b><div style="color:#6B7280;font-size:14px">Спасибо.</div></td></tr></table><p style="margin:12px 0 0;font-size:14px;color:#6B7280">A = кассир (Attendant) · B = покупатель (Visitor)</p></div></div>$h$::text)) where id='90121cdc-b251-465b-8ad7-83318f6f2cd2';
update classroom_blocks set payload = jsonb_set(payload,'{html}',to_jsonb($h$<div style="max-width:680px;border:1px solid #E6E0D8;border-radius:14px;overflow:hidden;font-size:15px;line-height:1.35"><div style="background:#D37218;color:#fff;padding:7px 12px;font-weight:700">📖 вопросительные слова</div><div style="padding:10px 12px;background:#fff"><div style="border:1px solid #E6D3BC;border-radius:10px;overflow:hidden;margin-bottom:8px"><div style="background:#D37218;color:#fff;padding:6px 12px;font-weight:700;text-align:center">WHERE</div><div style="padding:8px 12px;background:#FFF8EF"><div><b>где? / куда?</b></div><div style="color:#D37218">Where do you live?</div><div style="color:#6B7280;font-style:italic">Где ты живёшь?</div></div></div><div style="border:1px solid #E6D3BC;border-radius:10px;overflow:hidden;margin-bottom:8px"><div style="background:#D37218;color:#fff;padding:6px 12px;font-weight:700;text-align:center">WHO</div><div style="padding:8px 12px;background:#FFF8EF"><div><b>кто?</b></div><div style="color:#D37218">Who is your hero?</div><div style="color:#6B7280;font-style:italic">Кто твой герой?</div></div></div><div style="border:1px solid #E6D3BC;border-radius:10px;overflow:hidden;margin-bottom:8px"><div style="background:#D37218;color:#fff;padding:6px 12px;font-weight:700;text-align:center">WHAT</div><div style="padding:8px 12px;background:#FFF8EF"><div><b>что? / какой?</b></div><div style="color:#D37218">What sport do you like?</div><div style="color:#6B7280;font-style:italic">Какой спорт тебе нравится?</div></div></div><div style="border:1px solid #E6D3BC;border-radius:10px;overflow:hidden;margin-bottom:8px"><div style="background:#D37218;color:#fff;padding:6px 12px;font-weight:700;text-align:center">WHEN</div><div style="padding:8px 12px;background:#FFF8EF"><div><b>когда?</b></div><div style="color:#D37218">When is your birthday?</div><div style="color:#6B7280;font-style:italic">Когда твой день рождения?</div></div></div><div style="border:1px solid #E6D3BC;border-radius:10px;overflow:hidden;margin-bottom:8px"><div style="background:#D37218;color:#fff;padding:6px 12px;font-weight:700;text-align:center">HOW MANY</div><div style="padding:8px 12px;background:#FFF8EF"><div><b>сколько?</b></div><div style="color:#D37218">How many sisters have you got?</div><div style="color:#6B7280;font-style:italic">Сколько у тебя сестёр?</div></div></div><div style="border:1px solid #E6D3BC;border-radius:10px;overflow:hidden;margin-bottom:8px"><div style="background:#D37218;color:#fff;padding:6px 12px;font-weight:700;text-align:center">WHOSE</div><div style="padding:8px 12px;background:#FFF8EF"><div><b>чей? / чья?</b></div><div style="color:#D37218">Whose bike is this?</div><div style="color:#6B7280;font-style:italic">Чей это велосипед?</div></div></div></div></div>$h$::text)) where id='68aadfa8-8cd9-4f38-821d-f249140b05ae';
update classroom_blocks set payload = jsonb_set(payload,'{html}',to_jsonb($h$<div style="max-width:680px;border:1px solid #E6E0D8;border-radius:14px;overflow:hidden;font-size:15px;line-height:1.35"><div style="padding:10px 12px;background:#fff"><table style="width:100%;border-collapse:collapse"><tr><td style="padding:10px;border-bottom:1px solid #F0ECE6"><b style="font-size:18px">Pass me the box, please</b><div style="color:#6B7280">Передай ту коробку, пожалуйста</div></td></tr><tr><td style="padding:10px;border-bottom:1px solid #F0ECE6"><b style="font-size:18px">Watch out!</b><div style="color:#6B7280">Берегись! Осторожно!</div></td></tr><tr><td style="padding:10px;border-bottom:1px solid #F0ECE6"><b style="font-size:18px">— I'm sorry.<br>— It's OK.</b><div style="color:#6B7280">— Простите / Извините.<br>— Всё в порядке / Ничего страшного.</div></td></tr><tr><td style="padding:10px;border-bottom:1px solid #F0ECE6"><b style="font-size:18px">— My notebook.<br>— Here you are.</b><div style="color:#6B7280">— Моя тетрадь.<br>— Вот, возьми.</div></td></tr></table></div></div>$h$::text)) where id='7c540efb-0916-4859-bab7-2ecda4774b6e';
update classroom_blocks set payload = jsonb_set(payload,'{html}',to_jsonb($h$<div style="max-width:680px;border:1px solid #E6E0D8;border-radius:14px;overflow:hidden;font-size:15px;line-height:1.35"><div style="background:#F39E12;color:#fff;padding:7px 12px;font-weight:700">📌 Grammar — in / on / under (Предлоги места)</div><div style="padding:10px 12px;background:#fff"><p style="margin:0 0 12px;padding:10px 12px;background:#FFFBEF;border-radius:10px">📖 Чтобы сказать, <b style="color:#E8732A">ГДЕ</b> находится предмет или животное, используем предлоги: <b style="color:#2F6FB8">in</b> (в), <b style="color:#2E9E6B">on</b> (на), <b style="color:#D94A77">under</b> (под).</p><div style="background:#EAF3FC;border:1px solid #9CC4E8;border-radius:10px;padding:10px 12px;margin-bottom:8px;text-align:center"><div style="font-size:24px;font-weight:700;color:#2F6FB8">IN</div><div style="color:#6B7280;text-transform:uppercase">в</div><div style="margin-top:8px"><b>The frog is IN the bag.</b></div><div style="color:#6B7280;font-size:14px">Лягушка В рюкзаке.</div></div><div style="background:#EDF9F1;border:1px solid #9FD9B6;border-radius:10px;padding:10px 12px;margin-bottom:8px;text-align:center"><div style="font-size:24px;font-weight:700;color:#2E9E6B">ON</div><div style="color:#6B7280;text-transform:uppercase">на</div><div style="margin-top:8px"><b>The cat is ON the book.</b></div><div style="color:#6B7280;font-size:14px">Кошка НА книге.</div></div><div style="background:#FDEFF1;border:1px solid #F0B5BF;border-radius:10px;padding:10px 12px;margin-bottom:8px;text-align:center"><div style="font-size:24px;font-weight:700;color:#D94A77">UNDER</div><div style="color:#6B7280;text-transform:uppercase">под</div><div style="margin-top:8px"><b>The dog is UNDER the chair.</b></div><div style="color:#6B7280;font-size:14px">Собака ПОД стулом.</div></div><p style="margin:12px 0 0;padding:10px 12px;background:#FFFBEF;border-left:4px solid #E8A33C;border-radius:8px">✅ <b style="color:#E8732A">Формула:</b> The [pet] is <b style="color:#E8732A">in / on / under</b> the [place].</p><p style="margin:14px 0 6px;color:#E8732A;font-weight:700">📝 More Examples / Ещё примеры</p><table style="width:100%;border-collapse:collapse"><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6">✅ <b>The spider is in the bag.</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;color:#6B7280">— Паук в рюкзаке.</td></tr><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6">✅ <b>The lizard is on the chair.</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;color:#6B7280">— Ящерица на стуле.</td></tr><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6">✅ <b>The rat is on the desk.</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;color:#6B7280">— Крыса на парте.</td></tr><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6">✅ <b>The elephant is under the bed!</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;color:#6B7280">— Слон под кроватью!</td></tr><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6">✅ <b>The duck is under the hat.</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;color:#6B7280">— Утка под шляпой.</td></tr></table></div></div>$h$::text)) where id='95c11d9d-85f0-4a1a-b21e-cd587ddb802d';
update classroom_blocks set payload = jsonb_set(payload,'{html}',to_jsonb($h$<div style="max-width:680px;border:1px solid #E6E0D8;border-radius:14px;overflow:hidden;font-size:15px;line-height:1.35"><div style="background:#EA499B;color:#fff;padding:7px 12px;font-weight:700">📖 Story — "The Cap" (Key Phrases)</div><div style="padding:10px 12px;background:#fff"><table style="width:100%;border-collapse:collapse"><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;border-left:5px solid #2F6FB8;background:#EAF3FC"><b>My cap isn't here.</b><div style="color:#6B7280;font-size:14px">Моей кепки тут нет.</div></td></tr><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;border-left:5px solid #D94A77;background:#FDEFF4"><b>Look! Gary's wearing my cap.</b><div style="color:#6B7280;font-size:14px">Смотри! Гэри носит мою кепку.</div></td></tr><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;border-left:5px solid #2E9E6B;background:#EDF9F1"><b>Are you sure?</b><div style="color:#6B7280;font-size:14px">Ты уверена?</div></td></tr><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;border-left:5px solid #E8C13C;background:#FDF8DC"><b>Stop! That's my cap.</b><div style="color:#6B7280;font-size:14px">Стой! Это моя кепка.</div></td></tr><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;border-left:5px solid #E8732A;background:#FDEEE6"><b>No, it's my cap.</b><div style="color:#6B7280;font-size:14px">Нет, это моя кепка.</div></td></tr><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;border-left:5px solid #2F6FB8;background:#EAF3FC"><b>Get my cap, please.</b><div style="color:#6B7280;font-size:14px">Достань мою кепку, пожалуйста.</div></td></tr><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;border-left:5px solid #8B5CF6;background:#F3EEFD"><b>I'm very sorry, Gary.</b><div style="color:#6B7280;font-size:14px">Мне очень жаль, Гэри.</div></td></tr><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;border-left:5px solid #2E9E6B;background:#EDF9F1"><b>It's OK.</b><div style="color:#6B7280;font-size:14px">Всё хорошо.</div></td></tr></table><div style="margin-top:12px;padding:10px 12px;background:#F6EEFD;border:1px solid #D9C4F5;border-radius:10px"><p style="margin:0 0 4px;color:#7B3AEB;font-weight:700">📖 Phonics — звуки /sp/ и /st/</p><p style="margin:0">"There are <b style="color:#D94A77">st</b>ripes and <b style="color:#D94A77">sp</b>ots on the socks on the <b style="color:#D94A77">st</b>airs." <span style="color:#6B7280;font-style:italic">— /sp/ и /st/ в начале слова!</span></p></div></div></div>$h$::text)) where id='69bae971-c072-4757-8678-375ccdaeba83';
update classroom_blocks set payload = jsonb_set(payload,'{html}',to_jsonb($h$<div style="max-width:680px;border:1px solid #E6E0D8;border-radius:14px;overflow:hidden;font-size:15px;line-height:1.35"><div style="background:#1A4B8A;color:#fff;padding:7px 12px;font-weight:700">Vocabulary: Numbers 10-100</div><div style="padding:10px 12px;background:#fff"><p style="margin:0 0 8px;font-weight:700;color:#1A4B8A">Десятки:</p><table style="width:100%;border-collapse:separate;border-spacing:6px"><tr><td style="padding:4px 8px;background:#F7FAF8;border:1px solid #E6E0D8;border-radius:10px;vertical-align:middle"><div style="text-align:center"><div style="font-size:26px;font-weight:700;color:#1A6BC4">10</div><div style="color:#6B7280;font-size:14px">ten</div></div></td><td style="padding:4px 8px;background:#F7FAF8;border:1px solid #E6E0D8;border-radius:10px;vertical-align:middle"><div style="text-align:center"><div style="font-size:26px;font-weight:700;color:#1A6BC4">20</div><div style="color:#6B7280;font-size:14px">twenty</div></div></td><td style="padding:4px 8px;background:#F7FAF8;border:1px solid #E6E0D8;border-radius:10px;vertical-align:middle"><div style="text-align:center"><div style="font-size:26px;font-weight:700;color:#1A6BC4">30</div><div style="color:#6B7280;font-size:14px">thirty</div></div></td><td style="padding:4px 8px;background:#F7FAF8;border:1px solid #E6E0D8;border-radius:10px;vertical-align:middle"><div style="text-align:center"><div style="font-size:26px;font-weight:700;color:#1A6BC4">40</div><div style="color:#6B7280;font-size:14px">forty</div></div></td><td style="padding:4px 8px;background:#F7FAF8;border:1px solid #E6E0D8;border-radius:10px;vertical-align:middle"><div style="text-align:center"><div style="font-size:26px;font-weight:700;color:#1A6BC4">50</div><div style="color:#6B7280;font-size:14px">fifty</div></div></td></tr><tr><td style="padding:4px 8px;background:#F7FAF8;border:1px solid #E6E0D8;border-radius:10px;vertical-align:middle"><div style="text-align:center"><div style="font-size:26px;font-weight:700;color:#1A6BC4">60</div><div style="color:#6B7280;font-size:14px">sixty</div></div></td><td style="padding:4px 8px;background:#F7FAF8;border:1px solid #E6E0D8;border-radius:10px;vertical-align:middle"><div style="text-align:center"><div style="font-size:26px;font-weight:700;color:#1A6BC4">70</div><div style="color:#6B7280;font-size:14px">seventy</div></div></td><td style="padding:4px 8px;background:#F7FAF8;border:1px solid #E6E0D8;border-radius:10px;vertical-align:middle"><div style="text-align:center"><div style="font-size:26px;font-weight:700;color:#1A6BC4">80</div><div style="color:#6B7280;font-size:14px">eighty</div></div></td><td style="padding:4px 8px;background:#F7FAF8;border:1px solid #E6E0D8;border-radius:10px;vertical-align:middle"><div style="text-align:center"><div style="font-size:26px;font-weight:700;color:#1A6BC4">90</div><div style="color:#6B7280;font-size:14px">ninety</div></div></td><td style="padding:4px 8px;background:#F7FAF8;border:1px solid #E6E0D8;border-radius:10px;vertical-align:middle"><div style="text-align:center"><div style="font-size:26px;font-weight:700;color:#1A6BC4">100</div><div style="color:#6B7280;font-size:14px">one hundred</div></div></td></tr></table><div style="margin-top:12px;padding:10px 12px;background:#EAF3FC;border:1px solid #9CC4E8;border-radius:10px"><p style="margin:0 0 6px;font-weight:700;color:#1A4B8A">💡 Как читать двузначные числа:</p><p style="margin:0">thirty-THREE (33) = thirty + three &nbsp;|&nbsp; sixty-SIX (66) = sixty + six &nbsp;|&nbsp; eighty-EIGHT (88) = eighty + eight</p></div></div></div>$h$::text)) where id='33b3817e-8b00-4c8b-bf93-60c229c6687a';
update classroom_blocks set payload = jsonb_set(payload,'{html}',to_jsonb($h$<div style="max-width:680px;border:1px solid #E6E0D8;border-radius:14px;overflow:hidden;font-size:15px;line-height:1.35"><div style="background:#784214;color:#fff;padding:7px 12px;font-weight:700">Grammar 2</div><div style="padding:10px 12px;background:#fff"><p style="margin:0 0 12px;font-size:19px;font-weight:700;color:#B4530F">Как рассказать о том, что делает ОН или ОНА?</p><div style="background:#FFF8EF;border:2px solid #D79B2A;border-radius:10px;padding:10px 12px"><p style="margin:0 0 4px"><b style="color:#D94A77">📌 Правило +s / +es:</b></p><p style="margin:0">Когда мы говорим о ком-то другом (он / она), глагол меняется — к нему добавляется <b style="color:#D94A77">-s</b> или <b style="color:#D94A77">-es</b>.</p></div><p style="margin:10px 0;padding:10px 12px;background:#E8732A;color:#fff;border-radius:10px;text-align:center">★ He / She / It + verb + S / ES &nbsp;&nbsp; I walk → She walk<b>S</b> · I go → She go<b>ES</b> · I have → She <b>HAS</b> ★</p><p style="margin:0 0 0;padding:10px 12px;background:#FFFBEF;border-left:4px solid #D79B2A;border-radius:8px">⚠️ Неправильные формы: have → <b>has</b> ★ go → <b>goes</b> ★ watch → <b>watches</b> ★</p><p style="margin:14px 0 6px;color:#B4530F;font-weight:700">Примеры</p><table style="width:100%;border-collapse:collapse"><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6">✅ <b>She walkS to school.</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;color:#6B7280">— Она ходит в школу.</td></tr><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6">✅ <b>She playS in the park.</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;color:#6B7280">— Она играет в парке.</td></tr><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6">✅ <b>She has dinner. ★</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;color:#6B7280">— Она ужинает.</td></tr><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6">✅ <b>She watchES TV. ★</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;color:#6B7280">— Она смотрит ТВ.</td></tr><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6">✅ <b>He goES to bed early.</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;color:#6B7280">— Он рано ложится.</td></tr><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6">✅ <b>He getS up at seven.</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;color:#6B7280">— Он встаёт в семь.</td></tr></table></div></div>$h$::text)) where id='c3f80c5f-6ca3-48ff-af49-6707445f5456';
update classroom_blocks set payload = jsonb_set(payload,'{html}',to_jsonb($h$<div style="max-width:680px;border:1px solid #E6E0D8;border-radius:14px;overflow:hidden;font-size:15px;line-height:1.35"><div style="background:#AF5F01;color:#fff;padding:7px 12px;font-weight:700">❓ Грамматика 2: Does she/he like...?</div><div style="padding:10px 12px;background:#fff"><p style="margin:0 0 12px"><b style="color:#B4530F">Как спросить, нравится ли кому-то что-то?</b><br>Для вопроса про одного (он/она/оно) используем <b style="color:#E8732A">DOES</b> + подлежащее + <b style="color:#E8732A">LIKE</b> (без -s!).<br>Краткий ответ: Yes, she/he/it does / No, she/he/it doesn't.</p><div style="background:#FFF8EF;border:2px solid #D79B2A;border-radius:10px;padding:10px 12px"><p style="margin:0 0 6px">❓ <b style="color:#B85700">Does</b> she / he / it <b style="color:#B85700">like</b> ___? &nbsp; ✅ Yes, she / he / it <b style="color:#2E9E6B">does!</b> &nbsp; ❌ No, she / he / it <b style="color:#D94A77">doesn't.</b></p><p style="margin:0;font-size:15px">⚠️ <b>Важно:</b> <i>В вопросе DOES берёт -s на себя, поэтому LIKE без -s! | doesn't = does + not</i></p></div><table style="width:100%;border-collapse:collapse;margin-top:12px"><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6"><b style="color:#1A4B8A">Does the tiger like meat?</b> 🍖<div style="color:#6B7280;font-style:italic">Тигру нравится мясо?</div></td></tr><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;background:#EDF9F1"><b style="color:#1F7A4A">Yes, it does!</b> ✅<div style="color:#6B7280;font-style:italic">Да, нравится!</div></td></tr><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6"><b style="color:#1A4B8A">Does she like fish?</b> 🐟<div style="color:#6B7280;font-style:italic">Ей нравится рыба?</div></td></tr><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;background:#EDF9F1"><b style="color:#1F7A4A">Yes, she does!</b> ✅<div style="color:#6B7280;font-style:italic">Да, нравится!</div></td></tr><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6"><b style="color:#1A4B8A">Does the monkey like cheese?</b> 🧀<div style="color:#6B7280;font-style:italic">Обезьяне нравится сыр?</div></td></tr><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6"><b style="color:#1A4B8A">Does he like peas?</b> 🫛<div style="color:#6B7280;font-style:italic">Ему нравится горох?</div></td></tr><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;background:#FDEFF4"><b style="color:#B03A5B">No, it doesn't.</b> ❌<div style="color:#6B7280;font-style:italic">Нет, не нравится.</div></td></tr><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;background:#FDEFF4"><b style="color:#B03A5B">No, he doesn't.</b> ❌<div style="color:#6B7280;font-style:italic">Нет, не нравится.</div></td></tr></table></div></div>$h$::text)) where id='05c1242a-f77d-4f3a-8b31-1f2c4fd37d35';
update classroom_blocks set payload = jsonb_set(payload,'{html}',to_jsonb($h$<div style="max-width:680px;border:1px solid #E6E0D8;border-radius:14px;overflow:hidden;font-size:15px;line-height:1.35"><div style="background:#DC691C;color:#fff;padding:7px 12px;font-weight:700">Grammar 2 — Prepositions of Place 📍</div><div style="padding:10px 12px;background:#fff"><table style="width:100%;border-collapse:separate;border-spacing:6px"><tr><td style="padding:4px 8px;background:#F7FAF8;border:1px solid #E6E0D8;border-radius:10px;vertical-align:middle"><div style="border:1px solid #E6D3BC;border-radius:10px;background:#FFF8EF;padding:10px 6px;text-align:center"><div style="font-weight:700;color:#B4530F">next to</div><div style="margin:10px 0"><span style="display:inline-block;width:30px;height:26px;background:#3FBBC4;border:2px solid #1F2937;vertical-align:middle"></span>&nbsp;<span style="display:inline-block;width:20px;height:20px;border-radius:50%;background:#1F2937;vertical-align:middle"></span></div><div style="color:#6B7280;font-style:italic">рядом с</div></div></td><td style="padding:4px 8px;background:#F7FAF8;border:1px solid #E6E0D8;border-radius:10px;vertical-align:middle"><div style="border:1px solid #E6D3BC;border-radius:10px;background:#FFF8EF;padding:10px 6px;text-align:center"><div style="font-weight:700;color:#B4530F">in front of</div><div style="margin:10px 0"><span style="display:inline-block;width:30px;height:26px;background:#3FBBC4;border:2px solid #1F2937;vertical-align:middle"></span><span style="display:inline-block;width:20px;height:20px;border-radius:50%;background:#1F2937;vertical-align:middle"></span></div><div style="color:#6B7280;font-style:italic">перед</div></div></td></tr><tr><td style="padding:4px 8px;background:#F7FAF8;border:1px solid #E6E0D8;border-radius:10px;vertical-align:middle"><div style="border:1px solid #E6D3BC;border-radius:10px;background:#FFF8EF;padding:10px 6px;text-align:center"><div style="font-weight:700;color:#B4530F">behind</div><div style="margin:10px 0"><span style="display:inline-block;width:14px;height:14px;border-radius:50%;background:#1F2937;vertical-align:top"></span><span style="display:inline-block;width:30px;height:26px;background:#3FBBC4;border:2px solid #1F2937;vertical-align:middle"></span></div><div style="color:#6B7280;font-style:italic">позади / за</div></div></td><td style="padding:4px 8px;background:#F7FAF8;border:1px solid #E6E0D8;border-radius:10px;vertical-align:middle"><div style="border:1px solid #E6D3BC;border-radius:10px;background:#FFF8EF;padding:10px 6px;text-align:center"><div style="font-weight:700;color:#B4530F">between</div><div style="margin:10px 0"><span style="display:inline-block;width:30px;height:26px;background:#3FBBC4;border:2px solid #1F2937;vertical-align:middle"></span>&nbsp;<span style="display:inline-block;width:20px;height:20px;border-radius:50%;background:#1F2937;vertical-align:middle"></span>&nbsp;<span style="display:inline-block;width:30px;height:26px;background:#3FBBC4;border:2px solid #1F2937;vertical-align:middle"></span></div><div style="color:#6B7280;font-style:italic">между (двумя)</div><div style="font-size:13px;color:#B4530F">⚠️ всегда два объекта!</div></div></td></tr></table><p style="margin:14px 0 6px;font-weight:700">Примеры предложений:</p><table style="width:100%;border-collapse:collapse"><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6">✅ <b>The cinema is next to the café.</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;color:#6B7280">Кинотеатр стоит рядом с кафе.</td></tr><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6">✅ <b>The park is behind the hospital.</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;color:#6B7280">Парк находится за больницей.</td></tr><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6">✅ <b>Alex is in front of the school.</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;color:#6B7280">Алекс стоит перед школой.</td></tr><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6">✅ <b>The shop is between the café and the cinema.</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;color:#6B7280">Магазин между кафе и кинотеатром.</td></tr></table></div></div>$h$::text)) where id='aacc637d-3718-4548-a0ed-5130f7b5a44d';
update classroom_blocks set payload = jsonb_set(payload,'{html}',to_jsonb($h$<div style="max-width:680px;border:1px solid #E6E0D8;border-radius:14px;overflow:hidden;font-size:15px;line-height:1.35"><div style="background:#B84F0C;color:#fff;padding:7px 12px;font-weight:700">🧊 Грамматика: Is / Are there any...? &nbsp;<span style="font-weight:400;font-size:14px">Unit 4 · Урок 3</span></div><div style="padding:10px 12px;background:#fff"><div style="padding:10px 12px;border:1px solid #E6D3BC;border-radius:10px;margin-bottom:10px"><p style="margin:0 0 4px">Спрашиваем: есть ли еда где-то?</p><p style="margin:0"><b>IS</b> — для неисчисляемого (bread, milk, cheese). <b>ARE</b> — для исчисляемого мн.ч. (eggs, apples, tomatoes).</p></div><div style="background:#E8732A;color:#fff;border-radius:10px;padding:10px 12px;margin-bottom:8px"><p style="margin:0 0 6px;font-weight:700">IS there any...? (bread / cheese / milk / water)</p><p style="margin:0">✅ Yes, there IS.</p><p style="margin:0">❌ No, there ISN'T any.</p></div><div style="background:#B03A12;color:#fff;border-radius:10px;padding:10px 12px;margin-bottom:12px"><p style="margin:0 0 6px;font-weight:700">ARE there any...? (eggs / apples / grapes / tomatoes)</p><p style="margin:0">✅ Yes, there ARE.</p><p style="margin:0">❌ No, there AREN'T any.</p></div><table style="width:100%;border-collapse:collapse"><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;white-space:nowrap"><span style="display:inline-block;background:#2F6FB8;color:#fff;border-radius:6px;padding:2px 10px;font-weight:700">IS</span></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6">✅ <b>Is there any bread?</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;color:#6B7280;font-style:italic">— Есть хлеб?</td></tr><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6"></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;background:#FFF8EF">Yes, there is. / No, there isn't any.</td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;background:#FFF8EF;color:#6B7280;font-style:italic">— Да, есть. / Нет.</td></tr><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6"><span style="display:inline-block;background:#7B3AEB;color:#fff;border-radius:6px;padding:2px 10px;font-weight:700">ARE</span></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6">✅ <b>Are there any eggs?</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;color:#6B7280;font-style:italic">— Есть яйца?</td></tr><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6"></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;background:#FFF8EF">Yes, there are. / No, there aren't any.</td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;background:#FFF8EF;color:#6B7280;font-style:italic">— Да, есть. / Нет, нет.</td></tr><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6"><span style="display:inline-block;background:#2F6FB8;color:#fff;border-radius:6px;padding:2px 10px;font-weight:700">IS</span></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6">✅ <b>Is there any cheese?</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;color:#6B7280;font-style:italic">— Есть сыр?</td></tr><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6"><span style="display:inline-block;background:#7B3AEB;color:#fff;border-radius:6px;padding:2px 10px;font-weight:700">ARE</span></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6">✅ <b>Are there any tomatoes?</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;color:#6B7280;font-style:italic">— Есть помидоры?</td></tr></table></div></div>$h$::text)) where id='ec0761bd-b0c7-4bbc-ae69-d1bf4f8002f7';
update classroom_blocks set payload = jsonb_set(payload,'{html}',to_jsonb($h$<div style="max-width:680px;border:1px solid #E6E0D8;border-radius:14px;overflow:hidden;font-size:15px;line-height:1.35"><div style="background:#C97A28;color:#fff;padding:7px 12px;font-weight:700">❓ Грамматика 2: Whose...? / It's... / They're...</div><div style="padding:10px 12px;background:#fff"><div style="padding:10px 12px;border:1px solid #E6D3BC;border-radius:10px;background:#FFF8EF;margin-bottom:10px"><p style="margin:0 0 4px">Whose = "Чей / Чья / Чьё / Чьи?"</p><p style="margin:0">Чтобы ответить — скажи It's (одна вещь) или They're (много вещей), потом имя + 's</p></div><div style="border:1px solid #E6D3BC;border-radius:10px;background:#FFFBEF;padding:10px 12px;margin-bottom:8px"><p style="margin:0 0 4px">❓ <b style="color:#E8732A">Whose hat IS this?</b></p><p style="margin:0 0 4px">✅ <b style="color:#2E9E6B">It's Penny's hat.</b></p><p style="margin:0;color:#6B7280;font-style:italic">ℹ️ одна вещь → IS / It's</p></div><div style="border:1px solid #E6D3BC;border-radius:10px;background:#FFFBEF;padding:10px 12px;margin-bottom:8px"><p style="margin:0 0 4px">❓ <b style="color:#E8732A">Whose shoes ARE these?</b></p><p style="margin:0 0 4px">✅ <b style="color:#2E9E6B">They're Penny's shoes.</b></p><p style="margin:0;color:#6B7280;font-style:italic">ℹ️ много вещей → ARE / They're</p></div><p style="margin:12px 0 0;padding:10px 12px;background:#FFFBEF;border-left:4px solid #D79B2A;border-radius:8px">⚠️ Апостроф 's = «принадлежит кому-то»: Penny's hat = шляпа Пенни · Flash's room = комната Флэш</p><table style="width:100%;border-collapse:collapse"><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6">✅ <b>Whose bag is this? — It's my bag.</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;color:#6B7280">— Чья это сумка? — Это моя сумка.</td></tr><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6">✅ <b>Whose books are these? — They're Tom's books.</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;color:#6B7280">— Чьи это книги? — Это книги Тома.</td></tr><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6">✅ <b>Whose pen is this? — It's the teacher's pen.</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;color:#6B7280">— Чья это ручка? — Это ручка учителя.</td></tr><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6">✅ <b>Whose chairs are those? — They're May's chairs.</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;color:#6B7280">— Чьи те стулья? — Это стулья Мэй.</td></tr><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6">✅ <b>Whose wardrobe is that? — It's Flash's wardrobe.</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;color:#6B7280">— Чей тот шкаф? — Это шкаф Флэша.</td></tr></table></div></div>$h$::text)) where id='28696398-5e01-492f-9145-a09d548772e1';
update classroom_blocks set payload = jsonb_set(payload,'{html}',to_jsonb($h$<div style="max-width:680px;border:1px solid #E6E0D8;border-radius:14px;overflow:hidden;font-size:15px;line-height:1.35"><div style="background:#C07A2E;color:#fff;padding:7px 12px;font-weight:700">🟥 GRAMMAR 1 — Am / Is / Are + Adjective</div><div style="padding:10px 12px;background:#fff"><p style="margin:0 0 10px;padding:10px 12px;background:#FFF8EF;border:1px solid #E6D3BC;border-radius:10px;color:#B4530F;font-weight:700">🟥 GRAMMAR 1 — Am / Is / Are + Adjective</p><p style="margin:0 0 10px;text-align:center;font-size:20px;font-weight:700;color:#C07A2E">Описываем чувства</p><div style="padding:10px 12px;border:1px solid #E6D3BC;border-radius:10px;margin-bottom:10px"><p style="margin:0 0 4px">Используем <b style="color:#E8732A">AM / IS / ARE</b> с прилагательным, чтобы сказать, как кто-то себя чувствует.</p><p style="margin:0"><b style="color:#E8732A">AM</b> → I &nbsp; <b style="color:#E8732A">IS</b> → He / She &nbsp; <b style="color:#E8732A">ARE</b> → We / You / They</p></div><p style="margin:0 0 12px;padding:10px 12px;background:#B8860B;color:#fff;border-radius:10px;text-align:center">⚠️ I'm happy. &nbsp; He's angry. &nbsp; Are you scared? — Yes, I am. / No, I'm not.</p><table style="width:100%;border-collapse:collapse"><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6">✅ <b>I'm happy! 😄</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;color:#6B7280">— Я счастлив(а)!</td></tr><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6">✅ <b>Are you tired? 😴</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;color:#6B7280">— Ты устал(а)?</td></tr><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6">✅ <b>She's angry. 😠</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;color:#6B7280">— Она злится.</td></tr><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6">✅ <b>She's scared. 😨</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;color:#6B7280">— Она напугана.</td></tr><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6">✅ <b>He's sad. 🥺</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;color:#6B7280">— Он грустит.</td></tr><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6">✅ <b>No, I'm not. 😊</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;color:#6B7280">— Нет, не устал(а).</td></tr><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6">✅ <b>I'm excited! 🤩</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;color:#6B7280">— Я в восторге!</td></tr></table></div></div>$h$::text)) where id='dc93d5b1-2171-4e11-843f-d0e01a37b73c';
update classroom_blocks set payload = jsonb_set(payload,'{html}',to_jsonb($h$<div style="max-width:680px;border:1px solid #E6E0D8;border-radius:14px;overflow:hidden;font-size:15px;line-height:1.35"><div style="background:#1B6A39;color:#fff;padding:7px 12px;font-weight:700">Where Does Transport Go?</div><div style="padding:10px 12px;background:#fff"><table style="width:100%;border-collapse:separate;border-spacing:6px"><tr><td style="padding:4px;vertical-align:top"><div><div style="background:#1A5FBF;color:#fff;border-radius:10px;padding:4px 8px;text-align:center;font-weight:700">✈️ IN THE AIR<div style="font-weight:400;font-size:14px">в воздухе</div></div><div style="background:#EAF3FC;border-radius:8px;padding:6px 8px;margin:6px 0;text-align:center;color:#1F7A4A">A ___ goes in the air.</div><div style="border:1px solid #D8E6DC;border-radius:8px;padding:6px 8px;margin-bottom:6px">🚁 <b style="color:#1F7A4A">helicopter</b><div style="color:#6B7280;font-size:14px">вертолёт</div></div><div style="border:1px solid #D8E6DC;border-radius:8px;padding:6px 8px;margin-bottom:6px">✈️ <b style="color:#1F7A4A">plane</b><div style="color:#6B7280;font-size:14px">самолёт</div></div></div></td><td style="padding:4px;vertical-align:top"><div><div style="background:#1F8A6B;color:#fff;border-radius:10px;padding:4px 8px;text-align:center;font-weight:700">⛵ ON WATER<div style="font-weight:400;font-size:14px">по воде</div></div><div style="background:#EAF7F2;border-radius:8px;padding:6px 8px;margin:6px 0;text-align:center;color:#1F7A4A">A ___ goes on water.</div><div style="border:1px solid #D8E6DC;border-radius:8px;padding:6px 8px;margin-bottom:6px">🚢 <b style="color:#1F7A4A">ship</b><div style="color:#6B7280;font-size:14px">корабль</div></div><div style="border:1px solid #D8E6DC;border-radius:8px;padding:6px 8px;margin-bottom:6px">⛵ <b style="color:#1F7A4A">boat</b><div style="color:#6B7280;font-size:14px">лодка</div></div></div></td><td style="padding:4px;vertical-align:top"><div><div style="background:#1B6A39;color:#fff;border-radius:10px;padding:4px 8px;text-align:center;font-weight:700">🚗 ON LAND<div style="font-weight:400;font-size:14px">по суше</div></div><div style="background:#EDF9F1;border-radius:8px;padding:6px 8px;margin:6px 0;text-align:center;color:#1F7A4A">A ___ goes on land.</div><div style="border:1px solid #D8E6DC;border-radius:8px;padding:6px 8px;margin-bottom:6px">🚌 <b style="color:#1F7A4A">bus</b><div style="color:#6B7280;font-size:14px">автобус</div></div><div style="border:1px solid #D8E6DC;border-radius:8px;padding:6px 8px;margin-bottom:6px">🚕 <b style="color:#1F7A4A">taxi</b><div style="color:#6B7280;font-size:14px">такси</div></div><div style="border:1px solid #D8E6DC;border-radius:8px;padding:6px 8px;margin-bottom:6px">🚛 <b style="color:#1F7A4A">lorry</b><div style="color:#6B7280;font-size:14px">грузовик</div></div><div style="border:1px solid #D8E6DC;border-radius:8px;padding:6px 8px;margin-bottom:6px">🛵 <b style="color:#1F7A4A">scooter</b><div style="color:#6B7280;font-size:14px">скутер</div></div><div style="border:1px solid #D8E6DC;border-radius:8px;padding:6px 8px;margin-bottom:6px">🏍️ <b style="color:#1F7A4A">motorbike</b><div style="color:#6B7280;font-size:14px">мотоцикл</div></div><div style="border:1px solid #D8E6DC;border-radius:8px;padding:6px 8px;margin-bottom:6px">🛹 <b style="color:#1F7A4A">skateboard</b><div style="color:#6B7280;font-size:14px">скейтборд</div></div></div></td></tr></table></div></div>$h$::text)) where id='785af1aa-1a50-4c7b-a022-fe1257b3ef48';
update classroom_blocks set payload = jsonb_set(payload,'{html}',to_jsonb($h$<div style="max-width:680px;border:1px solid #E6E0D8;border-radius:14px;overflow:hidden;font-size:15px;line-height:1.35"><div style="background:#5C2C71;color:#fff;padding:7px 12px;font-weight:700">💬 The Football Club</div><div style="padding:10px 12px;background:#fff"><table style="width:100%;border-collapse:collapse"><tr><td style="padding:10px 12px;border-bottom:1px solid #F0ECE6;border-left:5px solid #7B3AEB;background:#F6EEFD"><span style="font-size:20px">🙋</span> <b style="font-size:18px">Can I join?</b><div style="color:#7B3AEB;font-style:italic;font-size:14px">Можно мне присоединиться?</div></td></tr><tr><td style="padding:10px 12px;border-bottom:1px solid #F0ECE6;border-left:5px solid #D94A77;background:#FDEFF4"><span style="font-size:20px">😕</span> <b style="font-size:18px">The team's full.</b><div style="color:#B03A5B;font-style:italic;font-size:14px">В команде нет мест.</div></td></tr><tr><td style="padding:10px 12px;border-bottom:1px solid #F0ECE6;border-left:5px solid #4C3AB8;background:#F0EEFD"><span style="font-size:20px">💡</span> <b style="font-size:18px">Let's start a team!</b><div style="color:#4C3AB8;font-style:italic;font-size:14px">Давай создадим свою команду!</div></td></tr><tr><td style="padding:10px 12px;border-bottom:1px solid #F0ECE6;border-left:5px solid #7B3AEB;background:#F6EEFD"><span style="font-size:20px">🤝</span> <b style="font-size:18px">Join our team!</b><div style="color:#7B3AEB;font-style:italic;font-size:14px">Присоединяйся к нашей команде!</div></td></tr><tr><td style="padding:10px 12px;border-bottom:1px solid #F0ECE6;border-left:5px solid #D94A77;background:#FDEFF4"><span style="font-size:20px">😄</span> <b style="font-size:18px">It's going to be easy.</b><div style="color:#B03A5B;font-style:italic;font-size:14px">Это будет легко.</div></td></tr><tr><td style="padding:10px 12px;border-bottom:1px solid #F0ECE6;border-left:5px solid #4C3AB8;background:#F0EEFD"><span style="font-size:20px">🏆</span> <b style="font-size:18px">We've got our team!</b><div style="color:#4C3AB8;font-style:italic;font-size:14px">У нас есть наша команда!</div></td></tr></table></div></div>$h$::text)) where id='4f25de39-cd29-47de-8cb3-a39124b788fc';
update classroom_blocks set payload = jsonb_set(payload,'{html}',to_jsonb($h$<div style="max-width:680px;border:1px solid #E6E0D8;border-radius:14px;overflow:hidden;font-size:15px;line-height:1.35"><div style="background:#5C2C71;color:#fff;padding:7px 12px;font-weight:700">💬 I'd like to...</div><div style="padding:10px 12px;background:#fff"><p style="margin:0 0 12px;padding:10px 12px;background:#FAF5FE;border:1px solid #E0CFF2;border-radius:10px">"I'd like to" = "I would like to" — вежливый способ сказать "я хотел бы / я хочу". Это мягче, чем просто "I want"!</p><table style="width:100%;border-collapse:collapse"><tr><td style="padding:10px 12px;border-bottom:1px solid #F0ECE6;background:#F6EEFD"><span style="font-size:20px">🏕️</span> <b style="color:#5C2C71;font-size:17px">"I'd like to go camping!"</b><div style="color:#6B7280;font-size:14px">Я бы хотел(а) пойти в поход с палаткой!</div></td></tr><tr><td style="padding:10px 12px;border-bottom:1px solid #F0ECE6;background:#FDEFEA"><span style="font-size:20px">❓</span> <b style="color:#C0392B;font-size:17px">"What would you like to do?"</b><div style="color:#6B7280;font-size:14px">Что бы ты хотел(а) сделать?</div></td></tr><tr><td style="padding:10px 12px;border-bottom:1px solid #F0ECE6;background:#F6EEFD"><span style="font-size:20px">🌳</span> <b style="color:#5C2C71;font-size:17px">"I'd like to build a tree house!"</b><div style="color:#6B7280;font-size:14px">Я бы хотел(а) построить домик на дереве!</div></td></tr><tr><td style="padding:10px 12px;border-bottom:1px solid #F0ECE6;background:#FDEFEA"><span style="font-size:20px">🏊</span> <b style="color:#C0392B;font-size:17px">"I'd like to learn to swim."</b><div style="color:#6B7280;font-size:14px">Я бы хотел(а) научиться плавать.</div></td></tr><tr><td style="padding:10px 12px;border-bottom:1px solid #F0ECE6;background:#F6EEFD"><span style="font-size:20px">📖</span> <b style="color:#5C2C71;font-size:17px">"I'd like to read a comic on holiday."</b><div style="color:#6B7280;font-size:14px">Я бы хотел(а) читать комиксы на каникулах.</div></td></tr></table></div></div>$h$::text)) where id='41879916-cdf4-44a4-9119-cdfe2faf6f96';
update classroom_blocks set payload = jsonb_set(payload,'{html}',to_jsonb($h$<div style="max-width:680px;border:1px solid #E6E0D8;border-radius:14px;overflow:hidden;font-size:15px;line-height:1.35"><div style="background:#7B3AEB;color:#fff;padding:7px 12px;font-weight:700">💬 Unit 1 · Introductions</div><div style="padding:10px 12px;background:#fff"><table style="width:100%;border-collapse:collapse"><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;border-left:4px solid #7B3AEB"><b>💬 Hello! / Hi!</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;color:#6B7280">Привет!</td></tr><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;border-left:4px solid #7B3AEB"><b>💬 What's your name?</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;color:#6B7280">Как тебя зовут?</td></tr><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;border-left:4px solid #7B3AEB"><b>💬 Nice to meet you too!</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;color:#6B7280">Мне тоже!</td></tr><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;border-left:4px solid #7B3AEB"><b>💬 Where are you from?</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;color:#6B7280">Откуда ты?</td></tr><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;border-left:4px solid #D64C8D"><b>💬 I'm ___ / My name's ___.</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;color:#6B7280">Меня зовут ___.</td></tr><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;border-left:4px solid #D64C8D"><b>💬 Nice to meet you!</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;color:#6B7280">Приятно познакомиться!</td></tr><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;border-left:4px solid #D64C8D"><b>💬 This is ___. He's/She's my friend.</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;color:#6B7280">Это ___. Он/Она мой друг/моя подруга.</td>