update classroom_blocks set payload = jsonb_set(payload,'{html}',to_jsonb($h$<div style="max-width:680px;border:1px solid #E6E0D8;border-radius:14px;overflow:hidden;font-size:15px;line-height:1.35"><div style="background:#6E28DD;color:#fff;padding:7px 12px;font-weight:700">Как познакомиться — Personal Information</div><div style="padding:10px 12px;background:#fff"><table style="width:100%;border-collapse:collapse"><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6"><b>💬 What's your name?</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;color:#6B7280">Как тебя зовут?</td></tr><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6"><b>💬 How old are you?</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;color:#6B7280">Сколько тебе лет?</td></tr><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6"><b>💬 Where are you from?</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;color:#6B7280">Откуда ты?</td></tr><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6"><b>💬 What's your favourite music / sport / film?</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;color:#6B7280">Какой твой любимый жанр / спорт / фильм?</td></tr><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6"><b>💬 Who's your favourite singer / actor?</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;color:#6B7280">Кто твой любимый певец / актёр?</td></tr></table><div style="margin:10px 0;padding:10px 12px;background:#F5F1FE;border:1px solid #D8C9F7;border-radius:10px"><p style="margin:0 0 8px;font-weight:700;color:#6E28DD">Пример диалога:</p><p style="margin:6px 0"><b style="color:#6E28DD">A:</b> What's your name? &nbsp;→&nbsp; <b style="color:#6E28DD">B:</b> My name's Lucas. That's L-U-C-A-S.</p><p style="margin:6px 0"><b style="color:#6E28DD">A:</b> How old are you? &nbsp;→&nbsp; <b style="color:#6E28DD">B:</b> I'm eleven years old.</p><p style="margin:6px 0"><b style="color:#6E28DD">A:</b> Where are you from? &nbsp;→&nbsp; <b style="color:#6E28DD">B:</b> I'm from Madrid, Spain.</p><p style="margin:6px 0"><b style="color:#6E28DD">A:</b> What's your favourite music? &nbsp;→&nbsp; <b style="color:#6E28DD">B:</b> Rock, I think!</p></div></div></div>$h$::text)) where id='b0144221-ff03-4ef2-967f-25df5aab4cf6';
update classroom_blocks set payload = jsonb_set(payload,'{html}',to_jsonb($h$<div style="max-width:680px;border:1px solid #E6E0D8;border-radius:14px;overflow:hidden;font-size:15px;line-height:1.35"><div style="background:#D64C8D;color:#fff;padding:7px 12px;font-weight:700">🚪 Принимаем гостя</div><div style="padding:10px 12px;background:#fff"><table style="width:100%;border-collapse:collapse"><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6"><b>💬 Hello! Please, come in.</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;color:#6B7280">Привет! Пожалуйста, входи!</td></tr><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6"><b>💬 Thank you.</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;color:#6B7280">Спасибо.</td></tr><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6"><b>💬 Would you like a sandwich?</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;color:#6B7280">Хочешь бутерброд?</td></tr><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6"><b>💬 Yes, please.</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;color:#6B7280">Да, пожалуйста.</td></tr><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6"><b>💬 No, thank you.</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;color:#6B7280">Нет, спасибо.</td></tr></table><hr style="border:0;border-top:1px solid #F0ECE6;margin:12px 0"><table style="width:100%;border-collapse:collapse"><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6"><b>💬 Where's the bathroom, please?</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;color:#6B7280">Где ванная комната, пожалуйста?</td></tr><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6"><b>💬 It's upstairs.</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;color:#6B7280">Это наверху.</td></tr><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6"><b>💬 It's downstairs.</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;color:#6B7280">Это внизу.</td></tr><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6"><b>💬 It's next to the living room.</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;color:#6B7280">Это рядом с гостиной.</td></tr><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6"><b>💬 Let me show you.</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;color:#6B7280">Позволь, я покажу.</td></tr></table></div></div>$h$::text)) where id='2456c81e-c053-448a-9531-fb8018e1df45';
update classroom_blocks set payload = jsonb_set(payload,'{html}',to_jsonb($h$<div style="max-width:680px;border:1px solid #E6E0D8;border-radius:14px;overflow:hidden;font-size:15px;line-height:1.35"><div style="background:#E8732A;color:#fff;padding:7px 12px;font-weight:700">have got — вопросы и краткие ответы</div><div style="padding:10px 12px;background:#fff"><p style="margin:6px 0;color:#6B7280">Чтобы задать вопрос — поставь Have / Has в начало.</p><div style="margin:10px 0;padding:10px 12px;background:#FFF8EF;border:1px solid #E8C9A3;border-radius:10px"><p style="margin:6px 0">❓ <b style="color:#E8732A">Have</b> I / you / we / they got …? &nbsp;&nbsp; <b style="color:#E8732A">Has</b> he / she / it got …?</p><p style="margin:6px 0">✅ Yes, I/you/we/they <b style="color:#2E9E6B">have</b>. &nbsp; Yes, he/she/it <b style="color:#2E9E6B">has</b>. &nbsp;&nbsp; ❌ No, I/you/we/they <b style="color:#D94A77">haven't</b>. &nbsp; No, he/she/it <b style="color:#D94A77">hasn't</b>.</p></div><table style="width:100%;border-collapse:collapse"><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6"><b>❓ Has she got blue eyes?</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;color:#6B7280">✅ Yes, she has.</td></tr><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6"><b>❓ Have you got curly hair?</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;color:#6B7280">✅ No, I haven't.</td></tr><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6"><b>❓ Have they got super eyes?</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;color:#6B7280">✅ Yes, they have.</td></tr><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6"><b>❓ Has he got spiky hair?</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;color:#6B7280">✅ Yes, he has.</td></tr><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6"><b>❓ Has it got battery power?</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;color:#6B7280">✅ No, it hasn't.</td></tr><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6"><b>❓ Have we got time?</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;color:#6B7280">✅ Yes, we have.</td></tr></table><p style="margin:12px 0 0;padding:10px 12px;background:#FFFBEB;border-left:4px solid #E8A33D;border-radius:8px">⚠️ В кратком ответе всегда полная форма: Yes, she HAS. / No, they HAVEN'T.</p><div style="margin:10px 0;padding:10px 12px;background:#FFF8EF;border:1px solid #E8C9A3;border-radius:10px"><p style="margin:0 0 8px;font-weight:700;color:#B4530F">🔑 Притяжательные местоимения:</p><p style="margin:6px 0">it → <b style="color:#E8732A">its</b> <span style="color:#6B7280">(его / её)</span> &nbsp;&nbsp; we → <b style="color:#E8732A">our</b> <span style="color:#6B7280">(наш / наша)</span> &nbsp;&nbsp; you → <b style="color:#E8732A">your</b> <span style="color:#6B7280">(ваш / ваша)</span> &nbsp;&nbsp; they → <b style="color:#E8732A">their</b> <span style="color:#6B7280">(их)</span></p></div></div></div>$h$::text)) where id='4aa29be2-6599-41e8-b7a9-7f01edb4ee7f';
update classroom_blocks set payload = jsonb_set(payload,'{html}',to_jsonb($h$<div style="max-width:680px;border:1px solid #E6E0D8;border-radius:14px;overflow:hidden;font-size:15px;line-height:1.35"><div style="background:#E17B20;color:#fff;padding:7px 12px;font-weight:700">Unit 5 can / can't</div><div style="padding:10px 12px;background:#fff"><p style="margin:6px 0;color:#6B7280">CAN = умею / могу. &nbsp; CAN'T = не умею / не могу. &nbsp; После CAN — всегда инфинитив (начальная форма глагола).</p><div style="margin:10px 0;padding:10px 12px;background:#FFF8EF;border:1px solid #E8C9A3;border-radius:10px"><p style="margin:6px 0">✅ <b>Subject + CAN + infinitive</b></p><p style="margin:6px 0">❌ <b>Subject + CAN'T + infinitive</b></p></div><p style="margin:12px 0 0;padding:10px 12px;background:#FFFBEB;border-left:4px solid #E8A33D;border-radius:8px">⚠️ CAN не изменяется по лицам! I can · He can · She can · They can (никакого -s!)</p><table style="width:100%;border-collapse:collapse"><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6"><b>✅ I can swim.</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;color:#6B7280">Я умею плавать.</td></tr><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6"><b>✅ She can play the guitar.</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;color:#6B7280">Она умеет играть на гитаре.</td></tr><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6"><b>✅ He can fix things.</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;color:#6B7280">Он умеет чинить вещи.</td></tr><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6"><b>❌ I can't fly.</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;color:#6B7280">Я не умею летать.</td></tr><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6"><b>❌ We can't sing very well.</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;color:#6B7280">Мы не очень хорошо умеем петь.</td></tr></table></div></div>$h$::text)) where id='9f512ea9-8962-4afc-9950-a7dcdbe76e63';
update classroom_blocks set payload = jsonb_set(payload,'{html}',to_jsonb($h$<div style="max-width:680px;border:1px solid #E6E0D8;border-radius:14px;overflow:hidden;font-size:15px;line-height:1.35"><div style="background:#C65F02;color:#fff;padding:7px 12px;font-weight:700">Unit 6 Present Simple (Affirmative)</div><div style="padding:10px 12px;background:#fff"><p style="margin:6px 0;color:#6B7280">Используем Present Simple для регулярных действий. Для I/You/We/They — глагол не меняется. Для He/She/It — добавляем -s/-es/-ies.</p><div style="margin:10px 0;padding:10px 12px;background:#FFF8EF;border:1px solid #E8C9A3;border-radius:10px"><p style="margin:6px 0"><b>I / You / We / They &nbsp;+&nbsp; VERB</b></p><p style="margin:6px 0"><i style="color:#C65F02">I listen. We walk. They watch.</i></p></div><div style="margin:10px 0;padding:10px 12px;background:#FFF8EF;border:1px solid #E8C9A3;border-radius:10px"><p style="margin:6px 0"><b>He / She / It &nbsp;+&nbsp; VERB + s / es / ies</b></p><p style="margin:6px 0"><i style="color:#C65F02">She listens. He goes. She studies.</i></p></div><p style="margin:12px 0 0;padding:10px 12px;background:#FFFBEB;border-left:4px solid #E8A33D;border-radius:8px">⚠️ Важно! watch → watches · go → goes · study → studies</p><table style="width:100%;border-collapse:collapse"><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6"><b>✅ I get up early.</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;color:#6B7280">Я встаю рано.</td></tr><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6"><b>✅ She makes pancakes.</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;color:#6B7280">Она делает блинчики.</td></tr><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6"><b>✅ He listens to classical music.</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;color:#6B7280">Он слушает классическую музыку.</td></tr><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6"><b>✅ We walk to school.</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;color:#6B7280">Мы идём в школу пешком.</td></tr><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6"><b>✅ They never tidy their room.</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;color:#6B7280">Они никогда не убирают комнату.</td></tr></table></div></div>$h$::text)) where id='b33e1422-acde-4692-9d33-3f256bb69518';
update classroom_blocks set payload = jsonb_set(payload,'{html}',to_jsonb($h$<div style="max-width:680px;border:1px solid #E6E0D8;border-radius:14px;overflow:hidden;font-size:15px;line-height:1.35"><div style="background:#C52F80;color:#fff;padding:7px 12px;font-weight:700">💬 погода (Weather)</div><div style="padding:10px 12px;background:#fff"><table style="width:100%;border-collapse:collapse"><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6"><b>💬 What's the weather like?</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;color:#6B7280">Какая погода? / Как погода?</td></tr><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6"><b>💬 It's sunny 🌞 / cloudy ⛅ / rainy 🌧️</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;color:#6B7280">Солнечно / Облачно / Дождливо</td></tr><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6"><b>💬 It's snowy ❄️ / windy 🌬️</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;color:#6B7280">Снежно / Ветрено</td></tr><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6"><b>💬 It's hot 🌡️ / cold 🥶 / warm 🌤️</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;color:#6B7280">Жарко / Холодно / Тепло</td></tr><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6"><b>💬 That's a pity!</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;color:#6B7280">Жаль! (Как жаль!)</td></tr><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6"><b>💬 I hope it's sunny tomorrow.</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;color:#6B7280">Надеюсь, завтра будет солнечно.</td></tr></table></div></div>$h$::text)) where id='5fa58e45-f4f8-4c2d-8031-5f1458c3d376';
update classroom_blocks set payload = jsonb_set(payload,'{html}',to_jsonb($h$<div style="max-width:680px;border:1px solid #E6E0D8;border-radius:14px;overflow:hidden;font-size:15px;line-height:1.35"><div style="background:#F39C11;color:#fff;padding:7px 12px;font-weight:700">📌 he / she • his / her</div><div style="padding:10px 12px;background:#fff"><div style="margin:10px 0;padding:10px 12px;background:#FFFBEB;border:1px solid #F3E3B8;border-radius:10px">📖 <b style="color:#2F6FB8">he / his</b> — используем для <b style="color:#2F6FB8">мальчиков / мужчин</b>. &nbsp; <b style="color:#D94A77">she / her</b> — используем для <b style="color:#D94A77">девочек / женщин</b>.</div><p style="margin:12px 0 0;padding:10px 12px;background:#FFFBEB;border-left:4px solid #E8A33D;border-radius:8px">⚠️ <b>Запомни:</b> <b style="color:#2F6FB8">he</b> = он · <b style="color:#D94A77">she</b> = она · <b style="color:#2F6FB8">his</b> = его · <b style="color:#D94A77">her</b> = её</p><div style="margin:8px 0;padding:10px 12px;background:#EAF3FD;border:1px solid #9CC4EC;border-radius:10px"><p style="margin:0 0 6px;font-weight:700;color:#2F6FB8">👦 HE / HIS (мальчик)</p><p style="margin:6px 0">What's <b style="color:#2F6FB8">his</b> name? — <b style="color:#2F6FB8">His</b> name's Ben.</p><p style="margin:6px 0">How old is <b style="color:#2F6FB8">he</b>? — <b style="color:#2F6FB8">He</b>'s ten.</p><p style="margin:6px 0">What's <b style="color:#2F6FB8">his</b> favourite toy? — <b style="color:#2F6FB8">His</b> favourite toy's <b style="color:#2F6FB8">his</b> train. 🚂</p></div><div style="margin:8px 0;padding:7px 10px;background:#FDF0F4;border:1px solid #EFB3C7;border-radius:10px"><p style="margin:0 0 6px;font-weight:700;color:#D94A77">👧 SHE / HER (девочка)</p><p style="margin:6px 0">What's <b style="color:#D94A77">her</b> name? — <b style="color:#D94A77">Her</b> name's Kate.</p><p style="margin:6px 0">How old is <b style="color:#D94A77">she</b>? — <b style="color:#D94A77">She</b>'s eight.</p><p style="margin:6px 0">What's <b style="color:#D94A77">her</b> favourite toy? — <b style="color:#D94A77">Her</b> favourite toy's <b style="color:#D94A77">her</b> plane. ✈️</p></div><p style="margin:0 0 8px;font-weight:700;color:#B4530F">📝 Ещё примеры:</p><table style="width:100%;border-collapse:collapse"><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6"><b>👦 This is Tom. He's seven. His favourite toy's his bike.</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;color:#6B7280">Это Том. Ему семь. Его любимая игрушка — велосипед.</td></tr><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6"><b>👧 This is Mia. She's six. Her favourite toy's her doll.</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;color:#6B7280">Это Мия. Ей шесть. Её любимая игрушка — кукла.</td></tr><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6"><b>👦 What's his name? — His name's Alex.</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;color:#6B7280">Как его зовут? — Его зовут Алекс.</td></tr><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6"><b>👧 What's her name? — Her name's Sophie.</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;color:#6B7280">Как её зовут? — Её зовут Софи.</td></tr></table></div></div>$h$::text)) where id='4fa7b06b-5b24-4767-aed1-fb4ead3eba62';
update classroom_blocks set payload = jsonb_set(payload,'{html}',to_jsonb($h$<div style="max-width:680px;border:1px solid #E6E0D8;border-radius:14px;overflow:hidden;font-size:15px;line-height:1.35"><div style="background:#F39C11;color:#fff;padding:7px 12px;font-weight:700">📌 Grammar — in / on / under (Предлоги места)</div><div style="padding:10px 12px;background:#fff"><div style="margin:10px 0;padding:10px 12px;background:#FFFBEB;border:1px solid #F3E3B8;border-radius:10px">📖 Чтобы сказать, <b style="color:#B4530F">ГДЕ</b> находится предмет или животное, используем предлоги: <b style="color:#2F6FB8">in</b> (в), <b style="color:#2E9E6B">on</b> (на), <b style="color:#D94A77">under</b> (под).</div><div style="margin:8px 0;padding:10px 12px;background:#EAF3FD;border:1px solid #9CC4EC;border-radius:10px"><p style="margin:0 0 6px;font-weight:700;color:#2F6FB8">IN — в</p><p style="margin:6px 0"><b>The frog is IN the bag.</b></p><p style="margin:6px 0;color:#6B7280">Лягушка В рюкзаке.</p></div><div style="margin:8px 0;padding:10px 12px;background:#EAF8F0;border:1px solid #9FD9BE;border-radius:10px"><p style="margin:0 0 6px;font-weight:700;color:#2E9E6B">ON — на</p><p style="margin:6px 0"><b>The cat is ON the book.</b></p><p style="margin:6px 0;color:#6B7280">Кошка НА книге.</p></div><div style="margin:8px 0;padding:7px 10px;background:#FDF0F4;border:1px solid #EFB3C7;border-radius:10px"><p style="margin:0 0 6px;font-weight:700;color:#D94A77">UNDER — под</p><p style="margin:6px 0"><b>The dog is UNDER the chair.</b></p><p style="margin:6px 0;color:#6B7280">Собака ПОД стулом.</p></div><p style="margin:12px 0 0;padding:10px 12px;background:#FFFBEB;border-left:4px solid #E8A33D;border-radius:8px">✅ <b>Формула:</b> The [pet] is <b style="color:#2F6FB8">in</b> / <b style="color:#2E9E6B">on</b> / <b style="color:#D94A77">under</b> the [place].</p><p style="margin:0 0 8px;font-weight:700;color:#B4530F">📝 More Examples / Ещё примеры</p><table style="width:100%;border-collapse:collapse"><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6"><b>✅ The spider is in the bag.</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;color:#6B7280">Паук в рюкзаке.</td></tr><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6"><b>✅ The rat is on the desk.</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;color:#6B7280">Крыса на парте.</td></tr><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6"><b>✅ The duck is under the hat.</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;color:#6B7280">Утка под шляпой.</td></tr><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6"><b>✅ The lizard is on the chair.</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;color:#6B7280">Ящерица на стуле.</td></tr><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6"><b>✅ The elephant is under the bed!</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;color:#6B7280">Слон под кроватью!</td></tr></table></div></div>$h$::text)) where id='56dbd3b1-582a-4f29-a907-0965e33c992c';
update classroom_blocks set payload = jsonb_set(payload,'{html}',to_jsonb($h$<div style="max-width:680px;border:1px solid #E6E0D8;border-radius:14px;overflow:hidden;font-size:15px;line-height:1.35"><div style="background:#E67E22;color:#fff;padding:7px 12px;font-weight:700">📖 Phonics — -LE & S /z/</div><div style="padding:10px 12px;background:#fff"><div style="margin:8px 0;padding:10px 12px;background:#FFF8EF;border:1px solid #E8C9A3;border-radius:10px"><p style="margin:0 0 6px;font-weight:700;color:#2F6FB8">-LE &nbsp; /əl/</p><p style="margin:6px 0">🍎 &nbsp; <b>apple</b> &nbsp; <span style="color:#6B7280">«яблоко»</span></p></div><div style="margin:8px 0;padding:10px 12px;background:#FFF8EF;border:1px solid #E8C9A3;border-radius:10px"><p style="margin:0 0 6px;font-weight:700;color:#2F6FB8">S &nbsp; /z/</p><p style="margin:6px 0">🦵 &nbsp; <b>legs</b> &nbsp; <span style="color:#6B7280">«ноги»</span></p></div></div></div>$h$::text)) where id='d832eb48-20ab-4b37-b06a-368983677856';
update classroom_blocks set payload = jsonb_set(payload,'{html}',to_jsonb($h$<div style="max-width:680px;border:1px solid #E6E0D8;border-radius:14px;overflow:hidden;font-size:15px;line-height:1.35"><div style="background:#F39C11;color:#fff;padding:7px 12px;font-weight:700">📝 Grammar — Do you… at the weekend?</div><div style="padding:10px 12px;background:#fff"><div style="margin:10px 0;padding:10px 12px;background:#FFFBEB;border:1px solid #F3E3B8;border-radius:10px">📖 Чтобы спросить, <b style="color:#B4530F">что кто-то делает на выходных</b>, говори: <b style="color:#2F6FB8">Do you + [что делаешь] + at the weekend?</b><br>Отвечай: <b style="color:#2E9E6B">Yes, I do.</b> / <b style="color:#D94A77">No, I don't.</b></div><div style="margin:8px 0;padding:10px 12px;background:#EAF3FD;border:1px solid #9CC4EC;border-radius:10px"><p style="margin:0 0 6px;font-weight:700;color:#D94A77">❓ ВОПРОС</p><p style="margin:6px 0"><b style="color:#2F6FB8">Do you + [activity] at the weekend?</b></p><p style="margin:6px 0;color:#6B7280">= Ты делаешь… на выходных?</p><p style="margin:6px 0">⚽❓ <b>Do you play football at the weekend?</b></p><p style="margin:6px 0;color:#6B7280">Ты играешь в футбол на выходных?</p></div><div style="margin:8px 0;padding:10px 12px;background:#EAF8F0;border:1px solid #9FD9BE;border-radius:10px"><p style="margin:0 0 6px;font-weight:700;color:#2E9E6B">✅ ДА</p><p style="margin:6px 0"><b style="color:#2E9E6B">Yes, I do.</b></p><p style="margin:6px 0;color:#6B7280">= Да!</p><p style="margin:6px 0">⚽✅ <b>Yes, I do!</b></p><p style="margin:6px 0;color:#6B7280">Да, играю!</p></div><div style="margin:8px 0;padding:7px 10px;background:#FDF0F4;border:1px solid #EFB3C7;border-radius:10px"><p style="margin:0 0 6px;font-weight:700;color:#D94A77">❌ НЕТ</p><p style="margin:6px 0"><b style="color:#D94A77">No, I don't.</b></p><p style="margin:6px 0;color:#6B7280">= Нет!</p><p style="margin:6px 0">⚽❌ <b>No, I don't.</b></p><p style="margin:6px 0;color:#6B7280">Нет, не играю.</p></div><p style="margin:0 0 8px;font-weight:700;color:#B4530F">📝 Examples / Примеры</p><table style="width:100%;border-collapse:collapse"><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6"><b>📺 Do you watch TV at the weekend?</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;color:#6B7280">Ты смотришь ТВ на выходных?</td></tr><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6"><b>🎮 Do you play computer games?</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;color:#6B7280">Ты играешь в компьютерные игры?</td></tr><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6"><b>🚴 Do you ride your bike?</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;color:#6B7280">Ты катаешься на велике?</td></tr><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6"><b>✅ Yes, I do!</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;color:#6B7280">Да!</td></tr><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6"><b>❌ No, I don't.</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;color:#6B7280">Нет.</td></tr><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6"><b>🐴 Do you ride a horse? — No, I don't!</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;color:#6B7280">Ты катаешься на лошади? — Нет!</td></tr></table><p style="margin:12px 0 0;padding:10px 12px;background:#FFFBEB;border-left:4px solid #E8A33D;border-radius:8px">⚠️ <b>at the weekend</b> = на выходных (Sat + Sun)<br><b style="color:#2F6FB8">on Mondays</b> = каждый пн ≠ <b>at the weekend</b></p></div></div>$h$::text)) where id='d1691289-4a6c-4ff5-bb11-4788bffb3a67';
update classroom_blocks set payload = jsonb_set(payload,'{html}',to_jsonb($h$<div style="max-width:680px;border:1px solid #E6E0D8;border-radius:14px;overflow:hidden;font-size:15px;line-height:1.35"><div style="background:#F49F0C;color:#fff;padding:7px 12px;font-weight:700">📝 Grammar 1 — Do you like this / these?</div><div style="padding:10px 12px;background:#fff"><div style="margin:10px 0;padding:10px 12px;background:#FFFBEB;border:1px solid #F3E3B8;border-radius:10px">📖 Чтобы спросить, нравится ли что-то: <b style="color:#2E9E6B">this</b> → один предмет (этот/эта), <b style="color:#2F6FB8">these</b> → несколько (эти).</div><div style="margin:8px 0;padding:10px 12px;background:#EAF8F0;border:1px solid #9FD9BE;border-radius:10px"><p style="margin:0 0 6px;font-weight:700;color:#B4530F">☝️ ОДИН предмет</p><p style="margin:6px 0">Do you like <b style="color:#2E9E6B">this</b> + <i>[предмет]</i>?</p><p style="margin:6px 0"><b>Do you like this hat?</b></p><p style="margin:6px 0;color:#6B7280">Тебе нравится эта шляпа?</p></div><div style="margin:8px 0;padding:10px 12px;background:#EAF3FD;border:1px solid #9CC4EC;border-radius:10px"><p style="margin:0 0 6px;font-weight:700;color:#2F6FB8">👆 НЕСКОЛЬКО</p><p style="margin:6px 0">Do you like <b style="color:#2F6FB8">these</b> + <i>[предметы]</i>?</p><p style="margin:6px 0"><b>Do you like these shoes?</b></p><p style="margin:6px 0;color:#6B7280">Тебе нравятся эти ботинки?</p></div><p style="margin:6px 0">✅ <b style="color:#2E9E6B">Yes, I do.</b> — <span style="color:#6B7280">Да, нравится.</span> &nbsp;&nbsp; ❌ <b style="color:#D94A77">No, I don't.</b> — <span style="color:#6B7280">Нет, не нравится.</span></p><p style="margin:0 0 8px;font-weight:700;color:#B4530F">📝 Примеры:</p><table style="width:100%;border-collapse:collapse"><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6"><b>🟢 Do you like this T-shirt? — No, I don't.</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;color:#6B7280">Тебе нравится эта футболка? — Нет.</td></tr><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6"><b>🔵 Do you like these shoes? — Yes, I do.</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;color:#6B7280">Тебе нравятся эти ботинки? — Да.</td></tr><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6"><b>🟢 Do you like this bag? — Yes, I do.</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;color:#6B7280">Тебе нравится эта сумка? — Да.</td></tr><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6"><b>🔵 Do you like this hat? — No, I don't.</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;color:#6B7280">Тебе нравится эта шляпа? — Нет.</td></tr></table></div></div>$h$::text)) where id='1dee20bf-c01c-4cbc-b332-f68c80c0c0f8';
update classroom_blocks set payload = jsonb_set(payload,'{html}',to_jsonb($h$<div style="max-width:680px;border:1px solid #E6E0D8;border-radius:14px;overflow:hidden;font-size:15px;line-height:1.35"><div style="background:#F49F0C;color:#fff;padding:7px 12px;font-weight:700">📝 Grammar 1 — I can / I can't</div><div style="padding:10px 12px;background:#fff"><div style="margin:10px 0;padding:10px 12px;background:#FFFBEB;border:1px solid #F3E3B8;border-radius:10px">📖 <b style="color:#2E9E6B">can</b> — могу/умею, <b style="color:#D94A77">can't</b> — не могу/не умею.</div><div style="margin:8px 0;padding:10px 12px;background:#EAF8F0;border:1px solid #9FD9BE;border-radius:10px"><p style="margin:0 0 6px;font-weight:700;color:#2E9E6B">✅ УМЕЮ</p><p style="margin:6px 0">I <b style="color:#2E9E6B">can</b> + <i>[действие]</i></p><p style="margin:6px 0"><b>I can swim.</b></p><p style="margin:6px 0;color:#6B7280">Я умею плавать.</p></div><div style="margin:8px 0;padding:7px 10px;background:#FDF0F4;border:1px solid #EFB3C7;border-radius:10px"><p style="margin:0 0 6px;font-weight:700;color:#D94A77">❌ НЕ УМЕЮ</p><p style="margin:6px 0">I <b style="color:#D94A77">can't</b> + <i>[действие]</i></p><p style="margin:6px 0"><b>I can't fly.</b></p><p style="margin:6px 0;color:#6B7280">Я не умею летать.</p></div><p style="margin:0 0 8px;font-weight:700;color:#B4530F">📝 Примеры:</p><table style="width:100%;border-collapse:collapse"><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6"><b>🟢 I can stand on one leg.</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;color:#6B7280">Я могу стоять на одной ноге.</td></tr><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6"><b>🟢 I can skip.</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;color:#6B7280">Я умею прыгать через скакалку.</td></tr><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6"><b>🟢 I can swim.</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;color:#6B7280">Я умею плавать.</td></tr><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6"><b>🟢 I can sing.</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;color:#6B7280">Я умею петь.</td></tr><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6"><b>🟢 I can touch my toes.</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;color:#6B7280">Я могу достать до пальцев ног.</td></tr><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6"><b>🔴 I can't fly.</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;color:#6B7280">Я не умею летать.</td></tr></table><p style="margin:12px 0 0;padding:10px 12px;background:#FFFBEB;border-left:4px solid #E8A33D;border-radius:8px">⚠️ <b>can't</b> = can not. &nbsp; После <b>can / can't</b> глагол без <b style="color:#2F6FB8">to</b>: I can swim ✅ &nbsp; I can to swim ❌</p></div></div>$h$::text)) where id='33f21932-9d4b-4d7d-9ef4-36ca1512271e';
update classroom_blocks set payload = jsonb_set(payload,'{html}',to_jsonb($h$<div style="max-width:680px;border:1px solid #E6E0D8;border-radius:14px;overflow:hidden;font-size:15px;line-height:1.35"><div style="background:#7E5B00;color:#fff;padding:7px 12px;font-weight:700">Grammar: Imperatives (Команды)</div><div style="padding:10px 12px;background:#fff"><p style="margin:0 0 8px;font-weight:700;color:#7E5B00">Как давать команды по-английски</p><p style="margin:6px 0;color:#6B7280">Imperative — это команда: скажи кому-то что-то сделать или не делать. Утвердительная команда = просто глагол. Отрицательная команда = Don't + глагол. Добавь please — и команда станет вежливой!</p><div style="margin:8px 0;padding:10px 12px;background:#EAF8F0;border:1px solid #9FD9BE;border-radius:10px"><p style="margin:0 0 6px;font-weight:700;color:#2E9E6B">✅ Утвердительная</p><p style="margin:6px 0"><b style="color:#2E9E6B">VERB &nbsp;(+ please)</b></p><p style="margin:6px 0;color:#6B7280"><i>e.g. Sit down, please.</i></p></div><div style="margin:8px 0;padding:7px 10px;background:#FDF0F4;border:1px solid #EFB3C7;border-radius:10px"><p style="margin:0 0 6px;font-weight:700;color:#D94A77">🚫 Отрицательная</p><p style="margin:6px 0"><b style="color:#D94A77">DON'T + VERB</b></p><p style="margin:6px 0;color:#6B7280"><i>e.g. Don't sit down!</i></p></div><p style="margin:12px 0 0;padding:10px 12px;background:#FFFBEB;border-left:4px solid #E8A33D;border-radius:8px">⚠️ DON'T = DO + NOT (сокращение) = «НЕ ДЕЛАЙ»</p><table style="width:100%;border-collapse:collapse"><tr><th style="text-align:left;padding:4px 8px;color:#2E9E6B">✅ Утвердительная</th><th style="text-align:left;padding:4px 8px;color:#D94A77">🚫 Отрицательная</th></tr><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6">Sit down.</td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6">Don't sit down.</td></tr><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6">Stand up.</td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6">Don't stand up.</td></tr><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6">Open your book.</td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6">Don't open your book.</td></tr><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6">Close your book.</td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6">Don't close your book.</td></tr><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6">Sit down, please. 🙏</td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6">Please don't stand up. 🙏</td></tr></table></div></div>$h$::text)) where id='6f66b4f2-a50a-4eaa-b227-5443ab2434af';
update classroom_blocks set payload = jsonb_set(payload,'{html}',to_jsonb($h$<div style="max-width:680px;border:1px solid #E6E0D8;border-radius:14px;overflow:hidden;font-size:15px;line-height:1.35"><div style="background:#6F3584;color:#fff;padding:7px 12px;font-weight:700">Story Phrases</div><div style="padding:10px 12px;background:#fff"><p style="margin:0 0 8px;font-weight:700;color:#6F3584">Ключевые фразы из истории — запомни их!</p><table style="width:100%;border-collapse:collapse"><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6"><b>💬 Oh no!</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;color:#6B7280">О нет! (выражение ужаса/испуга)</td></tr><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6"><b>💬 Can you see my keys?</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;color:#6B7280">Ты видишь мои ключи?</td></tr><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6"><b>💬 Mum's keys are under the car.</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;color:#6B7280">Ключи мамы под машиной.</td></tr><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6"><b>💬 Sorry, Mum.</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;color:#6B7280">Прости, мама.</td></tr><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6"><b>💬 Mmm! I love chicken!</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;color:#6B7280">Ммм! Я люблю курицу!</td></tr><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6"><b>💬 It's not such a bad day after all!</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;color:#6B7280">В конце концов, это не такой уж плохой день!</td></tr></table></div></div>$h$::text)) where id='1de6154e-676b-4373-9693-2812cde8efdc';
update classroom_blocks set payload = jsonb_set(payload,'{html}',to_jsonb($h$<div style="max-width:680px;border:1px solid #E6E0D8;border-radius:14px;overflow:hidden;font-size:15px;line-height:1.35"><div style="background:#8A2FC9;color:#fff;padding:7px 12px;font-weight:700">📖 История: «The Zoo Keeper» — ключевые фразы</div><div style="padding:10px 12px;background:#fff"><p style="margin:6px 0;color:#6B7280;text-align:center"><i>Фразы из истории — запомни и скажи с выражением!</i></p><div style="margin:8px 0;padding:10px 12px;background:#FBF2FE;border:1px solid #E3C6F5;border-radius:10px"><p style="margin:0 0 6px;font-weight:700;color:#8A2FC9"><span style="background:#E5519B;color:#fff;border-radius:6px;padding:2px 8px;font-size:13px">Панель 2</span></p><p style="margin:6px 0">💬 <b>Let's help him! 👨</b></p><p style="margin:6px 0;color:#6B7280">Давайте поможем ему!</p><p style="margin:6px 0;color:#A14BC9">📌 <i>Let's + verb = давайте сделаем вместе!</i></p></div><div style="margin:8px 0;padding:10px 12px;background:#FBF2FE;border:1px solid #E3C6F5;border-radius:10px"><p style="margin:0 0 6px;font-weight:700;color:#8A2FC9"><span style="background:#E5519B;color:#fff;border-radius:6px;padding:2px 8px;font-size:13px">Панель 5</span></p><p style="margin:6px 0">💬 <b>Come here! 👋</b></p><p style="margin:6px 0;color:#6B7280">Иди сюда!</p><p style="margin:6px 0;color:#A14BC9">📌 <i>Императив — команда (без подлежащего!)</i></p></div><div style="margin:8px 0;padding:10px 12px;background:#FBF2FE;border:1px solid #E3C6F5;border-radius:10px"><p style="margin:0 0 6px;font-weight:700;color:#8A2FC9"><span style="background:#E5519B;color:#fff;border-radius:6px;padding:2px 8px;font-size:13px">Панель 6</span></p><p style="margin:6px 0">💬 <b>Don't throw them! 🚫</b></p><p style="margin:6px 0;color:#6B7280">Не бросай их!</p><p style="margin:6px 0;color:#A14BC9">📌 <i>Don't + verb = отрицательный императив</i></p></div><div style="margin:8px 0;padding:10px 12px;background:#FBF2FE;border:1px solid #E3C6F5;border-radius:10px"><p style="margin:0 0 6px;font-weight:700;color:#8A2FC9"><span style="background:#E5519B;color:#fff;border-radius:6px;padding:2px 8px;font-size:13px">Панель 8</span></p><p style="margin:6px 0">💬 <b>Thank you so much! 🙏</b></p><p style="margin:6px 0;color:#6B7280">Большое спасибо!</p><p style="margin:6px 0;color:#A14BC9">📌 <i>Фраза благодарности</i></p></div></div></div>$h$::text)) where id='c7226bf8-bd91-40d2-a994-efb678b0fafd';
update classroom_blocks set payload = jsonb_set(payload,'{html}',to_jsonb($h$<div style="max-width:680px;border:1px solid #E6E0D8;border-radius:14px;overflow:hidden;font-size:15px;line-height:1.35"><div style="background:#7B3090;color:#fff;padding:7px 12px;font-weight:700">Story Phrases — The Tree on the Track 🚂💬</div><div style="padding:10px 12px;background:#fff"><table style="width:100%;border-collapse:collapse"><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6"><b>💬 There's a tree on the track!</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;color:#6B7280">Дерево на рельсах!</td></tr><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6"><b>💬 Run, Flash! Stop the train!</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;color:#6B7280">Беги, Флэш! Останови поезд!</td></tr><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6"><b>💬 She's next to my train.</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;color:#6B7280">Она рядом с моим поездом.</td></tr><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6"><b>💬 Never give up! 💪</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;color:#6B7280">Никогда не сдавайся! — ценность урока</td></tr><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6"><b>💬 The ______ is next to / behind / in front of / between the ______.</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;color:#6B7280">Место находится рядом с / за / перед / между…</td></tr></table></div></div>$h$::text)) where id='3b1650f9-8b63-4975-bab9-666c3068a70b';
update classroom_blocks set payload = jsonb_set(payload,'{html}',to_jsonb($h$<div style="max-width:680px;border:1px solid #E6E0D8;border-radius:14px;overflow:hidden;font-size:15px;line-height:1.35"><div style="background:#7F2279;color:#fff;padding:7px 12px;font-weight:700">📖 Ключевые фразы: «Bad Apples»</div><div style="padding:10px 12px;background:#fff"><p style="margin:6px 0"><span style="background:#A33C9D;color:#fff;border-radius:8px;padding:3px 10px;font-size:14px">Unit 4 · Урок 4</span></p><table style="width:100%;border-collapse:collapse"><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6"><b>💬 I've got a bad apple.</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;color:#6B7280">У меня плохое яблоко.</td></tr><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6"><b>💬 I've got an idea.</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;color:#6B7280">У меня есть идея.</td></tr><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6"><b>💬 Come to the market with me.</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;color:#6B7280">Пойдём со мной на рынок.</td></tr><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6"><b>💬 Nice, sweet apples!</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;color:#6B7280">Вкусные, сладкие яблоки!</td></tr><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6"><b>💬 Well done, children!</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;color:#6B7280">Молодцы, дети!</td></tr></table></div></div>$h$::text)) where id='443e0378-745a-4611-a06e-05d5773d8a1a';
update classroom_blocks set payload = jsonb_set(payload,'{html}',to_jsonb($h$<div style="max-width:680px;border:1px solid #E6E0D8;border-radius:14px;overflow:hidden;font-size:15px;line-height:1.35"><div style="background:#6F3584;color:#fff;padding:7px 12px;font-weight:700">📖 Tidy Up!</div><div style="padding:10px 12px;background:#fff"><table style="width:100%;border-collapse:collapse"><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;text-align:center;font-size:22px">🧹</td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6"><b>💬 Tidy up your bedroom, Flash!</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;color:#6B7280">Убери в своей комнате, Флэш!</td></tr><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;text-align:center;font-size:22px">🙈</td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6"><b>💬 I don't believe it!</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;color:#6B7280">Не может быть! / Не верю своим глазам!</td></tr><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;text-align:center;font-size:22px">😔</td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6"><b>💬 Sorry, Mum. No park for me today.</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;color:#6B7280">Прости, мама. Сегодня в парк я не пойду.</td></tr><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;text-align:center;font-size:22px">🙈</td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6"><b>💬 hide</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;color:#6B7280">прятать(ся)</td></tr><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;text-align:center;font-size:22px">🏠</td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6"><b>💬 There is a book on the sofa.</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;color:#6B7280">На диване лежит книга.</td></tr><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;text-align:center;font-size:22px">🏠</td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6"><b>💬 There are socks on the lamp!</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;color:#6B7280">На лампе носки!</td></tr></table></div></div>$h$::text)) where id='5096e898-c0d4-410f-b295-ed7606485ac5';
update classroom_blocks set payload = jsonb_set(payload,'{html}',to_jsonb($h$<div style="max-width:680px;border:1px solid #E6E0D8;border-radius:14px;overflow:hidden;font-size:15px;line-height:1.35"><div style="background:#C2571A;color:#fff;padding:7px 12px;font-weight:700">📕 GRAMMAR 2 — Our / Their + Birthdays</div><div style="padding:10px 12px;background:#fff"><p style="margin:0 0 8px;font-weight:700;color:#C2571A">Говорим про дни рождения</p><div style="margin:10px 0;padding:10px 12px;background:#FFF8EF;border:1px solid #E8C9A3;border-radius:10px"><p style="margin:6px 0"><b style="color:#C2571A">OUR</b> = наши</p><p style="margin:6px 0"><b style="color:#C2571A">THEIR</b> = их</p></div><p style="margin:12px 0;padding:10px 12px;background:#B5870C;color:#fff;border-radius:8px">⚠️ Our birthdays are in November. &nbsp; Their birthdays aren't in May. &nbsp; Their birthdays are in July!</p><table style="width:100%;border-collapse:collapse"><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6"><b>✅ Our birthdays are in June. 🎂</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;color:#6B7280">Наши дни рождения в июне.</td></tr><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6"><b>✅ Their birthdays aren't in March.</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;color:#6B7280">Их дни рождения не в марте.</td></tr><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6"><b>✅ Are our birthdays in May?</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;color:#6B7280">Наши дни рождения в мае?</td></tr><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6"><b>✅ Their birthdays are in December. 🎄</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;color:#6B7280">Их дни рождения в декабре.</td></tr></table><p style="margin:0 0 8px;font-weight:700;color:#C2571A">ℹ️ 12 Months:</p><table style="width:100%;border-collapse:collapse"><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;text-align:center"><b>January</b><br><span style="color:#6B7280;font-size:14px">январь</span></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;text-align:center"><b>February</b><br><span style="color:#6B7280;font-size:14px">февраль</span></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;text-align:center"><b>March</b><br><span style="color:#6B7280;font-size:14px">март</span></td></tr><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;text-align:center"><b>April</b><br><span style="color:#6B7280;font-size:14px">апрель</span></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;text-align:center"><b>May</b><br><span style="color:#6B7280;font-size:14px">май</span></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;text-align:center"><b>June</b><br><span style="color:#6B7280;font-size:14px">июнь</span></td></tr><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;text-align:center"><b>July</b><br><span style="color:#6B7280;font-size:14px">июль</span></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;text-align:center"><b>August</b><br><span style="color:#6B7280;font-size:14px">август</span></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;text-align:center"><b>September</b><br><span style="color:#6B7280;font-size:14px">сентябрь</span></td></tr><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;text-align:center"><b>October</b><br><span style="color:#6B7280;font-size:14px">октябрь</span></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;text-align:center"><b>November</b><br><span style="color:#6B7280;font-size:14px">ноябрь</span></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;text-align:center"><b>December</b><br><span style="color:#6B7280;font-size:14px">декабрь</span></td></tr></table></div></div>$h$::text)) where id='7e901ccc-f687-4964-be04-3d50ad3b63a9';
update classroom_blocks set payload = jsonb_set(payload,'{html}',to_jsonb($h$<div style="max-width:680px;border:1px solid #E6E0D8;border-radius:14px;overflow:hidden;font-size:15px;line-height:1.35"><div style="background:#C06329;color:#fff;padding:7px 12px;font-weight:700">GRAMMAR 1 · I'd like to…</div><div style="padding:10px 12px;background:#fff"><div style="margin:10px 0;padding:10px 12px;background:#FFF8EF;border:1px solid #E8C9A3;border-radius:10px"><p style="margin:6px 0"><b>I'd like to go to [место] by [транспорт]!</b></p><p style="margin:6px 0"><b>I'd like to [drive/fly/ride/sail] a [транспорт]!</b></p></div><div style="margin:8px 0;padding:10px 12px;background:#FDF0E9;border:1px solid #E8B894;border-radius:10px"><p style="margin:0 0 6px;font-weight:700;color:#B4530F">💡 Как запомнить?</p><p style="margin:6px 0">«I'd like to» = «я хотел бы»</p></div><div style="margin:8px 0;padding:10px 12px;background:#FFFBEB;border:1px solid #F3E3B8;border-radius:10px"><p style="margin:0 0 6px;font-weight:700;color:#B4530F">⚠️ Важно запомнить!</p><p style="margin:6px 0">I'd like to go to Brazil &nbsp;<b>BY</b>&nbsp; plane ✅</p><p style="margin:6px 0">drive: car/bus/lorry/taxi · fly: plane/helicopter</p><p style="margin:6px 0">ride: bike/scooter/motorbike · sail: boat/ship</p></div><table style="width:100%;border-collapse:collapse"><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6"><b>✅ I'd like to go to Japan by ship!</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;color:#6B7280">Я бы хотел поехать в Японию на корабле!</td></tr><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6"><b>✅ I'd like to go to Brazil by plane!</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;color:#6B7280">Я бы хотела поехать в Бразилию на самолёте!</td></tr><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6"><b>✅ I'd like to fly a helicopter!</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;color:#6B7280">Я бы хотел полететь на вертолёте!</td></tr><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6"><b>✅ I'd like to ride a scooter!</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;color:#6B7280">Я бы хотела поехать на скутере!</td></tr><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6"><b>✅ I'd like to go to school by bus!</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;color:#6B7280">Я бы хотел поехать в школу на автобусе!</td></tr><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6"><b>✅ I'd like to sail a big ship!</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;color:#6B7280">Я бы хотела поплыть на большом корабле!</td></tr></table></div></div>$h$::text)) where id='b267400e-fbf6-4122-9a63-6b233bdefca8';
update classroom_blocks set payload = jsonb_set(payload,'{html}',to_jsonb($h$<div style="max-width:680px;border:1px solid #E6E0D8;border-radius:14px;overflow:hidden;font-size:15px;line-height:1.35"><div style="background:#1A7B4C;color:#fff;padding:7px 12px;font-weight:700">🌿 Environment on Holiday</div><div style="padding:10px 12px;background:#fff"><div style="margin:10px 0;padding:10px 12px;background:#EDF8F1;border:1px solid #B6DCC6;border-radius:10px">🌍 Эти слова помогут тебе говорить о природе и защите окружающей среды на каникулах!</div><table style="width:100%;border-collapse:collapse"><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;text-align:center;font-size:22px">🌿</td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6"><b>natural environment</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;color:#6B7280">природная среда / живая природа</td></tr><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;text-align:center;font-size:22px">♻️</td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6"><b>recycle</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;color:#6B7280">перерабатывать (мусор)</td></tr><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;text-align:center;font-size:22px">🗑️</td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6"><b>rubbish</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;color:#6B7280">мусор / отходы</td></tr><tr><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;text-align:center;font-size:22px">🗻</td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6"><b>path</b></td><td style="padding:4px 8px;border-bottom:1px solid #F0ECE6;color:#6B7280">тропинка / дорожка</td></tr></table><div style="margin:12px 0 0;padding:10px 12px;background:#E8F2F7;border:1px solid #AFCBDD;border-radius:10px"><p style="margin:0 0 4px;font-weight:700;color:#1A5A7B">💬 На каникулах:</p><p style="margin:0"><b>Don't drop rubbish! Walk on the path. Recycle plastic bottles!</b></p><p style="margin:4px 0 0;color:#6B7280">Не бросай мусор! Иди по тропинке. Перерабатывай пластиковые бутылки!</p></div></div></div>$h$::text)) where id='edf373e9-7fad-405a-a2cb-6b71ce8ffa52';

